# Windows WebEngine can show a blank/white compositor surface on some GPU/driver
# combinations. Prefer the software compositor when the user has not supplied
# Chromium flags explicitly; this keeps the embedded page visible instead of blank.
if platform.system() == "Windows":
    os.environ.setdefault("QTWEBENGINE_CHROMIUM_FLAGS", "--disable-gpu --disable-gpu-compositing")

# QtWebEngine is imported LAZILY, on the first webview that actually needs it.
#
# Two reasons, both measured or safety-critical:
#
# * Cost. `import PyQt6.QtWebEngineWidgets` initialises Chromium's own
#   command-line layer and costs ~81 ms of the ~671 ms `import ui` — paid on
#   every launch for a panel most sessions never open. The import now happens
#   when the embedded browser is first built, so startup does not pay it.
# * Safety. Chromium hard-aborts (an access violation at process teardown, not
#   a Python exception) in environments that cannot host it — offscreen/headless
#   runs and the test harnesses among them. Deferring the import means a run
#   that never opens a webview never starts Chromium at all.
#
# Every WebEngine surface already degrades gracefully (`_WEB_OK` False → the
# panel shows an "install WebEngine" notice), so a failure here still costs one
# feature rather than the process.
QWebEngineView = QWebEnginePage = QWebEngineSettings = None
_WEB_OK = None            # None = not yet attempted; True/False = decided
_WEB_LOCK = threading.Lock()


def _load_webengine() -> bool:
    """Import QtWebEngine on first use — exactly once, thread-safe.

    Returns True when the embedded browser is usable. Honours
    ``JARVIS_DISABLE_WEBENGINE`` (used by the test harness) as before.
    """
    global QWebEngineView, QWebEnginePage, QWebEngineSettings, _WEB_OK
    if _WEB_OK is not None:
        return bool(_WEB_OK)
    with _WEB_LOCK:
        if _WEB_OK is not None:
            return bool(_WEB_OK)
        try:
            if os.environ.get("JARVIS_DISABLE_WEBENGINE", "").strip().lower() in ("1", "true", "yes"):
                raise ImportError("QtWebEngine disabled by JARVIS_DISABLE_WEBENGINE")
            from PyQt6.QtWebEngineWidgets import QWebEngineView as _QWEV
            from PyQt6.QtWebEngineCore import QWebEnginePage as _QWEP, QWebEngineSettings as _QWES
            QWebEngineView, QWebEnginePage, QWebEngineSettings = _QWEV, _QWEP, _QWES
            _WEB_OK = True
        except Exception as _exc:
            QWebEngineView = QWebEnginePage = QWebEngineSettings = None
            _WEB_OK = False
            print(f"[JARVIS] WebView engine unavailable: {_exc}")
    return bool(_WEB_OK)


def _web_ready() -> bool:
    """True when the embedded browser can be built (loads it on first ask)."""
    return bool(_WEB_OK) if _WEB_OK is not None else _load_webengine()

