        # it updates on actual state transitions and hides when idle.
        self._chat_activity = QLabel('')
        self._chat_activity.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self._chat_activity.setStyleSheet(
            f'color:{C.PRI};font:800 7pt "Exo 2";'
            f'background:rgba(4,36,55,170);'
            f'border:1px solid rgba(74,196,239,130);border-radius:5px;'
            f'padding:3px 10px;letter-spacing:1.5px;'
        )
        self._chat_activity.hide()
        lay.addWidget(self._chat_activity)

        # The realtime microphone transcript is rendered directly into the one
        # existing command textbox below (`self.input`) — there is no separate
