def _paint_tab_icon(p: 'QPainter', key: str, rect: 'QRectF', color, size: float = 14.0) -> None:
    ops = _TAB_ICON_DEFS.get(key)
    if not ops:
        return
    p.save()
    pen = QPen(QColor(color), 1.7, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin)
    p.setPen(pen)
    p.setBrush(Qt.BrushStyle.NoBrush)
    s = size / 24.0
    ox = rect.left() + (rect.width() - size) / 2.0
    oy = rect.top() + (rect.height() - size) / 2.0
    p.translate(ox, oy)
    p.scale(s, s)
    for op in ops:
        kind = op[0]
        if kind == 'path':
            p.drawPath(_svg_path_to_qpp(op[1]))
        elif kind == 'line':
            _, x1, y1, x2, y2 = op
            p.drawLine(QPointF(x1, y1), QPointF(x2, y2))
        elif kind == 'circle':
            _, ccx, ccy, r = op
            p.drawEllipse(QPointF(ccx, ccy), r, r)
        elif kind == 'rrect':
            _, rx0, ry0, rw, rh, rr = op
            p.drawRoundedRect(QRectF(rx0, ry0, rw, rh), rr, rr)
        elif kind == 'rect':
            _, rx0, ry0, rw, rh, rr = op
            p.drawRoundedRect(QRectF(rx0, ry0, rw, rh), rr, rr)
    p.restore()


# =====================================================================
#  JARVIS ICON BUTTONS — QPainter ports of the movingicons.dev SVG set
#  (mic-off & arrow-big-right). Original Svelte components converted to
#  PyQt6 with the same hover animations.
# =====================================================================
class _MicIconButton(QPushButton):
    """Mic-off SVG rendered with QPainter. Hover shakes horizontally for
    600 ms — the same gesture as the Svelte original."""
    def __init__(self, parent=None, size=22, color=None):
        super().__init__(parent)
        self._size = int(size)
        self._color = color or C.PRI
        self._hover = False
        self._shake_t = 0.0
        self._shake_on = False
        self.setFixedSize(self._size + 18, self._size + 18)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFlat(True)
        self.setStyleSheet("background:transparent;border:none;padding:0;")
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._tick)
        self._timer.start(16)

    def enterEvent(self, e):
        self._hover = True
        self._shake_on = True
        self._shake_t = 0.0
        QTimer.singleShot(600, lambda: setattr(self, "_shake_on", False))
        self.update(); super().enterEvent(e)

    def leaveEvent(self, e):
        self._hover = False; self.update(); super().leaveEvent(e)

    def _tick(self):
        if self._shake_on:
            self._shake_t += 0.016
        self.update()

    def _offset_x(self) -> float:
        if not self._shake_on:
            return 0.0
        p = (self._shake_t / 0.6) % 1.0
        amp = 0.07 * (self._size + 18)
        return math.sin(p * math.pi * 6.0) * amp * (1.0 - p)

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        col = QColor(C.WHITE if self._hover else self._color)
        pen = QPen(col, 2.0, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin)
        p.setPen(pen); p.setBrush(Qt.BrushStyle.NoBrush)

        s = self._size / 24.0
        ox = self.width() / 2.0 - self._size / 2.0 + self._offset_x()
        oy = self.height() / 2.0 - self._size / 2.0
        p.translate(ox, oy); p.scale(s, s)

        p.drawLine(QPointF(2, 2), QPointF(22, 22))

        path1 = QPainterPath()
        path1.moveTo(18.89, 13.23)
        path1.arcTo(QRectF(2.0, 5.0, 17.0, 14.0), 20, 80)
        path1.lineTo(19, 12); path1.lineTo(19, 10)
        p.drawPath(path1)

        path2 = QPainterPath()
        path2.moveTo(5, 10); path2.lineTo(5, 12)
        path2.arcTo(QRectF(5.0, 5.0, 14.0, 14.0), 180, 60)
        path2.lineTo(17, 17)
        p.drawPath(path2)

        path3 = QPainterPath()
        path3.moveTo(15, 9.34); path3.lineTo(15, 5)
        path3.arcTo(QRectF(9.32, 2.0, 5.68, 6.0), 180, 180)
        path3.lineTo(9.32, 3.67)
        p.drawPath(path3)

        path4 = QPainterPath()
        path4.moveTo(9, 9); path4.lineTo(9, 12)
        path4.arcTo(QRectF(9.0, 9.0, 6.0, 6.0), 180, 60)
        path4.lineTo(14.12, 14.12)
        p.drawPath(path4)

        p.drawLine(QPointF(12, 19), QPointF(12, 22))
        p.end()


class _SendIconButton(QPushButton):
    """'arrow-big-right' SVG rendered with QPainter. Hover slides +3 px.

    While a request is in flight the same control becomes the STOP/interrupt
    button: the glyph switches to a filled square (the universal stop mark) in
    the alert red, and clicking it cancels the running turn instead of sending.
    """
    def __init__(self, parent=None, size=22, color=None):
        super().__init__(parent)
        self._size = int(size)
        self._color = color or C.PRI
        self._hover = False
        self._stop = False
        self.setFixedSize(self._size + 18, self._size + 18)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFlat(True)
        self.setStyleSheet("background:transparent;border:none;padding:0;")
        # Start self-describing: Send glyph, Send tooltip, Send accessible name.
        self.set_stop_mode(False)

    def set_stop_mode(self, on: bool) -> None:
        """Switch the glyph/handler between Send (arrow) and Stop (square)."""
        self._stop = bool(on)
        self.setAccessibleName('Stop' if self._stop else 'Send')
        self.setToolTip('Stop / interrupt J.A.R.V.I.S.' if self._stop
                        else 'Send command')
        self.update()

    def is_stop_mode(self) -> bool:
        return bool(self._stop)

    def enterEvent(self, e):
        self._hover = True; self.update(); super().enterEvent(e)

    def leaveEvent(self, e):
        self._hover = False; self.update(); super().leaveEvent(e)

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        if self._stop:
            col = QColor(C.WHITE if self._hover else C.RED)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(col)
            side = self._size * 0.52
            p.drawRoundedRect(QRectF(self.width() / 2.0 - side / 2.0,
                                     self.height() / 2.0 - side / 2.0,
                                     side, side), 2.5, 2.5)
            p.end()
            return
        col = QColor(C.WHITE if self._hover else self._color)
        p.setPen(QPen(col, 2.0, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.setBrush(Qt.BrushStyle.NoBrush)
        s = self._size / 24.0
        ox = self.width() / 2.0 - self._size / 2.0 + (3.0 if self._hover else 0.0)
        oy = self.height() / 2.0 - self._size / 2.0
        p.translate(ox, oy); p.scale(s, s)
        path = QPainterPath()
        path.moveTo(6, 9); path.lineTo(12, 9); path.lineTo(12, 5)
        path.lineTo(19, 12); path.lineTo(12, 19); path.lineTo(12, 15)
        path.lineTo(6, 15); path.closeSubpath()
        p.drawPath(path)
        p.end()



class _ImportIconButton(QPushButton):
    """Icon-only Import (attach) button rendered with QPainter.

    No visible text, matching the mic/send controls it sits between: clicking
    it (or dropping a file on the chat) attaches a file and previews it.
    """

    def __init__(self, parent=None, size=22, color=None):
        super().__init__(parent)
        self._size = int(size)
        self._color = color or C.PRI
        self._hover = False
        self.setFixedSize(self._size + 18, self._size + 18)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFlat(True)
        self.setStyleSheet("background:transparent;border:none;padding:0;")

    def enterEvent(self, e):
        self._hover = True; self.update(); super().enterEvent(e)

    def leaveEvent(self, e):
        self._hover = False; self.update(); super().leaveEvent(e)

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        col = QColor(C.WHITE if self._hover else self._color)
        p.setPen(QPen(col, 1.7, Qt.PenStyle.SolidLine,
                      Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.setBrush(Qt.BrushStyle.NoBrush)
        s = self._size / 24.0
        ox = self.width() / 2.0 - self._size / 2.0
        oy = self.height() / 2.0 - self._size / 2.0
        p.translate(ox, oy); p.scale(s, s)
        # A slim paperclip: two nested rounded arcs joined at the bottom.
        p.drawLine(QPointF(15.5, 8.5), QPointF(15.5, 15.0))
        p.drawLine(QPointF(8.5, 7.5), QPointF(8.5, 16.5))
        path = QPainterPath()
        path.moveTo(8.5, 7.5)
        path.arcTo(QRectF(8.5, 3.5, 7.0, 7.0), 180.0, -180.0)
        path.lineTo(15.5, 15.0)
        path.arcTo(QRectF(11.0, 13.0, 6.5, 6.5), 0.0, -180.0)
        p.drawPath(path)
        p.end()


class _VisionCornerButton(QPushButton):
    """Icon-only HUD button that floats over the Vision camera surface.

    There is no caption: the glyph *is* the control, painted from the shared
    tab-icon set so it reads as part of the camera HUD. ``checked`` holds the
    active tint, which is what makes the drawer handle look engaged while the
    rail is open.
    """

    def __init__(self, icon: str, parent=None, tip: str = '', tint=None, size: int = 34,
                 checkable: bool = False):
        super().__init__(parent)
        self._icon_key = icon
        self._tint = QColor(tint) if tint is not None else QColor(C.PRI)
        self._hover = False
        self.setFixedSize(int(size), int(size))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setToolTip(tip)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.setMouseTracking(True)
        self.setCheckable(bool(checkable))
        self.setStyleSheet('background:transparent;border:none;padding:0;')
        self._flat_visual = True

    def enterEvent(self, e):
        self._hover = True
        self.update()
        super().enterEvent(e)

    def leaveEvent(self, e):
        self._hover = False
        self.update()
        super().leaveEvent(e)

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.rect()).adjusted(1.0, 1.0, -1.0, -1.0)
        active = self.isChecked() or self._hover
        # These corner controls deliberately have no background or border/stroke.
        glyph = QColor(245, 253, 255, 255) if active else QColor(self._tint)
        _paint_tab_icon(p, self._icon_key, r.adjusted(7.0, 7.0, -7.0, -7.0), glyph, size=15.0)
        p.end()


class _VisionSwitch(QCheckBox):
    """Text-first Vision switch used inside the left scroll control surface.

    Symbols/icons are intentionally removed from the visible label.  The full
    control is wide enough to show its name and the switch itself, while the
    containing QScrollArea keeps the Vision stage compact.
    """
    def __init__(self, text: str, parent=None, icon: str = "", tip: str = ""):
        super().__init__(text, parent)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFixedHeight(32)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.setToolTip(tip or text)
        # Preserve compatibility with existing call sites that still pass icon=.
        self._icon_only = False
        self.setStyleSheet(f"""
            QCheckBox {{
                color:{C.TEXT_MED}; background:rgba(1,15,25,95); border:1px solid rgba(67,170,199,45);
                border-radius:7px; font:900 8.8pt 'Exo 2'; letter-spacing:0.75px;
                spacing:10px; padding:4px 9px;
            }}
            QCheckBox:hover {{
                color:{C.WHITE}; border-color:rgba(88,214,245,120);
                background:rgba(0,72,96,70);
            }}
            QCheckBox:checked {{
                color:{C.WHITE}; border-color:{C.PRI};
                background:rgba(0,134,184,92);
            }}
            QCheckBox::indicator {{
                width:34px; height:17px; border-radius:9px;
                background:rgba(8,24,34,220);
                border:1px solid rgba(60,156,190,110);
            }}
            QCheckBox::indicator:hover {{ border-color:{C.PRI}; }}
            QCheckBox::indicator:checked {{
                background:rgba(0,150,200,220); border-color:{C.PRI};
            }}
            QCheckBox:disabled {{ color:#365664; }}
            QCheckBox::indicator:disabled {{
                background:rgba(8,16,21,120); border-color:rgba(50,70,78,90);
            }}
        """)


class _InferenceControlPanel(QFrame):
    """Dedicated expandable object-inference control surface.

    Groups the *real* inference controls — CONFIDENCE GATE, OVERLAP GATE (IoU),
    INFERENCE SCALE, INFERENCE CORE (device), OBJECT LIMIT, PERSON MODE and a
    searchable CLASS FILTER built from the loaded model's own class names. Every
    control drives the live detector; nothing here is decorative. The class
    list stays empty until a model actually reports its classes, so it can never
    show classes the running model does not have.
    """

    options_changed = pyqtSignal()

    _SCALES = (320, 416, 512, 640, 960)
    _LIMITS = (10, 20, 40, 80, 120)
    _CORES = (('AUTO', 'auto'), ('CPU', 'cpu'), ('CUDA', 'cuda'))
    _PERSON = (('ALL OBJECTS', 'all'), ('PERSON ONLY', 'only'), ('EXCLUDE PERSON', 'exclude'))

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setObjectName('InferenceControlPanel')
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setStyleSheet(
            'QFrame#InferenceControlPanel { background:transparent; border:none; }'
            'QLabel { background:transparent; border:none; }'
        )
        self._class_names: list = []
        self._suppress = False

        combo_css = (
            f'QComboBox {{ color:{C.WHITE}; background:rgba(1,15,25,200);'
            f' border:1px solid rgba(67,170,199,70); border-radius:6px;'
            f' padding:2px 7px; font:800 8pt "Exo 2"; }}'
            f'QComboBox:hover {{ border-color:{C.PRI}; }}'
            f'QComboBox::drop-down {{ border:none; width:14px; }}'
            f'QComboBox QAbstractItemView {{ color:{C.WHITE}; background:#04121c;'
            f' border:1px solid {C.PRI}; selection-background-color:rgba(0,134,184,150);'
            f' font:800 8pt "Exo 2"; }}'
            f'QComboBox:disabled {{ color:#3a5a68; border-color:rgba(50,70,78,90); }}'
        )
        title_css = (f'color:{C.TEXT_DIM}; font:800 6.4pt "Orbitron";'
                     f' letter-spacing:0.9px;')
        val_css = (f'color:{C.PRI}; font:800 7.4pt "Share Tech Mono";'
                   f' background:transparent;')

        root = QVBoxLayout(self)
        root.setContentsMargins(0, 4, 0, 0)
        root.setSpacing(0)

        # ── expandable header ──────────────────────────────────────────────
        self._header = QPushButton('OBJECT INFERENCE   ⌄')
        self._header.setCheckable(True)
        self._header.setChecked(True)
        self._header.setCursor(Qt.CursorShape.PointingHandCursor)
        self._header.setToolTip('Show / hide the live inference controls')
        self._header.setAccessibleName('OBJECT INFERENCE control panel')
        self._header.setStyleSheet(
            f'QPushButton {{ color:{C.PRI}; background:rgba(0,72,96,60);'
            f' border:1px solid rgba(67,170,199,70); border-radius:7px;'
            f' font:900 8pt "Orbitron"; letter-spacing:1.0px; padding:5px 8px;'
            f' text-align:left; }}'
            f'QPushButton:hover {{ border-color:{C.PRI}; background:rgba(0,110,150,90); }}'
        )
        self._header.toggled.connect(self._on_header_toggle)
        root.addWidget(self._header)

        # ── body ───────────────────────────────────────────────────────────
        self._body = QWidget(self)
        body = QVBoxLayout(self._body)
        body.setContentsMargins(3, 7, 3, 3)
        body.setSpacing(8)

        # CONFIDENCE GATE
        self._conf_lbl = QLabel('CONFIDENCE GATE'); self._conf_lbl.setStyleSheet(title_css)
        self._conf_val = QLabel('0.45'); self._conf_val.setStyleSheet(val_css)
        self._conf_val.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        crow = QHBoxLayout(); crow.setContentsMargins(0, 0, 0, 0); crow.addWidget(self._conf_lbl, 1); crow.addWidget(self._conf_val)
        self._conf = QSlider(Qt.Orientation.Horizontal); self._conf.setRange(10, 90)
        self._conf.setValue(45); self._conf.setStyleSheet(_theme_slider_css())
        self._conf.setToolTip('Minimum detection confidence fed to the model')
        self._conf.setAccessibleName('CONFIDENCE GATE')
        body.addLayout(crow); body.addWidget(self._conf)

        # OVERLAP GATE (IoU)
        self._iou_lbl = QLabel('OVERLAP GATE'); self._iou_lbl.setStyleSheet(title_css)
        self._iou_val = QLabel('IOU 0.45'); self._iou_val.setStyleSheet(val_css)
        self._iou_val.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        irow = QHBoxLayout(); irow.setContentsMargins(0, 0, 0, 0); irow.addWidget(self._iou_lbl, 1); irow.addWidget(self._iou_val)
        self._iou = QSlider(Qt.Orientation.Horizontal); self._iou.setRange(5, 95)
        self._iou.setValue(45); self._iou.setStyleSheet(_theme_slider_css())
        self._iou.setToolTip('Non-maximum-suppression IoU threshold')
        self._iou.setAccessibleName('OVERLAP GATE')
        body.addLayout(irow); body.addWidget(self._iou)

        # INFERENCE SCALE
        body.addWidget(self._mini_title('INFERENCE SCALE', title_css))
        self._scale = QComboBox(); self._scale.setStyleSheet(combo_css)
        for s in self._SCALES:
            self._scale.addItem(str(s), s)
        self._select_by_data(self._scale, 640)
        self._scale.setToolTip('Model image-size (imgsz) used for inference')
        self._scale.setAccessibleName('INFERENCE SCALE')
        body.addWidget(self._scale)

        # INFERENCE CORE
        crow2 = QHBoxLayout(); crow2.setContentsMargins(0, 0, 0, 0)
        crow2.addWidget(self._mini_title('INFERENCE CORE', title_css), 1)
        self._dev_readout = QLabel('DEVICE · —'); self._dev_readout.setStyleSheet(val_css)
        self._dev_readout.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        crow2.addWidget(self._dev_readout)
        body.addLayout(crow2)
        self._core = QComboBox(); self._core.setStyleSheet(combo_css)
        for label, val in self._CORES:
            self._core.addItem(label, val)
        self._select_by_data(self._core, 'auto')
        self._core.setToolTip('Requested inference device; the readout shows the device actually in use')
        self._core.setAccessibleName('INFERENCE CORE')
        body.addWidget(self._core)

        # OBJECT LIMIT
        body.addWidget(self._mini_title('OBJECT LIMIT', title_css))
        self._limit = QComboBox(); self._limit.setStyleSheet(combo_css)
        for n in self._LIMITS:
            self._limit.addItem(str(n), n)
        self._select_by_data(self._limit, 20)
        self._limit.setToolTip('Maximum detections per frame (max_det)')
        self._limit.setAccessibleName('OBJECT LIMIT')
        body.addWidget(self._limit)

        # PERSON MODE
        body.addWidget(self._mini_title('PERSON MODE', title_css))
        self._person = QComboBox(); self._person.setStyleSheet(combo_css)
        for label, val in self._PERSON:
            self._person.addItem(label, val)
        self._select_by_data(self._person, 'all')
        self._person.setToolTip('Filter detections by the model\'s real person class')
        self._person.setAccessibleName('PERSON MODE')
        body.addWidget(self._person)

        # CLASS FILTER
        chead = QHBoxLayout(); chead.setContentsMargins(0, 0, 0, 0)
        chead.addWidget(self._mini_title('CLASS FILTER', title_css), 1)
        self._class_count = QLabel('—'); self._class_count.setStyleSheet(val_css)
        chead.addWidget(self._class_count)
        body.addLayout(chead)
        self._class_search = QLineEdit(); self._class_search.setPlaceholderText('SEARCH CLASSES…')
        self._class_search.setClearButtonEnabled(True)
        self._class_search.setToolTip('Search the loaded model\'s classes')
        self._class_search.setAccessibleName('CLASS FILTER search')
        self._class_search.setStyleSheet(
            f'QLineEdit {{ color:{C.WHITE}; background:rgba(1,15,25,200);'
            f' border:1px solid rgba(67,170,199,70); border-radius:6px;'
            f' padding:2px 7px; font:700 7.6pt "Share Tech Mono"; }}'
            f'QLineEdit:focus {{ border-color:{C.PRI}; }}'
        )
        self._class_search.textChanged.connect(self._apply_class_search)
        body.addWidget(self._class_search)

        self._class_list = QListWidget(); self._class_list.setToolTip('Toggle which classes the model may report')
        self._class_list.setAccessibleName('CLASS FILTER list')
        self._class_list.setMinimumHeight(96); self._class_list.setMaximumHeight(150)
        self._class_list.setStyleSheet(
            f'QListWidget {{ color:{C.TEXT_MED}; background:rgba(1,12,20,200);'
            f' border:1px solid rgba(67,170,199,55); border-radius:6px;'
            f' font:700 7.6pt "Share Tech Mono"; padding:2px; }}'
            f'QListWidget::item {{ padding:1px 3px; }}'
            f'QListWidget::item:hover {{ background:rgba(0,72,96,90); }}'
        )
        self._class_list.itemChanged.connect(self._on_class_item_changed)
        body.addWidget(self._class_list)

        qrow = QHBoxLayout(); qrow.setContentsMargins(0, 0, 0, 0); qrow.setSpacing(6)
        self._all_btn = self._mini_button('ALL')
        self._none_btn = self._mini_button('CLEAR')
        self._all_btn.clicked.connect(lambda _=False: self._set_all_classes(True))
        self._none_btn.clicked.connect(lambda _=False: self._set_all_classes(False))
        qrow.addWidget(self._all_btn); qrow.addWidget(self._none_btn); qrow.addStretch(1)
        self._class_hint = QLabel('ALL CLASSES WHEN EMPTY'); self._class_hint.setStyleSheet(
            f'color:{C.TEXT_DIM}; font:700 6pt "Share Tech Mono";')
        qrow.addWidget(self._class_hint)
        body.addLayout(qrow)

        root.addWidget(self._body)

        # ── signal wiring ──────────────────────────────────────────────────
        self._conf.valueChanged.connect(self._on_value_changed)
        self._iou.valueChanged.connect(self._on_value_changed)
        self._scale.currentIndexChanged.connect(self._on_value_changed)
        self._core.currentIndexChanged.connect(self._on_value_changed)
        self._limit.currentIndexChanged.connect(self._on_value_changed)
        self._person.currentIndexChanged.connect(self._on_value_changed)
        self._update_readouts()

    # ── small builders ─────────────────────────────────────────────────────
    @staticmethod
    def _mini_title(text, css):
        lbl = QLabel(text); lbl.setStyleSheet(css); return lbl

    @staticmethod
    def _mini_button(text):
        b = QPushButton(text)
        b.setCursor(Qt.CursorShape.PointingHandCursor)
        b.setFixedHeight(18)
        b.setStyleSheet(
            f'QPushButton {{ color:{C.TEXT_MED}; background:rgba(1,15,25,180);'
            f' border:1px solid rgba(67,170,199,60); border-radius:5px;'
            f' font:800 6.4pt "Exo 2"; padding:0 7px; }}'
            f'QPushButton:hover {{ color:{C.WHITE}; border-color:{C.PRI}; }}'
        )
        return b

    @staticmethod
    def _select_by_data(combo, data):
        idx = combo.findData(data)
        if idx >= 0:
            combo.setCurrentIndex(idx)

    # ── expand / collapse ──────────────────────────────────────────────────
    def _on_header_toggle(self, on):
        self._body.setVisible(bool(on))
        self._header.setText('OBJECT INFERENCE   ' + ('⌄' if on else '›'))

    def set_expanded(self, on: bool):
        self._header.setChecked(bool(on))

    # ── readouts ───────────────────────────────────────────────────────────
    def _update_readouts(self):
        self._conf_val.setText(f'{self._conf.value() / 100.0:.2f}')
        self._iou_val.setText(f'IOU {self._iou.value() / 100.0:.2f}')

    def _on_value_changed(self, *_a):
        self._update_readouts()
        if not self._suppress:
            self.options_changed.emit()

    # ── class filter ───────────────────────────────────────────────────────
    def set_class_names(self, names):
        names = [str(n) for n in (names or [])]
        if not names or names == self._class_names:
            return
        prior = self.selected_class_ids()
        self._class_names = names
        self._class_list.blockSignals(True)
        self._class_list.clear()
        for i, n in enumerate(names):
            it = QListWidgetItem(f'{i:02d}  {str(n).upper()}')
            it.setFlags(it.flags() | Qt.ItemFlag.ItemIsUserCheckable)
            it.setData(Qt.ItemDataRole.UserRole, i)
            checked = (i in prior) if prior else True
            it.setCheckState(Qt.CheckState.Checked if checked else Qt.CheckState.Unchecked)
            self._class_list.addItem(it)
        self._class_list.blockSignals(False)
        self._apply_class_search()
        self._update_class_count()

    def selected_class_ids(self) -> list:
        ids = []
        for i in range(self._class_list.count()):
            it = self._class_list.item(i)
            if it is not None and it.checkState() == Qt.CheckState.Checked:
                try:
                    ids.append(int(it.data(Qt.ItemDataRole.UserRole)))
                except (TypeError, ValueError):
                    pass
        return ids

    def set_selected_class_ids(self, ids):
        want = {int(i) for i in (ids or [])}
        self._class_list.blockSignals(True)
        for i in range(self._class_list.count()):
            it = self._class_list.item(i)
            try:
                cid = int(it.data(Qt.ItemDataRole.UserRole))
            except (TypeError, ValueError):
                continue
            it.setCheckState(Qt.CheckState.Checked if cid in want else Qt.CheckState.Unchecked)
        self._class_list.blockSignals(False)
        self._update_class_count()

    def _set_all_classes(self, on: bool):
        self._class_list.blockSignals(True)
        for i in range(self._class_list.count()):
            it = self._class_list.item(i)
            if it is not None and not it.isHidden():
                it.setCheckState(Qt.CheckState.Checked if on else Qt.CheckState.Unchecked)
        self._class_list.blockSignals(False)
        self._update_class_count()
        if not self._suppress:
            self.options_changed.emit()

    def _on_class_item_changed(self, *_a):
        self._update_class_count()
        if not self._suppress:
            self.options_changed.emit()

    def _update_class_count(self):
        total = self._class_list.count()
        sel = len(self.selected_class_ids())
        if total <= 0:
            self._class_count.setText('—')
        elif sel == 0 or sel == total:
            self._class_count.setText(f'ALL {total}')
        else:
            self._class_count.setText(f'{sel}/{total}')

    def _apply_class_search(self, text: str = None):
        needle = (self._class_search.text() if text is None else text).strip().lower()
        for i in range(self._class_list.count()):
            it = self._class_list.item(i)
            it.setHidden(bool(needle) and needle not in it.text().lower())

    # ── aggregate state ────────────────────────────────────────────────────
    def values(self) -> dict:
        total = self._class_list.count()
        ids = self.selected_class_ids()
        classes = ids if (total and 0 < len(ids) < total) else []
        return {
            'confidence': self._conf.value() / 100.0,
            'iou': self._iou.value() / 100.0,
            'imgsz': int(self._scale.currentData()),
            'device': str(self._core.currentData()),
            'max_det': int(self._limit.currentData()),
            'person_mode': str(self._person.currentData()),
            'classes': classes,
        }

    def set_values(self, *, confidence=None, iou=None, imgsz=None, device=None,
                   max_det=None, person_mode=None):
        self._suppress = True
        try:
            if confidence is not None:
                self._conf.setValue(int(round(float(confidence) * 100.0)))
            if iou is not None:
                self._iou.setValue(int(round(float(iou) * 100.0)))
            if imgsz is not None:
                self._select_by_data(self._scale, int(imgsz))
            if device is not None:
                self._select_by_data(self._core, str(device).lower())
            if max_det is not None:
                self._select_by_data(self._limit, int(max_det))
            if person_mode is not None:
                self._select_by_data(self._person, str(person_mode).lower())
            self._update_readouts()
        finally:
            self._suppress = False

    def set_person_mode(self, mode: str, block: bool = False):
        prev = self._suppress
        self._suppress = bool(block) or prev
        try:
            self._select_by_data(self._person, str(mode).lower())
        finally:
            self._suppress = prev

    def set_device_readout(self, text: str):
        self._dev_readout.setText(f'DEVICE · {str(text or "—").upper()}')

    def set_active(self, on: bool):
        """Enable the controls only when object inference can actually run."""
        for w in (self._conf, self._iou, self._scale, self._core, self._limit,
                  self._person, self._class_search, self._class_list,
                  self._all_btn, self._none_btn):
            w.setEnabled(bool(on))
        tip = None if on else 'Enable OBJECT ENGINE or SCENE RADAR to use inference controls'
        for w in (self._conf, self._iou, self._scale, self._core, self._limit, self._person):
            if tip is not None:
                w.setToolTip(tip)


class _ActivityRow(QFrame):
    """Clickable ReferenceDashboard activity row with full-detail expansion.

    The compact line shows the same live summary as before. Clicking the row
    opens an embedded detail area containing the untruncated activity payload
    and the most recent entries for that category, so long search queries,
    code targets, URLs, file paths, and folder paths remain inspectable.
    """

    expanded_changed = pyqtSignal(bool)

    def __init__(self, category: str, parent=None):
        super().__init__(parent)
        self._category = str(category or '').upper()
        self._history: list[tuple[str, str]] = []
        self._active = False
        self._expanded = False
        self.setObjectName(f'DoingRow_{self._category}')
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setToolTip('Click to expand full activity details')

        root = QVBoxLayout(self)
        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(0)

        self._header = QFrame(self)
        self._header.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self._header.setCursor(Qt.CursorShape.PointingHandCursor)
        header_l = QHBoxLayout(self._header)
        header_l.setContentsMargins(0, 0, 3, 0)
        header_l.setSpacing(5)

        self.category_label = QLabel(self._category, self._header)
        self.category_label.setFixedWidth(52)
        self.category_label.setAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
        self.category_label.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        header_l.addWidget(self.category_label, 0)

        self.detail_label = QLabel('—', self._header)
        self.detail_label.setAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
        self.detail_label.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        header_l.addWidget(self.detail_label, 1)

        self._chevron = QLabel('›', self._header)
        self._chevron.setFixedWidth(10)
        self._chevron.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self._chevron.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        header_l.addWidget(self._chevron, 0)
        root.addWidget(self._header)

        self._details = QFrame(self)
        self._details.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        details_l = QVBoxLayout(self._details)
        details_l.setContentsMargins(6, 5, 6, 6)
        details_l.setSpacing(3)

        self._details_title = QLabel('FULL ACTIVITY', self._details)
        details_l.addWidget(self._details_title)

        self._details_text = QTextBrowser(self._details)
        self._details_text.setReadOnly(True)
        self._details_text.setOpenExternalLinks(True)
        self._details_text.setFrameShape(QFrame.Shape.NoFrame)
        self._details_text.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self._details_text.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self._details_text.setMinimumHeight(0)
        self._details_text.setMaximumHeight(150)
        self._details_text.setStyleSheet(
            f'QTextBrowser {{ background:rgba(1,14,24,175); border:1px solid rgba(88,214,245,55); '
            f'border-radius:5px; color:{C.WHITE}; padding:4px; font:700 6pt "Share Tech Mono"; }}'
            f'QScrollBar:vertical {{ width:5px; background:transparent; border:none; }}'
            f'QScrollBar::handle:vertical {{ background:rgba(88,214,245,100); border-radius:2px; min-height:18px; }}'
        )
        details_l.addWidget(self._details_text)
        self._details.hide()
        root.addWidget(self._details)

        self.setStyleSheet(
            f'QFrame#DoingRow_{self._category} {{ background:rgba(0,212,255,0); border:none; '
            f'border-bottom:1px solid rgba(63,153,184,45); }}'
            'QLabel { background:transparent; border:none; }'
        )
        self.category_label.setStyleSheet(
            f'color:{C.PRI}; font:900 6.15pt "Orbitron"; letter-spacing:0.65px;')
        self.detail_label.setStyleSheet(
            f'color:{C.TEXT_DIM}; font:700 6.35pt "Share Tech Mono"; letter-spacing:0.15px;')
        self._chevron.setStyleSheet(
            f'color:{C.TEXT_DIM}; font:900 9pt "Exo 2"; background:transparent;')
        self._details_title.setStyleSheet(
            f'color:{C.PRI}; font:900 5.2pt "Orbitron"; letter-spacing:0.9px; background:transparent;')

        self.setFixedHeight(24)
        self._header.mousePressEvent = self._header_mouse_press

    def _header_mouse_press(self, event) -> None:
        if event.button() == Qt.MouseButton.LeftButton:
            self.toggle_expanded()
            event.accept()
            return
        event.ignore()

    def mousePressEvent(self, event) -> None:
        if event.button() == Qt.MouseButton.LeftButton:
            self.toggle_expanded()
            event.accept()
            return
        super().mousePressEvent(event)

    @staticmethod
    def _escape(value: str) -> str:
        import html
        return html.escape(str(value or ''), quote=False)

    def _render_details(self) -> None:
        if not self._history:
            body = '<span style="color:#6d8791;">No activity details captured yet.</span>'
        else:
            latest = self._history[-1]
            blocks = [
                '<div style="color:#58d6f5;font-weight:700;">LIVE / LATEST</div>',
                f'<div style="color:#ffffff;">{self._escape(latest[1])}</div>',
            ]
            if len(self._history) > 1:
                blocks.append('<div style="color:#58d6f5;font-weight:700;margin-top:6px;">RECENT</div>')
                for stamp, detail in reversed(self._history[:-1][-6:]):
                    blocks.append(
                        f'<div style="color:#6d8791;">{self._escape(stamp)}</div>'
                        f'<div style="color:#d8e7eb;margin-bottom:4px;">{self._escape(detail)}</div>'
                    )
            body = ''.join(blocks)
        self._details_text.setHtml(body)

    def set_activity_detail(self, detail: str) -> None:
        detail = str(detail or '').strip()
        if not detail:
            return
        stamp = time.strftime('%H:%M:%S')
        if not self._history or self._history[-1][1] != detail:
            self._history.append((stamp, detail))
            self._history = self._history[-10:]
        self._active = True
        preview = detail.replace('\n', ' ')
        self.detail_label.setText(preview[:30].rstrip() + ('…' if len(preview) > 30 else ''))
        self.detail_label.setStyleSheet(
            f'color:{C.WHITE}; font:700 6.35pt "Share Tech Mono"; letter-spacing:0.15px;')
        self._render_details()
        self.update()

    def set_inactive(self) -> None:
        self._active = False
        self.detail_label.setText('—')
        self.detail_label.setStyleSheet(
            f'color:{C.TEXT_DIM}; font:700 6.35pt "Share Tech Mono"; letter-spacing:0.15px;')
        self._render_details()
        self.update()

    def toggle_expanded(self) -> None:
        self._expanded = not self._expanded
        self._details.setVisible(self._expanded)
        self._chevron.setText('⌄' if self._expanded else '›')
        self._chevron.setStyleSheet(
            f'color:{C.PRI if self._expanded else C.TEXT_DIM}; font:900 8pt "Exo 2"; background:transparent;')
        self.setFixedHeight(125 if self._expanded else 24)
        if self._expanded:
            self._render_details()
        self.expanded_changed.emit(self._expanded)
        self.update()

    def full_detail(self) -> str:
        return self._history[-1][1] if self._history else ''


class _VisionLoader(QWidget):
    """Real stage-driven camera-loading progress indicator.

    Replaces the old 3×3 square animation. The percentage comes from actual
    completed initialisation stages reported by the shared CameraManager
    (preparing → discovering → opening → configured → streaming → ready); the
    widget only ever shows a value the runtime has genuinely earned, and
    ``finish()`` is the only thing that displays 100 % (called when a real
    frame has landed). While a stage is in flight a subtle shimmer signals
    activity without pretending progress.
    """

    _STAGE_LABELS = {
        'preparing':   'PREPARING CAMERA',
        'discovering': 'FINDING DEVICE',
        'opening':     'OPENING DEVICE',
        'configured':  'CONFIGURING STREAM',
        'streaming':   'STARTING CAPTURE',
        'ready':       'READY',
        'scanning':    'SCANNING VISION',
        'capturing':   'CAPTURING FRAME',
        'captured':    'FRAME READY',
        'preparing':   'PREPARING CAMERA',
        'preparing_image': 'PREPARING IMAGE',
        'analyzing':   'ANALYSING',
        'detecting':   'DETECTING',
        'interpreting': 'INTERPRETING',
        'finalizing':  'FINALISING',
        'failed':      'SCAN FAILED',
    }

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setFixedSize(236, 74)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self._title = 'PREPARING CAMERA'
        self._pinned_title = ''      # caller-supplied caption (wins over stages)
        self._value = 0            # real, stage-derived percentage
        self._failed = False
        self._shimmer = 0.0
        self._tmr = QTimer(self)
        self._tmr.timeout.connect(self._step)

    def _step(self):
        # Pure "still working" animation between real stages; it never changes
        # the reported percentage, so it cannot fake progress.
        self._shimmer = (self._shimmer + 0.035) % 1.0
        self.update()

    def set_title(self, title: str) -> None:
        """Pin the operation caption ("INITIALIZING CAMERA" / "SCANNING VISION").

        While pinned, stage names no longer rewrite the caption — the caller
        owns what the indicator is called.
        """
        caption = str(title or '')
        if caption:
            self._pinned_title = caption
            if caption != self._title:
                self._title = caption
                self.update()

    def release_title(self) -> None:
        """Un-pin the caption so stages can name themselves again."""
        self._pinned_title = ''

    def begin(self, title: str = '') -> None:
        """Arm the indicator for a brand-new operation at a real 0 %."""
        self._value = 0
        self._failed = False
        self._shimmer = 0.0
        self._pinned_title = str(title or '')
        self._title = self._pinned_title or 'WORKING'
        self._tmr.start(33)
        self.update()

    def set_stage(self, stage: str, percent: int) -> None:
        """One real initialisation stage completed (never above 99 %)."""
        key = str(stage or '')
        failed = key.startswith('failed')
        self._failed = failed
        if failed:
            # A failed attempt must not sit on an arbitrary percentage.
            self._value = 0
            self._title = 'CAMERA UNAVAILABLE'
        else:
            self._value = max(0, min(99, int(percent)))
            if not self._pinned_title:
                self._title = self._STAGE_LABELS.get(key, (key or 'WORKING').upper())
        self._tmr.start(33)
        self.show()
        self.raise_()
        self.update()

    def finish(self) -> None:
        """The operation genuinely completed — show 100 % and stop animating."""
        self._value = 100
        self._failed = False
        # Keep naming the operation the user started ("SCANNING VISION"); only
        # an unnamed camera open falls back to "READY".
        if not self._pinned_title:
            self._title = 'READY'
        try:
            self._tmr.stop()
        except Exception:
            pass
        self.update()

    def halt(self, reason: str = '') -> None:
        """Failure / cancellation / timeout: stop the indicator, never stick."""
        self._failed = True
        self._title = (reason or 'CAMERA UNAVAILABLE').upper()
        try:
            self._tmr.stop()
        except Exception:
            pass
        self.update()

    def hide_progress(self) -> None:
        try:
            self._tmr.stop()
        except Exception:
            pass
        self.hide()

    def showEvent(self, e):
        super().showEvent(e)
        if not self._tmr.isActive():
            self._tmr.start(33)

    def hideEvent(self, e):
        # Never animate while hidden — the timer stops with the widget.
        self._tmr.stop()
        super().hideEvent(e)

    def paintEvent(self, _):
        p = QPainter(self)
        if not p.isActive():
            return
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        W, H = self.width(), self.height()
        # Readable plate so the HUD text never dissolves into a bright camera.
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QBrush(QColor(2, 11, 19, 222)))
        p.drawRoundedRect(QRectF(0, 0, W - 1, H - 1), 7, 7)
        p.setPen(QPen(QColor(88, 214, 245, 70), 1.0))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(QRectF(0.5, 0.5, W - 2, H - 2), 7, 7)

        accent = QColor(244, 178, 74) if self._failed else qcol(C.PRI)
        f = QFont('Exo 2', 6, QFont.Weight.Bold)
        p.setFont(f)
        p.setPen(QPen(accent, 1))
        p.drawText(QRectF(12, 9, W - 24, 14),
                   Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,
                   self._title)
        pf = QFont('Share Tech Mono', 12, QFont.Weight.Bold)
        p.setFont(pf)
        p.setPen(QPen(qcol(C.WHITE, 235), 1))
        p.drawText(QRectF(12, 26, W - 24, 22),
                   Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,
                   f'{self._value:02d}%')

        # Progress track + real fill.
        bx, by, bw, bh = 12.0, H - 20.0, W - 24.0, 6.0
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QBrush(QColor(88, 214, 245, 34)))
        p.drawRoundedRect(QRectF(bx, by, bw, bh), 3, 3)
        frac = max(0.0, min(1.0, self._value / 100.0))
        if frac > 0:
            p.setBrush(QBrush(QColor(accent.red(), accent.green(),
                                     accent.blue(), 210)))
            p.drawRoundedRect(QRectF(bx, by, max(bh, bw * frac), bh), 3, 3)
        # Shimmer: an activity marker that always stays inside the real fill.
        if self._tmr.isActive() and 0 < self._value < 100 and not self._failed:
            x = bx + (bw * frac) * self._shimmer
            g = QLinearGradient(x, by, x + 26, by)
            g.setColorAt(0.0, QColor(255, 255, 255, 0))
            g.setColorAt(0.5, QColor(255, 255, 255, 90))
            g.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.setBrush(QBrush(g))
            p.setPen(Qt.PenStyle.NoPen)
            p.drawRoundedRect(QRectF(bx, by, max(bh, bw * frac), bh), 3, 3)
        p.end()


class _VisionAnalyzer(QObject):
    """Single background worker that analyses the live camera frames.

    The previous implementation spawned a brand new thread for every eighth
    frame, decoded the JPEG twice, and had no way to cancel stale work — which
    is why the stage stuttered under load.  Everything now runs on ONE
    long-lived thread that always works on the newest frame and silently drops
    anything that piled up behind it.
    """

    results = pyqtSignal(object)

    # How often each stage is allowed to run, in seconds.
    _FACE_PERIOD   = 0.14
    _NAME_PERIOD   = 1.20
    _OBJECT_PERIOD = 0.25

    def __init__(self, parent=None):
        super().__init__(parent)
        self._lock = threading.Lock()
        self._pending: bytes | None = None
        self._wake = threading.Event()
        self._stop = threading.Event()
        self._thread: threading.Thread | None = None

        self._want_faces = True
        self._want_names = False
        self._want_expression = False
        self._want_objects = False
        self._yolo_enabled = False
        self._want_motion = False
        self._object_tracking = True
        self._person_filter = False
        # Live inference options pushed from the UI. Kept here so a detector
        # that is (re)built later inherits the current control-surface state.
        self._rt_opts: dict = {}

        self._last_face_t = 0.0
        self._last_name_t = 0.0
        self._last_object_t = 0.0

        self._faces: list = []
        self._objects: list = []
        self._names: list = []          # cached (cx, cy, name) from the slow pass
        self._expressions: list = []    # cached (cx, cy, label)

        self._face_cascade = None
        self._smile_cascade = None
        self._recognizer = None
        self._recognizer_tried = False
        self._detector = None
        self._detector_tried = False
        self._detector_note = ''
        self._motion_level = 0.0
        self._previous_gray_small = None

    # ── public API ────────────────────────────────────────────────────────
    def set_wants(self, *, faces=None, names=None, expression=None, objects=None, motion=None, object_tracking=None, person_only=None, yolo=None):
        if faces is not None:      self._want_faces = bool(faces)
        if names is not None:      self._want_names = bool(names)
        if expression is not None: self._want_expression = bool(expression)
        if objects is not None:    self._want_objects = bool(objects)
        if yolo is not None and bool(yolo) != self._yolo_enabled:
            self._yolo_enabled = bool(yolo)
            # Rebuild on the worker so the switch changes the actual detector backend.
            self._detector = None
            self._detector_tried = False
            self._detector_note = 'YOLO STARTING' if self._yolo_enabled else 'YOLO OFF'
        if motion is not None:     self._want_motion = bool(motion)
        if object_tracking is not None:
            self._object_tracking = bool(object_tracking)
            self._rt_opts['tracking'] = self._object_tracking
            if not self._object_tracking:
                self._objects = []
        if person_only is not None:
            self._person_filter = bool(person_only)
        if self._detector is not None:
            try:
                self._detector.set_runtime_options(
                    tracking=self._object_tracking,
                    person_only=self._person_filter,
                )
            except Exception:
                pass
        if not self._want_names:
            self._names = []
        if not self._want_expression:
            self._expressions = []
        if not self._want_objects:
            self._objects = []
        if not self._want_faces:
            self._faces = []
        if not self._want_motion:
            self._motion_level = 0.0
            self._previous_gray_small = None

    def set_runtime_options(self, **opts):
        """Forward live inference controls (confidence/iou/imgsz/max_det/device/
        classes/person_mode/tracking) to the detector.

        Values are remembered so a detector rebuilt later (e.g. YOLO CORE
        toggled back on) inherits the current control-surface state. Safe to
        call from the UI thread: it only mutates scalar config on the detector.
        """
        for k, v in opts.items():
            if v is not None:
                self._rt_opts[k] = v
        det = self._detector
        if det is not None:
            try:
                det.set_runtime_options(**self._rt_opts)
            except Exception:
                pass

    def start(self):
        if self._thread is not None and self._thread.is_alive():
            return
        self._stop.clear()
        self._thread = threading.Thread(target=self._run, daemon=True,
                                        name='jarvis-vision-analyze')
        self._thread.start()

    def stop(self, timeout: float = 2.0):
        """Park the worker and wait for it, so nothing is mid-import at exit.

        The worker loads OpenCV / cascade / detector modules lazily, and a
        daemon thread that is inside ``importlib`` when the interpreter starts
        tearing modules down takes the process with it — a segfault, not an
        exception. Joining here means the last import finishes while the app is
        still alive.
        """
        self._stop.set()
        self._wake.set()
        with self._lock:
            self._pending = None
        thread, self._thread = self._thread, None
        if thread is not None and thread.is_alive():
            try:
                thread.join(timeout=max(0.0, float(timeout)))
            except Exception:
                pass
        self._faces = []
        self._objects = []
        self._names = []
        self._expressions = []
        self._motion_level = 0.0
        self._previous_gray_small = None

    def submit(self, jpg: bytes):
        """Hand the newest frame over; anything not yet picked up is dropped."""
        with self._lock:
            self._pending = jpg
        self._wake.set()

    @property
    def detector_note(self) -> str:
        return self._detector_note

    # ── worker ────────────────────────────────────────────────────────────
    def _warm_backends(self):
        """Import the detection backends up front, on this worker.

        They are heavy native modules (face recognition, object detection) and
        slow to import. Doing it once here — before the first frame, and while
        the stage shows its loader — keeps a multi-second import off the live
        frame path and, just as important, means shutdown never catches this
        thread in the middle of one. A daemon thread importing while the
        interpreter finalises is a segfault, not an exception.
        """
        try:
            import cv2  # noqa: F401  (also warms cv2 for the face stage)
        except Exception:
            return
        if self._want_names:
            self._ensure_recognizer()
        if self._want_objects:
            self._ensure_detector()

    def _run(self):
        warmed = False
        while not self._stop.is_set():
            self._wake.wait(0.25)
            self._wake.clear()
            if self._stop.is_set():
                break
            with self._lock:
                jpg = self._pending
                self._pending = None
            if not jpg:
                continue
            try:
                self._analyse(jpg)
            except Exception as exc:
                # An analysis failure must never take the camera down with it.
                # Logged (rate-limited) so a recurring detector fault is
                # diagnosable instead of silent.
                try:
                    from vision.utils import logger
                    now = time.monotonic()
                    if now - getattr(self, "_last_err_t", 0.0) > 5.0:
                        self._last_err_t = now
                        logger.error(f"vision analysis frame failed: {exc!r}")
                except Exception:
                    pass
            if not warmed:
                # Warm AFTER the first pass so the picture is already on
                # screen while the heavy backends load.
                warmed = True
                self._warm_backends()

    def _analyse(self, jpg: bytes):
        now = time.monotonic()
        need_face = self._want_faces and (now - self._last_face_t) >= self._FACE_PERIOD
        need_name = self._want_names and (now - self._last_name_t) >= self._NAME_PERIOD
        need_obj  = self._want_objects and (now - self._last_object_t) >= self._OBJECT_PERIOD
        need_motion = self._want_motion
        if not (need_face or need_name or need_obj or need_motion):
            return

        try:
            import cv2
        except Exception:
            return

        arr = np.frombuffer(jpg, dtype=np.uint8)
        gray = None
        bgr = None

        if need_face or need_name:
            gray = cv2.imdecode(arr, cv2.IMREAD_GRAYSCALE)
        if need_name or need_obj:
            bgr = cv2.imdecode(arr, cv2.IMREAD_COLOR)
        if need_motion and gray is None:
            gray = cv2.imdecode(arr, cv2.IMREAD_GRAYSCALE)

        if need_face and gray is not None:
            self._last_face_t = now
            self._faces = self._run_faces(cv2, gray)

        if need_name and bgr is not None:
            self._last_name_t = now
            self._names = self._run_names(bgr)

        if self._want_expression and gray is not None and self._faces:
            self._expressions = self._run_expressions(cv2, gray)
        elif not self._want_expression:
            self._expressions = []

        if need_obj and bgr is not None:
            self._last_object_t = now
            self._objects = self._run_objects(bgr)

        if need_motion and gray is not None:
            self._motion_level = self._run_motion(cv2, gray)

        stats = {}
        try:
            if self._detector is not None:
                stats = dict(self._detector.runtime_status())
        except Exception:
            stats = {}
        stats.setdefault('backend', 'off')
        stats.setdefault('model', 'none')
        stats.setdefault('task', 'detect')
        stats.setdefault('device', 'cpu')
        stats['objects'] = len(self._objects)

        self.results.emit({
            'faces': list(self._faces),
            'names': list(self._names),
            'expressions': list(self._expressions),
            'objects': list(self._objects),
            'motion': float(self._motion_level),
            'stats': dict(stats),
            'note': self._detector_note,
            'yolo_enabled': bool(self._yolo_enabled),
            'yolo_backend': str(getattr(self._detector, 'backend', '') or ''),
        })

    # ── stages ────────────────────────────────────────────────────────────
    def _run_faces(self, cv2, gray) -> list:
        """Normalised (x, y, w, h) boxes for every visible face."""
        if self._face_cascade is None:
            try:
                self._face_cascade = cv2.CascadeClassifier(
                    cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
                if self._face_cascade.empty():
                    self._face_cascade = None
                    return []
            except Exception:
                self._face_cascade = None
                return []
        h, w = gray.shape[:2]
        if w <= 0 or h <= 0:
            return []
        # A single 320px-wide working copy keeps Haar cheap regardless of the
        # sensor resolution, and the aspect ratio is preserved so the boxes
        # land where the face actually is.
        scale = 320.0 / float(w)
        sw = max(80, int(round(w * scale)))
        sh = max(60, int(round(h * scale)))
        small = cv2.resize(gray, (sw, sh), interpolation=cv2.INTER_AREA)
        small = cv2.equalizeHist(small)
        try:
            found = self._face_cascade.detectMultiScale(
                small, scaleFactor=1.18, minNeighbors=5, minSize=(34, 34),
                flags=cv2.CASCADE_SCALE_IMAGE)
        except Exception:
            return []
        return [(float(x) / sw, float(y) / sh, float(fw) / sw, float(fh) / sh)
                for (x, y, fw, fh) in found]

    def _run_expressions(self, cv2, gray) -> list:
        """A cheap, fully offline smile read per detected face."""
        if self._smile_cascade is None:
            try:
                self._smile_cascade = cv2.CascadeClassifier(
                    cv2.data.haarcascades + 'haarcascade_smile.xml')
                if self._smile_cascade.empty():
                    self._smile_cascade = None
                    return []
            except Exception:
                self._smile_cascade = None
                return []
        h, w = gray.shape[:2]
        out = []
        for (nx, ny, nw, nh) in self._faces[:4]:
            x0 = max(0, int(nx * w)); y0 = max(0, int(ny * h))
            fw = max(1, int(nw * w)); fh = max(1, int(nh * h))
            # Lower half of the face only — that is where a smile lives.
            y1 = y0 + int(fh * 0.55)
            roi = gray[y1:min(h, y0 + fh), x0:min(w, x0 + fw)]
            if roi.size == 0:
                continue
            try:
                roi = cv2.resize(roi, (96, max(24, int(96 * roi.shape[0] / max(1, roi.shape[1])))),
                                 interpolation=cv2.INTER_AREA)
                smiles = self._smile_cascade.detectMultiScale(
                    roi, scaleFactor=1.7, minNeighbors=20, minSize=(24, 14))
            except Exception:
                smiles = []
            label = 'SMILING' if len(smiles) else 'NEUTRAL'
            out.append((nx + nw / 2.0, ny + nh / 2.0, label))
        return out

    def _run_motion(self, cv2, gray) -> float:
        """Estimate local frame-to-frame motion as a 0..100 percentage.

        The calculation stays entirely local and deliberately uses a tiny
        grayscale working image so the optional motion HUD cannot become the
        expensive part of the Vision pipeline.
        """
        try:
            small = cv2.resize(gray, (160, 90), interpolation=cv2.INTER_AREA)
            small = cv2.GaussianBlur(small, (5, 5), 0)
            previous = self._previous_gray_small
            self._previous_gray_small = small
            if previous is None or getattr(previous, "shape", None) != small.shape:
                return 0.0
            diff = cv2.absdiff(previous, small)
            # Ignore tiny sensor/compression noise, then express the moving
            # pixel ratio as a percentage with a little headroom for the HUD.
            active = diff > 14
            ratio = float(active.mean()) * 100.0
            mean_delta = float(diff.mean())
            return max(0.0, min(100.0, ratio * 1.8 + mean_delta * 0.35))
        except Exception:
            return float(self._motion_level)


    def _ensure_recognizer(self):
        """Load the face recogniser once (off the UI thread)."""
        if not self._recognizer_tried:
            self._recognizer_tried = True
            try:
                from vision.config import load_vision_config
                from vision.face_recognition import FaceRecognizer
                self._recognizer = FaceRecognizer(load_vision_config())
            except Exception:
                self._recognizer = None
        return self._recognizer

    def _run_names(self, bgr) -> list:
        """Identity per face, via the project's own recogniser when present."""
        if self._ensure_recognizer() is None:
            return []
        try:
            people = self._recognizer.who_is_there(bgr)
        except Exception:
            return []
        out = []
        for entry in (people or []):
            try:
                name, _conf, rect, _q = entry
            except Exception:
                continue
            if not name:
                continue
            try:
                cx = float(rect.x) + float(rect.w) / 2.0
                cy = float(rect.y) + float(rect.h) / 2.0
            except Exception:
                continue
            out.append((cx, cy, str(name).upper()))
        return out

    def _ensure_detector(self):
        """Load the local object detector once (off the UI thread)."""
        if not self._detector_tried:
            self._detector_tried = True
            try:
                from vision.config import load_vision_config
                from vision.object_detection import ObjectDetector
                cfg = load_vision_config()
                if self._yolo_enabled:
                    cfg.object_detector_backend = 'ultralytics'
                self._detector = ObjectDetector.create(cfg)
                backend = ''
                try:
                    backend = str(self._detector.ensure_backend() or '')
                except Exception:
                    backend = ''
                if not backend or backend in ('off', 'ai'):
                    # 'ai' routes every frame through a remote provider, which
                    # would be far too slow for a live HUD overlay.
                    self._detector_note = ('OBJECT ENGINE UNAVAILABLE' if self._yolo_enabled
                                           else 'NO LOCAL OBJECT MODEL')
                    self._detector = None
                else:
                    self._detector_note = f'OBJECT ENGINE · {backend.upper()}'
                    if self._rt_opts:
                        try:
                            self._detector.set_runtime_options(**self._rt_opts)
                        except Exception:
                            pass
            except Exception:
                self._detector = None
                self._detector_note = 'OBJECT DETECTOR UNAVAILABLE'
        return self._detector

    def _run_objects(self, bgr) -> list:
        """Normalised object boxes from the local detector, when one exists."""
        if self._ensure_detector() is None:
            return []
        try:
            try:
                self._detector.set_runtime_options(
                    tracking=self._object_tracking)
            except Exception:
                pass
            dets = self._detector.detect(bgr) or []
        except Exception:
            return []
        out = []
        for d in dets[:12]:
            try:
                r = d.rect
                box = (float(r.x), float(r.y), float(r.w), float(r.h))
                conf = float(d.confidence)
                # A thin/degenerate detection can carry a NaN box or score;
                # dropping it here means it never reaches the paint overlay.
                if not _finite_box(box) or conf != conf:
                    continue
                out.append((box[0], box[1], box[2], box[3],
                            str(d.label).upper(), conf,
                            int(getattr(d, 'tracker_id', -1))))
            except Exception:
                continue
        return out


class _LatestFrameMailbox:
    """Single-slot newest-frame hand-off to the UI thread.

    A queued signal is a *queue*: on a busy UI thread every emitted frame waits
    its turn, so the preview replays history and the delay grows with the
    backlog.  This mailbox keeps only the newest JPEG and lets at most one
    delivery be in flight, so a frame that arrives while the UI thread is still
    busy is dropped in favour of the next one.  ``put`` returns True exactly
    when the caller should emit its signal; :meth:`take` re-arms the mailbox.
    """

    def __init__(self):
        self._lock = threading.Lock()
        self._jpg: bytes | None = None
        self._in_flight = False

    def put(self, jpg: bytes) -> bool:
        if not jpg:
            return False
        with self._lock:
            self._jpg = jpg
            if self._in_flight:
                return False
            self._in_flight = True
            return True

    def take(self) -> bytes | None:
        with self._lock:
            jpg, self._jpg = self._jpg, None
            self._in_flight = False
            return jpg

    def reset(self) -> None:
        with self._lock:
            self._jpg = None
            self._in_flight = False


class _CameraFrameDecoder(QObject):
    """Decode camera JPEGs into display-ready QImages off the UI thread.

    One decoder serves every preview surface.  Decoding a 720p JPEG plus the
    ARGB32 conversion costs several milliseconds, and doing it inside the frame
    slot or the paint path stalled the whole HUD whenever a frame landed.
    Frames also arrive faster than the UI can paint them, so the newest JPEG
    always replaces one that has not been decoded yet: the picture can never
    fall behind by more than a single frame and no backlog of stale frames ever
    builds up.

    ``decoded`` carries no payload — receivers pull :meth:`take`, which is what
    makes the stream hand-off newest-wins instead of a queue.  The thread exists
    only between :meth:`start` and :meth:`stop`, so `stop` really is the end of
    this pipeline; one-shot photos are discrete user actions and get their own
    short-lived thread via :meth:`submit_photo`, delivered whole through
    ``photo_decoded`` so a live frame can never replace the photo just asked
    for.
    """

    decoded = pyqtSignal()
    photo_decoded = pyqtSignal(QImage)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._lock = threading.Lock()
        self._pending: bytes | None = None
        self._latest: QImage | None = None
        self._seq = 0
        self._wake = threading.Event()
        self._session: threading.Event | None = None
        self._thread: threading.Thread | None = None

    def start(self) -> None:
        if self._thread is not None and self._thread.is_alive():
            return
        session = threading.Event()
        self._session = session
        self._thread = threading.Thread(target=self._run, args=(session,),
                                        daemon=True, name='jarvis-frame-decode')
        self._thread.start()

    def stop(self) -> None:
        session = self._session
        if session is not None:
            session.set()
            self._session = None
        self._wake.set()
        with self._lock:
            self._pending = None
            self._latest = None
        thread, self._thread = self._thread, None
        # The loop wakes immediately, so this normally returns at once; the
        # bound only matters if a decode is wedged.
        if thread is not None and thread.is_alive():
            try:
                thread.join(timeout=0.3)
            except Exception:
                pass

    def submit(self, jpg: bytes) -> None:
        """Queue a stream frame (newest replaces one not yet decoded)."""
        if not jpg:
            return
        if self._thread is None or not self._thread.is_alive():
            self.start()
        with self._lock:
            self._pending = jpg
        self._wake.set()

    def submit_photo(self, jpg: bytes) -> None:
        """Decode one photo on its own thread and deliver it whole."""
        if not jpg:
            return

        def _work():
            img = self._decode(jpg)
            if img is not None:
                try:
                    self.photo_decoded.emit(img)
                except Exception:
                    pass

        threading.Thread(target=_work, daemon=True,
                         name='jarvis-photo-decode').start()

    def take(self) -> QImage | None:
        """Newest decoded stream frame, or None when nothing new is waiting."""
        with self._lock:
            img = self._latest
            self._latest = None
        return img

    @property
    def sequence(self) -> int:
        return self._seq

    def _run(self, session: threading.Event) -> None:
        while not session.is_set():
            self._wake.wait(0.25)
            if session.is_set():
                break
            self._wake.clear()
            with self._lock:
                jpg = self._pending
                self._pending = None
            if not jpg:
                continue
            img = self._decode(jpg)
            if img is None or session.is_set():
                continue
            with self._lock:
                self._latest = img
                self._seq += 1
            self.decoded.emit()

    @staticmethod
    def _decode(jpg: bytes) -> QImage | None:
        try:
            img = QImage.fromData(jpg)
        except Exception:
            return None
        if img.isNull():
            return None
        # ARGB32_Premultiplied is the raster engine's native format: convert
        # once here, off the UI thread, not on every blit.
        if img.format() != QImage.Format.Format_ARGB32_Premultiplied:
            img = img.convertToFormat(QImage.Format.Format_ARGB32_Premultiplied)
        return img


def _pct(value) -> int:
    """Confidence 0..1 → integer percent, non-finite/None-safe.

    A degenerate detection — a very thin object such as a pair of scissors can
    make the detector return a NaN/inf confidence or bounding box — must never
    reach int()/paint arithmetic, where it raises ValueError inside paintEvent
    and (in PyQt6) aborts the whole process.
    """
    try:
        f = float(value)
    except (TypeError, ValueError):
        return 0
    if f != f or f in (float("inf"), float("-inf")):
        return 0
    return max(0, min(100, int(f * 100)))


def _finite_box(entry, n: int = 4):
    """True when ``entry`` has at least ``n`` values and the first ``n`` are all
    finite floats. A short or non-numeric entry is rejected, not assumed ok."""
    try:
        vals = list(entry)
    except TypeError:
        return False
    if len(vals) < n:
        return False
    for v in vals[:n]:
        try:
            fv = float(v)
        except (TypeError, ValueError):
            return False
        if fv != fv or fv in (float("inf"), float("-inf")):
            return False
    return True


class _InlineVisionView(QFrame):
    """Camera surface used exclusively by the Chat Vision stage.

    Rendering contract
    ------------------
    * Decoding happens once per frame in ``_CameraFrameDecoder`` on its own
      thread; this widget only ever receives a finished ``QImage``, so the UI
      thread never pays a JPEG decode no matter how many previews are visible.
    * The scaled/mirrored/brightened picture is built **once per frame** into a
      cache.  ``paintEvent`` then does a straight blit plus vector overlays, so
      repaints triggered by overlays or resizes cost almost nothing.
    * Every switch on the control rail changes something visible here.
    """

    # Camera/scan init stages are reported from the capture/worker threads.
    _camera_progress_sig = pyqtSignal(str, int)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumSize(210, 190)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, False)
        self._frame = QImage()
        self._faces: list[tuple[float,float,float,float]] = []
        self._object_labels: list = []
        self._names: list = []
        self._expressions: list = []
        self._detector_note = ''
        self._loading = True
        self._face_track = True
        self._object_track = False
        self._visible_name = True
        self._face_zoom = False   # off by default: the frame is shown uncropped
        self._expression = False
        self._object_detection = True
        self._invert = False
        self._grid_overlay = False
        self._fps_hud = False
        self._low_light = False
        self._center_reticle = False
        self._edge_outline = False
        self._track_ids = True
        # Off by default: the plain camera preview must show the picture, not a
        # block of OBJECTS/TRACK/LATENCY text painted over it. The INFERENCE HUD
        # switch still turns this exact overlay on, so the feature is intact.
        self._inference_hud = False
        self._motion_pulse = False
        self._person_filter = False
        self._live_inference = True
        self._yolo_enabled = False
        self._yolo_backend = ''
        self._motion_level = 0.0
        self._inference_stats = {}
        self._fps_last_t = time.monotonic()
        self._fps_frames = 0
        self._fps_value = 0.0
        # Additive white lift applied over the live frame — a cheap way to keep
        # a dim webcam readable without touching the capture pipeline.
        self._brightness = 30
        self._status = 'VISION CAMERA · CONNECTING'
        self._frame_count = 0
        self._frame_serial = 0
        self._zoom_target = 1.0
        self._zoom = 1.0
        self._face_center = (0.5, 0.5)

        # Presentation cache: rebuilt only when something it depends on moves.
        self._cache_img: QImage | None = None
        self._cache_key = None
        self._img_rect = (0.0, 0.0, 0.0, 0.0)
        self._crop = (0.0, 0.0, 1.0, 1.0)

        self.setStyleSheet('QFrame { background:transparent; border:none; }')
        # Stage-driven progress (replaces the old 3×3 square loader).
        self._loader = _VisionLoader(self)
        self._loader.setFixedSize(236, 74)
        self._loader.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self._loader.hide()
        # Camera init stages arrive from the capture thread → marshal to UI.
        self._camera_progress_sig.connect(self._apply_camera_progress,
                                          Qt.ConnectionType.QueuedConnection)
        self._progress_op = 0          # operation generation (lifecycle safety)
        self._scan_progress = False    # True while a Vision Scan drives the bar
        self._ready_close_timer = None

        self._loading_timer = QTimer(self)
        self._loading_timer.setSingleShot(True)
        self._loading_timer.timeout.connect(self._loading_timeout)

        # Zoom easing runs on its own clock so it is smooth even when the
        # camera is slow, and stops dead once it has settled.
        self._zoom_timer = QTimer(self)
        self._zoom_timer.setTimerType(Qt.TimerType.PreciseTimer)
        self._zoom_timer.setInterval(16)
        self._zoom_timer.timeout.connect(self._step_zoom)

        # The same glowing sweep the floating preview uses: one shared overlay
        # class, so a look on the Vision stage reads exactly like a look on the
        # camera window.
        self._scan = _ScanOverlay(self)

    # ── options ───────────────────────────────────────────────────────────
    def set_scan(self, on: bool, single: bool = False) -> None:
        """Run the light-blue scan sweep over the picture."""
        try:
            if on:
                self._scan.start(single=single)
            else:
                self._scan.stop()
        except Exception:
            pass

    def set_options(self, *, face_track=None, object_track=None, visible_name=None,
                    face_zoom=None, expression=None, object_detection=None, invert=None,
                    grid_overlay=None, fps_hud=None, low_light=None,
                    center_reticle=None, edge_outline=None, track_ids=None,
                    inference_hud=None, motion_pulse=None, person_filter=None,
                    yolo_enabled=None, yolo_backend=None, live_inference=None):
        if face_track is not None: self._face_track = bool(face_track)
        if object_track is not None: self._object_track = bool(object_track)
        if visible_name is not None: self._visible_name = bool(visible_name)
        if face_zoom is not None: self._face_zoom = bool(face_zoom)
        if expression is not None: self._expression = bool(expression)
        if object_detection is not None: self._object_detection = bool(object_detection)
        if invert is not None: self._invert = bool(invert)
        if grid_overlay is not None: self._grid_overlay = bool(grid_overlay)
        if fps_hud is not None: self._fps_hud = bool(fps_hud)
        if low_light is not None: self._low_light = bool(low_light)
        if center_reticle is not None: self._center_reticle = bool(center_reticle)
        if edge_outline is not None: self._edge_outline = bool(edge_outline)
        if track_ids is not None: self._track_ids = bool(track_ids)
        if inference_hud is not None: self._inference_hud = bool(inference_hud)
        if motion_pulse is not None: self._motion_pulse = bool(motion_pulse)
        if person_filter is not None: self._person_filter = bool(person_filter)
        if yolo_enabled is not None: self._yolo_enabled = bool(yolo_enabled)
        if yolo_backend is not None: self._yolo_backend = str(yolo_backend or '')
        if live_inference is not None: self._live_inference = bool(live_inference)
        if not self._face_track:
            self._faces = []
            self._names = []
            self._expressions = []
        if not (self._object_detection and self._object_track):
            pass
        if not self._face_zoom:
            self._zoom_target = 1.0
            self._start_zoom_anim()
        self._cache_key = None      # brightness / mirror may have changed
        self.update()

    def set_detector_note(self, note: str):
        note = str(note or '')
        if note != self._detector_note:
            self._detector_note = note
            self.update()

    # ── real progress (camera init / vision scan) ─────────────────────────
    def report_progress(self, stage: str, percent: int) -> None:
        """Thread-safe: one REAL operation stage just completed.

        Callable from the capture or worker thread. It only stamps the current
        operation generation, so a callback from a camera load or a scan that
        has already been superseded can never move today's indicator.
        """
        op = self._progress_op
        try:
            self._camera_progress_sig.emit(f'{op}|{stage}', int(percent))
        except Exception:
            pass

    def cancel_progress(self, reason: str = 'CANCELLED') -> None:
        """Thread-safe stop: retire the current operation and clear the UI."""
        self._progress_op += 1
        self._scan_progress = False
        try:
            self._camera_progress_sig.emit(f'{-1}|cancelled', 0)
        except Exception:
            pass
        try:
            self._loader.hide_progress()
        except Exception:
            pass

    def begin_vision_scan(self) -> int:
        """Arm the shared indicator for a real Vision look.

        Returns the operation generation so the caller's watchdog can tell
        whether the scan it is supervising is still the current one.
        """
        self._progress_op += 1
        self._scan_progress = True
        self._loader.begin('SCANNING VISION')
        self._loader.show()
        self._loader.raise_()
        self._position_loader()
        return self._progress_op

    def end_vision_scan(self) -> None:
        """Retire a scan that finished (or was abandoned) without a result."""
        if not self._scan_progress:
            return
        self._retire_progress()
        self._loader.hide_progress()

    def _apply_camera_progress(self, stamped: str, percent: int) -> None:
        """UI-thread half of :meth:`report_progress`."""
        if self._scan_progress:
            title = 'SCANNING VISION'
        else:
            title = 'INITIALIZING CAMERA'
        op, _, stage = str(stamped or '').partition('|')
        try:
            if int(op) != self._progress_op:
                return          # belongs to a retired operation
        except ValueError:
            return
        if stage == 'cancelled':
            self._loader.hide_progress()
            return
        if stage.startswith('failed'):
            reason = stage.split(':', 1)[1] if ':' in stage else ''
            self._loader.halt({
                'no_opencv': 'OPENCV UNAVAILABLE',
                'disabled': 'CAMERA DISABLED',
                'device_unavailable': 'CAMERA UNAVAILABLE',
            }.get(reason, 'SCAN FAILED' if self._scan_progress
                            else 'CAMERA UNAVAILABLE'))
            if self._scan_progress:
                # A scan that failed still has to terminate its indicator.
                self._retire_progress()
                QTimer.singleShot(1400, self._loader.hide_progress)
            return
        # ``set_stage`` caps at 99 % — 100 % is only ever reached through
        # finish(), which is driven by a genuinely delivered frame (camera) or
        # a genuinely produced answer (scan "finalizing").
        if self._scan_progress and stage == 'finalizing':
            self._loader.set_title('SCANNING VISION')
            self._loader.finish()
            self._retire_progress()
            QTimer.singleShot(600, self._loader.hide_progress)
            return
        self._loader.set_title(title)
        self._loader.set_stage(stage, percent)
        self._position_loader()


    # ── frame intake ──────────────────────────────────────────────────────
    def set_frame_image(self, img: QImage) -> None:
        """Accept an already-decoded frame (decoded off the UI thread)."""
        if img is None or img.isNull():
            return
        self._frame = img
        self._frame_count += 1
        self._frame_serial += 1

        now = time.monotonic()
        self._fps_frames += 1
        dt = now - self._fps_last_t
        if dt >= 0.5:
            self._fps_value = self._fps_frames / dt
            self._fps_frames = 0
            self._fps_last_t = now

        if self._loading:
            self._loading = False
            self._status = 'VISION CAMERA · LIVE'
            # A real frame has landed: this is the only honest place where the
            # camera indicator reaches 100 %, and it retires the operation so a
            # late stage callback from this open can never revive it.
            self._retire_progress()
            try:
                self._loading_timer.stop()
            except Exception:
                pass
            self._loader.finish()
            self._loader.move(int((self.width() - self._loader.width()) / 2),
                              int(max(4.0, self.height() - self._loader.height() - 18.0)))
            QTimer.singleShot(520, self._loader.hide_progress)
        self.update()

    def _retire_progress(self) -> None:
        """Invalidate the in-flight progress operation (UI thread)."""
        self._progress_op += 1
        self._scan_progress = False

    def set_faces(self, faces):
        # Defensive: keep only well-formed, finite 4-tuples. set_analysis
        # already wraps its call, but set_faces is also reachable directly, and
        # a single malformed face box must never raise into a paint cycle.
        clean = []
        for r in (faces or []):
            try:
                a, b, c, d = float(r[0]), float(r[1]), float(r[2]), float(r[3])
            except (TypeError, ValueError, IndexError):
                continue
            if not _finite_box((a, b, c, d)):
                continue
            clean.append((a, b, c, d))
        self._faces = clean
        if self._faces and self._face_track and self._face_zoom:
            fx, fy, fw, fh = max(self._faces, key=lambda r: r[2] * r[3])
            self._face_center = (fx + fw / 2.0, fy + fh / 2.0)
            self._zoom_target = max(1.0, min(1.75, 0.92 / max(0.55, fw * 2.0)))
        else:
            self._zoom_target = 1.0
        self._start_zoom_anim()
        self.update()

    def set_analysis(self, payload: dict):
        """Results from :class:`_VisionAnalyzer`, applied in one go."""
        try:
            self.set_faces(payload.get('faces') or [])
            self._names = list(payload.get('names') or [])
            self._expressions = list(payload.get('expressions') or [])
            self._object_labels = list(payload.get('objects') or [])
            self._motion_level = float(payload.get('motion') or 0.0)
            self._inference_stats = dict(payload.get('stats') or {})
            self._yolo_enabled = bool(payload.get('yolo_enabled', self._yolo_enabled))
            self._yolo_backend = str(payload.get('yolo_backend', self._yolo_backend) or '')
            self.set_detector_note(payload.get('note') or '')
        except Exception:
            pass

    # ── zoom easing ───────────────────────────────────────────────────────
    def _start_zoom_anim(self):
        if abs(self._zoom_target - self._zoom) > 0.002:
            if not self._zoom_timer.isActive():
                self._zoom_timer.start()

    def _step_zoom(self):
        self._zoom += (self._zoom_target - self._zoom) * 0.16
        if abs(self._zoom_target - self._zoom) <= 0.002:
            self._zoom = self._zoom_target
            self._zoom_timer.stop()
        self._cache_key = None
        self.update()

    # ── lifecycle ─────────────────────────────────────────────────────────
    def begin_loading(self):
        # A fresh camera-open generation: any stage from a previous attempt is
        # now stale and will be dropped by _apply_camera_progress.
        self._progress_op += 1
        self._scan_progress = False
        self._loading = True
        self._status = 'VISION CAMERA · CONNECTING'
        self._frame = QImage()
        self._faces = []
        self._names = []
        self._expressions = []
        self._object_labels = []
        self._motion_level = 0.0
        self._inference_stats = {}
        self._cache_img = None
        self._cache_key = None
        self._frame_count = 0
        self._fps_frames = 0
        self._fps_value = 0.0
        self._fps_last_t = time.monotonic()
        self._zoom = 1.0
        self._zoom_target = 1.0
        self._loader.begin('INITIALIZING CAMERA')
        self._loader.show()
        self._loader.raise_()
        self._position_loader()
        try:
            self._loading_timer.start(20000)
        except Exception:
            pass
        self.update()

    def end_stream(self):
        """Release the decoded frame so a hidden stage holds no image memory."""
        try:
            self._loading_timer.stop()
        except Exception:
            pass
        self._zoom_timer.stop()
        try:
            self._scan.stop()
        except Exception:
            pass
        # Closing the stream retires the operation: a capture thread that is
        # still mid-open must not keep reporting into a closed panel.
        self._retire_progress()
        self._loader.hide_progress()
        self._frame = QImage()
        self._cache_img = None
        self._cache_key = None
        self._faces = []
        self._names = []
        self._expressions = []
        self._object_labels = []
        self._motion_level = 0.0
        self._inference_stats = {}

    def _loading_timeout(self):
        if self._loading and self._frame_count == 0:
            self._status = 'VISION CAMERA · NO SIGNAL'
            # The indicator must always terminate: a stalled open ends here in
            # an explicit failed state rather than sticking at a percentage.
            self._loader.halt('NO SIGNAL')
            self._retire_progress()
            QTimer.singleShot(1200, self._loader.hide_progress)
            self.update()

    def _position_loader(self):
        try:
            self._loader.move((self.width() - self._loader.width()) // 2,
                              max(6.0, self.height() - self._loader.height() - 16.0))
        except Exception:
            pass


    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._cache_key = None
        self._position_loader()

    # ── painting helpers ──────────────────────────────────────────────────
    def _draw_text(self, p, text, x, y, size=7, color=None, bold=True):
        p.setPen(QPen(qcol(color or C.PRI, 235), 1))
        p.setFont(QFont('Exo 2', size, QFont.Weight.Bold if bold else QFont.Weight.Normal))
        p.drawText(QPointF(x,y), text)

    def _rebuild_cache(self, W: int, H: int):
        """Scale, crop, mirror and brighten the current frame exactly once."""
        img = self._frame
        sw, sh = img.width(), img.height()
        if sw <= 0 or sh <= 0:
            self._cache_img = None
            return
        cx0 = cy0 = 0.0
        cwn = chn = 1.0
        if self._zoom > 1.001:
            cx = int(self._face_center[0] * sw); cy = int(self._face_center[1] * sh)
            cw = max(32, int(sw / self._zoom)); ch = max(32, int(sh / self._zoom))
            left = max(0, min(sw - cw, cx - cw // 2))
            top  = max(0, min(sh - ch, cy - ch // 2))
            img = img.copy(left, top, cw, ch)
            cx0, cy0 = left / sw, top / sh
            cwn, chn = cw / sw, ch / sh
        self._crop = (cx0, cy0, cwn, chn)

        # FIT the whole frame inside the view — letterboxed when the camera's
        # aspect differs from the widget. Nothing is cropped.
        mode = (Qt.TransformationMode.SmoothTransformation
                if img.width() <= W * 2 else Qt.TransformationMode.FastTransformation)
        scaled = img.scaled(int(W), int(H), Qt.AspectRatioMode.KeepAspectRatio, mode)

        if self._invert:
            # Baked into the cache: a mirrored blit every paint would force the
            # raster engine down its slow transformed path.
            try:
                scaled = scaled.mirrored(True, False)
            except (AttributeError, TypeError):
                # Qt 6.9+ renamed this; keep both spellings working.
                scaled = scaled.flipped(Qt.Orientation.Horizontal)
            if scaled.format() != QImage.Format.Format_ARGB32_Premultiplied:
                scaled = scaled.convertToFormat(QImage.Format.Format_ARGB32_Premultiplied)

        brightness = 72 if self._low_light else self._brightness
        if brightness > 0:
            # Dim sensors read as "broken"; an additive pass lifts the whole
            # image. Applied to the scaled copy only, so the cost scales with
            # the widget rather than with the sensor resolution.
            #
            # ``scaled`` is already this frame's private scaled copy, and it is
            # converted to the raster-native premultiplied format before the
            # second QPainter opens it: painting a format Qt must convert (or
            # a buffer it must detach) *inside* the widget's own paintEvent is
            # what produced the "painted by one painter at a time" flood.
            if scaled.format() != QImage.Format.Format_ARGB32_Premultiplied:
                scaled = scaled.convertToFormat(QImage.Format.Format_ARGB32_Premultiplied)
            bp = QPainter(scaled)
            if bp.isActive():
                bp.setCompositionMode(QPainter.CompositionMode.CompositionMode_Plus)
                bp.fillRect(scaled.rect(),
                            QColor(int(brightness), int(brightness), int(brightness), 255))
                bp.end()
            else:
                # The brightness pass is cosmetic; if Qt will not let us paint
                # the buffer we simply show the frame un-lifted rather than
                # corrupting the widget's painter state.
                pass

        self._cache_img = scaled
        sx = max(0, (W - scaled.width()) // 2)
        sy = max(0, (H - scaled.height()) // 2)
        self._img_rect = (float(sx), float(sy), float(scaled.width()), float(scaled.height()))

    def _map_box(self, nx, ny, nw, nh):
        """Normalised source box → widget coordinates, crop and mirror aware."""
        cx0, cy0, cwn, chn = self._crop
        sx, sy, sw, sh = self._img_rect
        u = (nx - cx0) / max(1e-6, cwn)
        v = (ny - cy0) / max(1e-6, chn)
        uw = nw / max(1e-6, cwn)
        vh = nh / max(1e-6, chn)
        if self._invert:
            u = 1.0 - u - uw
        return QRectF(sx + u * sw, sy + v * sh, uw * sw, vh * sh)

    def _map_point(self, nx, ny):
        cx0, cy0, cwn, chn = self._crop
        sx, sy, sw, sh = self._img_rect
        u = (nx - cx0) / max(1e-6, cwn)
        v = (ny - cy0) / max(1e-6, chn)
        if self._invert:
            u = 1.0 - u
        return QPointF(sx + u * sw, sy + v * sh)

    @staticmethod
    def _corner_box(p, rect: QRectF, color: QColor, arm: float = 0.26):
        """Targeting brackets rather than a plain rectangle — HUD language."""
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(color, 1.6))
        ax = max(6.0, rect.width() * arm)
        ay = max(6.0, rect.height() * arm)
        l, t, r, b = rect.left(), rect.top(), rect.right(), rect.bottom()
        p.drawLine(QPointF(l, t), QPointF(l + ax, t)); p.drawLine(QPointF(l, t), QPointF(l, t + ay))
        p.drawLine(QPointF(r, t), QPointF(r - ax, t)); p.drawLine(QPointF(r, t), QPointF(r, t + ay))
        p.drawLine(QPointF(l, b), QPointF(l + ax, b)); p.drawLine(QPointF(l, b), QPointF(l, b - ay))
        p.drawLine(QPointF(r, b), QPointF(r - ax, b)); p.drawLine(QPointF(r, b), QPointF(r, b - ay))

    def _label_chip(self, p, text: str, anchor: QPointF, color: QColor):
        f = QFont('Exo 2', 6, QFont.Weight.Bold)
        p.setFont(f)
        w = p.fontMetrics().horizontalAdvance(text) + 12
        h = 15.0
        x = anchor.x()
        y = anchor.y() - h - 3.0
        if y < 2.0:
            y = anchor.y() + 3.0
        x = max(2.0, min(float(self.width()) - w - 2.0, x))
        chip = QRectF(x, y, w, h)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QBrush(QColor(2, 14, 22, 190)))
        p.drawRoundedRect(chip, 3, 3)
        p.setPen(QPen(color, 1.0))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(chip, 3, 3)
        p.setPen(QPen(color, 1))
        p.drawText(chip, Qt.AlignmentFlag.AlignCenter, text)

    def _nearest(self, entries, cx, cy, radius=0.20):
        best = None
        best_d = radius * radius
        for e in entries:
            d = (e[0] - cx) ** 2 + (e[1] - cy) ** 2
            if d <= best_d:
                best_d = d
                best = e
        return best

    # ── paint ─────────────────────────────────────────────────────────────
    def paintEvent(self, _):
        # PyQt6 turns any exception raised inside a reimplemented paintEvent
        # into qFatal + abort — a whole-application crash, with no Python
        # traceback to catch. A single malformed detection box (a thin object
        # like scissors can carry a non-finite confidence) must never take the
        # process down, so the real painting is isolated here and any fault is
        # logged and the last good frame simply remains on screen.
        try:
            self._paint_scene(_)
        except Exception as exc:
            try:
                from vision.utils import logger
                now = time.monotonic()
                if now - getattr(self, "_last_paint_err", 0.0) > 2.0:
                    self._last_paint_err = now
                    logger.error(f"Vision paint fault suppressed: {exc!r}")
            except Exception:
                pass

    def _paint_scene(self, _):
        p=QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r=QRectF(self.rect()).adjusted(1,1,-1,-1)
        W,H=self.width(),self.height()
        live = not self._frame.isNull()
        # Nothing dark sits behind or over a live feed: the glass field, grid
        # and glow bands are painted ONLY while there is no frame to show, so
        # the HUD chrome can never dim the camera picture.
        if not live:
            p.setBrush(QBrush(QColor(2,8,16,235)))
            p.setPen(Qt.PenStyle.NoPen)
            p.drawRoundedRect(r, 10, 10)
        p.save()
        p.setClipRect(r)
        if not live:
            p.setPen(QPen(QColor(0,170,210,24),1))
            for x in range(0,W,24):
                p.drawLine(x,0,x,H)
            for y in range(0,H,24):
                p.drawLine(0,y,W,y)
            # corner glow bands
            p.setPen(QPen(QColor(0,212,255,55),1)); p.drawLine(0,22,W,22)
            p.setPen(QPen(QColor(244,178,74,30),1)); p.drawLine(0,H-18,W,H-18)
        if live:
            key = (self._frame_serial, W, H, round(self._zoom, 3), self._invert,
                   72 if self._low_light else self._brightness)
            if key != self._cache_key or self._cache_img is None:
                self._rebuild_cache(W, H)
                self._cache_key = key
            if self._cache_img is not None:
                p.drawImage(QPointF(self._img_rect[0], self._img_rect[1]), self._cache_img)

            # ── OBJECT TELEMETRY monitor ─────────────────────────────────
            # Keep the feed model-neutral; backend names and load states are
            # diagnostic noise on the Vision surface. And it only earns its
            # place when inference is actually running — with YOLO off the
            # panel reported "SCANNING · NO OBJECTS", i.e. text over the
            # picture that the runtime could not justify.
            inference_running = self._live_inference and self._yolo_enabled
            if inference_running:
                st = self._inference_stats or {}
                tracker = str(st.get('tracker') or 'OFF').upper()
                dets = list(self._object_labels or [])

                panel_w = 252.0
                row_h = 18.0
                max_rows = 6
                rows = min(max_rows, len(dets))
                panel_h = 52.0 + row_h * rows if rows else 68.0
                px = max(8.0, W - panel_w - 10.0)
                py = max(48.0, H - panel_h - 40.0)
                panel = QRectF(px, py, panel_w, panel_h)

                p.setPen(QPen(QColor(88, 214, 245, 135), 1.0))
                p.setBrush(QBrush(QColor(2, 12, 20, 218)))
                p.drawRoundedRect(panel, 7.0, 7.0)

                self._draw_text(p, 'OBJECT TELEMETRY', px + 10, py + 17, 7, C.PRI)
                self._draw_text(
                    p,
                    f'TRACK {tracker if self._object_track else "OFF"} · OBJECTS {len(dets):02d}',
                    px + 10,
                    py + 34,
                    5,
                    C.GREEN if self._object_track else C.TEXT_DIM,
                )

                if dets:
                    for i, entry in enumerate(dets[:max_rows]):
                        try:
                            _ox, _oy, _ow, _oh, label, conf = entry[:6]
                            tid = int(entry[6]) if len(entry) > 6 else -1
                        except Exception:
                            continue
                        y = py + 52.0 + i * row_h
                        if i:
                            p.setPen(QPen(QColor(88, 214, 245, 24), 1.0))
                            p.drawLine(QPointF(px + 9, y - 9), QPointF(px + panel_w - 9, y - 9))
                        self._draw_text(p, f'#{tid}' if self._object_track and tid >= 0 else '—', px + 10, y, 5, C.ACC2)
                        self._draw_text(p, str(label)[:18], px + 43, y, 5, C.WHITE)
                        self._draw_text(p, f'{_pct(conf):02d}%', px + panel_w - 45, y, 5, C.PRI)


            if self._grid_overlay:
                p.setPen(QPen(QColor(88,214,245,34), 1))
                for gx in range(0, W + 1, 24):
                    p.drawLine(gx, 0, gx, H)
                for gy in range(0, H + 1, 24):
                    p.drawLine(0, gy, W, gy)

            # ── SCENE RADAR: live YOLO/local object inference ────────────
            # Boxes must draw whenever detections exist — whether SCENE RADAR
            # or YOLO CORE (or both) is what asked for them — not only when
            # the SCENE RADAR switch specifically is on. Otherwise turning on
            # YOLO CORE alone produced telemetry with no visible boxes.
            show_boxes = self._object_detection or self._yolo_enabled
            if show_boxes and self._object_labels:
                amber = QColor(244, 178, 74, 220)
                for entry in self._object_labels:
                    try:
                        ox, oy, ow, oh, label, conf = entry[:6]
                        ox, oy, ow, oh = float(ox), float(oy), float(ow), float(oh)
                        if not _finite_box((ox, oy, ow, oh)):
                            continue
                        tracker_id = int(entry[6]) if len(entry) > 6 else -1
                    except Exception:
                        continue
                    box = self._map_box(ox, oy, ow, oh)
                    self._corner_box(p, box, amber, arm=0.22)
                    tag = f'{label} {_pct(conf):02d}%'
                    if self._track_ids and tracker_id >= 0:
                        tag = f'#{tracker_id} · {tag}'
                    self._label_chip(p, tag, box.topLeft(), amber)
            # Do not paint backend/error status text over the camera.

            if self._inference_hud and inference_running:
                st = self._inference_stats or {}
                inf_ms = float(st.get('inference_ms') or 0.0)
                det_n = int(st.get('objects') or len(self._object_labels))
                tracker = str(st.get('tracker') or 'OFF').upper()
                lines = [
                    f'OBJECTS {det_n:02d}',
                    f'TRACK {tracker}',
                    f'LATENCY {inf_ms:04.1f} MS',
                ]
                base_x = max(8.0, W - 220.0)
                for i, line in enumerate(lines):
                    self._draw_text(p, line, base_x, 18 + i * 12, 5 if i == 0 else 5,
                                    C.PRI if i == 0 else C.TEXT_DIM)

            if self._motion_pulse:
                level = max(0.0, min(100.0, self._motion_level))
                bx, by, bw, bh = 10.0, H - 28.0, 118.0, 5.0
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QBrush(QColor(2, 14, 22, 180)))
                p.drawRoundedRect(QRectF(bx, by, bw, bh), 2.5, 2.5)
                p.setBrush(QBrush(QColor(88, 214, 245, 185)))
                p.drawRoundedRect(QRectF(bx, by, bw * level / 100.0, bh), 2.5, 2.5)
                self._draw_text(p, f'MOTION {level:04.1f}%', bx, by - 4, 5, C.TEXT_DIM)

            # ── FACE TRACK: brackets, names and expressions ───────────────
            if self._face_track and self._faces:
                cyan = QColor(88, 214, 245, 225)
                for (fx, fy, fw, fh) in self._faces:
                    box = self._map_box(fx, fy, fw, fh)
                    self._corner_box(p, box, cyan)
                    cx, cy = fx + fw / 2.0, fy + fh / 2.0
                    bits = []
                    if self._visible_name:
                        hit = self._nearest(self._names, cx, cy)
                        bits.append(hit[2] if hit else 'UNKNOWN')
                    if self._expression:
                        hit = self._nearest(self._expressions, cx, cy)
                        if hit:
                            bits.append(hit[2])
                    if bits:
                        self._label_chip(p, ' · '.join(bits), box.topLeft(), cyan)
                    # A soft crosshair on the tracked centre sells the lock-on.
                    c = self._map_point(cx, cy)
                    p.setPen(QPen(QColor(88, 214, 245, 110), 1.0))
                    p.drawLine(QPointF(c.x() - 5, c.y()), QPointF(c.x() + 5, c.y()))
                    p.drawLine(QPointF(c.x(), c.y() - 5), QPointF(c.x(), c.y() + 5))

            if self._center_reticle:
                cx, cy = W / 2.0, H / 2.0
                p.setPen(QPen(QColor(140,235,255,155), 1.1))
                p.drawLine(QPointF(cx - 22, cy), QPointF(cx + 22, cy))
                p.drawLine(QPointF(cx, cy - 22), QPointF(cx, cy + 22))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawEllipse(QPointF(cx, cy), 13, 13)

            if self._fps_hud:
                # Drawn on every repaint, not only on the repaints that happen
                # to coincide with a new frame — otherwise the readout blinks.
                self._draw_text(p, f'VISION {self._fps_value:04.1f} FPS', 10, 18, 6, C.PRI)
                if self._face_track:
                    self._draw_text(p, f'FACES {len(self._faces)}', 10, 30, 6, C.TEXT_DIM)

            if self._edge_outline:
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.setPen(QPen(QColor(88, 214, 245, 165), 1.2))
                p.drawRoundedRect(r, 9, 9)

            # No outer Vision frame or stroke unless EDGE TRACE is explicitly enabled.
        else:
            # Explicit connection state while the camera is starting. The old
            # "INITIALISING OPTICAL LINK" caption is gone: the stage-driven
            # progress indicator below now carries that information (operation +
            # real percentage), and drawing both read as duplicate text.
            status_x = max(8.0, (W - 240.0) / 2.0)
            self._draw_text(p, self._status, status_x, H/2 + 22, 7, C.PRI)
        # HUD corners
        p.setPen(QPen(QColor(88,214,245,190),1.8))
        L=22; m=7
        for x,y,dx,dy in ((m,m,1,1),(W-m,m,-1,1),(m,H-m,1,-1),(W-m,H-m,-1,-1)):
            p.drawLine(QPointF(x,y),QPointF(x+dx*L,y)); p.drawLine(QPointF(x,y),QPointF(x,y+dy*L))
        p.restore(); p.end()

class _ScaledImageLabel(QLabel):
    """Transparent Image View surface with smooth zoom + pan.

    Wheel = zoom around the centre, or around the pointer when already zoomed.
    Left-drag while zoomed = move/pan the image. Double-click = reset view.
    Right-click remains the existing Download / Go to menu.
    """

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setStyleSheet('background:transparent;border:none;')
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setMinimumSize(80, 80)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.setContextMenuPolicy(Qt.ContextMenuPolicy.DefaultContextMenu)
        self.setMouseTracking(True)
        self._source = QPixmap()
        self._zoom = 1.0
        self._pan = QPointF(0.0, 0.0)
        self._dragging = False
        self._drag_last = QPointF()

    def contextMenuEvent(self, event):
        try:
            host = self.parentWidget()
            while host is not None and not hasattr(host, 'show_image_context_menu'):
                host = host.parentWidget()
            if host is not None:
                host.show_image_context_menu(event.globalPos())
                event.accept()
                return
        except Exception:
            pass
        super().contextMenuEvent(event)

    def set_source_pixmap(self, pixmap) -> None:
        self._source = pixmap if isinstance(pixmap, QPixmap) else QPixmap()
        self.reset_view()
        self.update()

    def clear_image(self) -> None:
        self._source = QPixmap()
        self.reset_view()
        self.update()

    def has_image(self) -> bool:
        return not self._source.isNull()

    def reset_view(self) -> None:
        self._zoom = 1.0
        self._pan = QPointF(0.0, 0.0)
        self._dragging = False

    def zoom_factor(self) -> float:
        return float(self._zoom)

    def _fit_scale(self) -> float:
        if self._source.isNull() or self.width() <= 0 or self.height() <= 0:
            return 1.0
        return min(self.width() / max(1, self._source.width()),
                   self.height() / max(1, self._source.height()))

    def _image_rect(self) -> QRectF:
        if self._source.isNull():
            return QRectF()
        scale = self._fit_scale() * self._zoom
        w = self._source.width() * scale
        h = self._source.height() * scale
        center = QRectF(self.rect()).center() + self._pan
        return QRectF(center.x() - w / 2.0, center.y() - h / 2.0, w, h)

    def _clamp_pan(self) -> None:
        if self._source.isNull():
            self._pan = QPointF(0.0, 0.0)
            return
        rect = self._image_rect()
        view = QRectF(self.rect())
        # Keep enough of the image on-screen to make it easy to recover.
        max_x = max(0.0, (rect.width() - view.width()) / 2.0 + 16.0)
        max_y = max(0.0, (rect.height() - view.height()) / 2.0 + 16.0)
        self._pan.setX(max(-max_x, min(max_x, self._pan.x())))
        self._pan.setY(max(-max_y, min(max_y, self._pan.y())))

    def wheelEvent(self, event):
        if self._source.isNull():
            event.ignore()
            return
        delta = event.angleDelta().y()
        if not delta:
            event.ignore()
            return
        factor = 1.20 if delta > 0 else (1.0 / 1.20)
        old_zoom = self._zoom
        new_zoom = max(0.50, min(6.0, old_zoom * (factor ** max(1, abs(delta) // 120))))
        if abs(new_zoom - old_zoom) < 1e-6:
            event.accept()
            return

        # Keep the point under the cursor visually stable while zooming.
        cursor = event.position().toPoint()
        cx, cy = self.width() / 2.0, self.height() / 2.0
        local_x = cursor.x() - cx - self._pan.x()
        local_y = cursor.y() - cy - self._pan.y()
        ratio = new_zoom / old_zoom
        self._pan += QPointF(local_x * (1.0 - ratio), local_y * (1.0 - ratio))
        self._zoom = new_zoom
        self._clamp_pan()
        self.update()
        event.accept()

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton and self._zoom > 1.01:
            self._dragging = True
            self._drag_last = event.position()
            self.setCursor(Qt.CursorShape.ClosedHandCursor)
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._dragging and (event.buttons() & Qt.MouseButton.LeftButton):
            now = event.position()
            self._pan += now - self._drag_last
            self._drag_last = now
            self._clamp_pan()
            self.update()
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton and self._dragging:
            self._dragging = False
            self.setCursor(Qt.CursorShape.ArrowCursor)
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.reset_view()
            self.update()
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def paintEvent(self, event) -> None:
        if self._source.isNull():
            return
        p = QPainter(self)
        try:
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
            rect = self._image_rect()
            p.drawPixmap(rect, self._source, QRectF(self._source.rect()))
        except Exception:
            pass
        finally:
            p.end()

    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        self._clamp_pan()
        self.update()


class _ChatImagePreview(QLabel):
    """Resize-friendly image preview inside a native rounded chat card."""
    def __init__(self, pixmap: QPixmap, parent=None):
        super().__init__(parent)
        self._source = pixmap if isinstance(pixmap, QPixmap) else QPixmap()
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setMinimumSize(220, 120)
        self.setMaximumHeight(300)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
        self.setStyleSheet('background:transparent;border:none;')
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._render()

    def showEvent(self, event):
        super().showEvent(event)
        self._render()

    def _render(self):
        try:
            if self._source.isNull() or self.width() <= 0 or self.height() <= 0:
                return
            px = self._source.scaled(
                max(1, self.width() - 8), max(1, self.height() - 8),
                Qt.AspectRatioMode.KeepAspectRatio,
                Qt.TransformationMode.SmoothTransformation,
            )
            self.setPixmap(px)
        except Exception:
            pass


class _ChatAvatar(QWidget):
    """Small borderless circular profile avatar for chat rows."""
    def __init__(self, category: str, initial: str, parent=None, muted: bool = False):
        super().__init__(parent)
        self.setFixedSize(31, 31)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self._muted = bool(muted)
        self._category = str(category or 'jarvis').lower()
        self._initial = str(initial or 'J')[:1]
        self._pix = self._load_avatar()

    def _chat_host(self):
        w = self.parentWidget()
        while w is not None:
            if hasattr(w, '_profile_avatar_path'):
                return w
            w = w.parentWidget()
        return None

    def _load_avatar(self):
        base = Path(__file__).resolve().parent
        host = self._chat_host()
        candidates = []
        if self._category == 'you':
            configured = getattr(host, '_profile_avatar_path', None) if host is not None else None
            if configured:
                candidates.append(Path(str(configured)))
            candidates.append(base / 'assets' / 'user_avatar.png')
        elif self._category == 'jarvis':
            candidates.append(base / 'assets' / 'jarvis_avatar.png')
        for src in candidates:
            try:
                if src.exists():
                    px = QPixmap(str(src))
                    if not px.isNull():
                        return px
            except Exception:
                continue
        return QPixmap()

    def set_muted(self, muted: bool = True) -> None:
        self._muted = bool(muted)
        self.update()

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        if self._muted:
            p.setOpacity(0.42)
        r = QRectF(1, 1, self.width()-2, self.height()-2)
        path = QPainterPath(); path.addEllipse(r)
        p.save(); p.setClipPath(path)
        if not self._pix.isNull():
            px = self._pix.scaled(self.size(), Qt.AspectRatioMode.KeepAspectRatioByExpanding,
                                  Qt.TransformationMode.SmoothTransformation)
            src = QRectF(max(0.0, (px.width()-self.width())/2),
                         max(0.0, (px.height()-self.height())/2),
                         self.width(), self.height())
            p.drawPixmap(self.rect(), px, src.toRect())
        else:
            grad = QLinearGradient(0, 0, self.width(), self.height())
            if self._category == 'you':
                grad.setColorAt(0.0, QColor(34, 135, 194, 255))
                grad.setColorAt(1.0, QColor(8, 76, 121, 255))
                fg = C.WHITE
            else:
                grad.setColorAt(0.0, QColor(8, 62, 82, 255))
                grad.setColorAt(1.0, QColor(5, 28, 43, 255))
                fg = C.PRI
            p.fillPath(path, grad)
            p.setPen(QColor(fg)); p.setFont(QFont('Rajdhani', 11, QFont.Weight.Bold))
            p.drawText(self.rect(), Qt.AlignmentFlag.AlignCenter, self._initial)
        p.restore(); p.end()


# Precompiled chat-link patterns: hoisted out of the per-token _linkify() call
# so streaming a long reply stops paying the re.sub pattern-cache lookup and
# flags re-parse on every chunk (identical match semantics — compiled once here).
_CHAT_LINK_MD   = re.compile(r'\[([^\]]+)\]\((https?://[^\s\)]+)\)', re.I)
_CHAT_LINK_BARE = re.compile(r'(?<![="/])(https?://[^\s<]+)', re.I)


class _ChatBubble(QFrame):
    """Natural Messenger-style bubble with a soft gradient and no stroke."""
    def __init__(self, text: str, you: bool, parent=None, muted: bool = False):
        super().__init__(parent)
        self._you = bool(you)
        self._muted = bool(muted)
        self._raw_text = str(text or '')
        self._max_width = 460
        self.setObjectName('JarvisUserBubble' if self._you else 'JarvisAssistantBubble')
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setAutoFillBackground(False)
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Preferred)
        lay = QVBoxLayout(self)
        # Keep the bubble tight around the message.  The old 14px side padding
        # made very short messages (for example "hi") look like oversized
        # capsules with too much empty space on the left/right.
        lay.setContentsMargins(9, 7, 9, 8)
        lay.setSpacing(0)
        self._body = QLabel()
        self._body.setTextFormat(Qt.TextFormat.RichText)
        self._body.setOpenExternalLinks(True)
        self._body.setTextInteractionFlags(
            Qt.TextInteractionFlag.TextSelectableByMouse |
            Qt.TextInteractionFlag.LinksAccessibleByMouse
        )
        self._body.setWordWrap(True)
        self._body.setAlignment(Qt.AlignmentFlag.AlignRight if self._you else Qt.AlignmentFlag.AlignLeft)
        self._body.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        _body_color = '#8d9aa3' if self._muted else (C.WHITE if self._you else C.TEXT)
        self._body.setStyleSheet(
            f'color:{_body_color};'
            'font-family:Rajdhani;font-size:10pt;font-weight:560;'
            'background:transparent;border:none;padding:0;'
        )
        lay.addWidget(self._body)
        self.set_text(self._raw_text)

    @staticmethod
    def _linkify(text: str) -> str:
        import html
        safe = html.escape(str(text or '')).replace('\n', '<br/>')
        safe = _CHAT_LINK_MD.sub(
            lambda m: f'<a href="{html.escape(m.group(2), quote=True)}" style="color:{C.PRI};text-decoration:none;">{m.group(1)}</a>',
            safe)
        safe = _CHAT_LINK_BARE.sub(
            lambda m: f'<a href="{html.escape(m.group(1).rstrip(".,!?;:"), quote=True)}" style="color:{C.PRI};text-decoration:none;">{html.escape(m.group(1))}</a>',
            safe)
        return safe

    def set_text(self, text: str) -> None:
        self._raw_text = str(text or '')
        self._body.setText(self._linkify(self._raw_text))
        self._body.adjustSize()
        self._resize_naturally()

    def append_text(self, text: str) -> None:
        self._raw_text += str(text or '')
        self._body.setText(self._linkify(self._raw_text))
        self._body.adjustSize()
        self._resize_naturally()

    def _resize_naturally(self) -> None:
        if self._body is None:
            return

        fm = self._body.fontMetrics()
        plain = self._raw_text.replace('\r\n', '\n').replace('\r', '\n')
        lines = plain.split('\n') or ['']

        # Measure the real message text instead of forcing every bubble to a
        # fairly large minimum width.  This is what makes "hi" render like
        # a compact Messenger bubble instead of a wide rectangle.
        text_width = max((fm.horizontalAdvance(line) for line in lines), default=0)

        # Match the actual QVBoxLayout side margins above.  Keep only a tiny
        # safety minimum so an empty/very short message still has a usable
        # rounded shape.
        horizontal_padding = 18
        body_min_width = 1
        natural = max(body_min_width + horizontal_padding, text_width + horizontal_padding)
        width = min(self._max_width, max(28, natural))
        body_width = max(body_min_width, int(width) - horizontal_padding)

        self.setFixedWidth(int(width))
        self._body.setFixedWidth(body_width)
        self._body.updateGeometry()
        self.adjustSize()

    def set_bubble_width(self, width: int) -> None:
        # This is only the maximum allowed width.  Short messages are still
        # sized from their measured text in _resize_naturally().
        self._max_width = max(180, int(width))
        self._resize_naturally()

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(0.5, 0.5, self.width()-1.0, self.height()-1.0)
        radius = min(20.0, max(14.0, self.height() * 0.28))
        grad = QLinearGradient(r.topLeft(), r.bottomRight())
        if self._muted:
            # Previous-session message: a quiet grey-slate bubble.
            if self._you:
                grad.setColorAt(0.0, QColor(66, 78, 88, 205))
                grad.setColorAt(1.0, QColor(40, 49, 58, 205))
            else:
                grad.setColorAt(0.0, QColor(44, 54, 62, 190))
                grad.setColorAt(1.0, QColor(28, 35, 42, 190))
        elif self._you:
            grad.setColorAt(0.0, QColor(36, 140, 205, 248))
            grad.setColorAt(1.0, QColor(7, 79, 132, 248))
        else:
            grad.setColorAt(0.0, QColor(12, 53, 70, 248))
            grad.setColorAt(1.0, QColor(5, 26, 41, 248))
        path = QPainterPath()
        path.addRoundedRect(r, radius, radius)
        p.fillPath(path, grad)
        p.end()
        super().paintEvent(event)


class _ChatMessageRow(QWidget):
    """Messenger-style row: circular profile icon + name/time + natural bubble."""
    def __init__(self, who: str, text: str, you: bool, color: str, parent=None, muted: bool = False):
        super().__init__(parent)
        self._muted = bool(muted)
        if self._muted:
            color = '#7b8791'
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setStyleSheet('background:transparent;border:none;')
        row = QHBoxLayout(self)
        row.setContentsMargins(2, 1, 2, 1)
        row.setSpacing(7)
        self._column = QVBoxLayout()
        self._column.setContentsMargins(0, 0, 0, 0)
        self._column.setSpacing(3)
        meta = QLabel()
        meta.setTextFormat(Qt.TextFormat.RichText)
        meta.setAlignment(Qt.AlignmentFlag.AlignRight if you else Qt.AlignmentFlag.AlignLeft)
        stamp = time.strftime('%I:%M %p').lstrip('0') or '12:00 AM'
        meta.setText(
            f'<span style="color:{color};font-family:Orbitron;font-size:7.8pt;font-weight:700;">'
            f'{self._esc(who)}</span> '
            f'<span style="color:{C.TEXT_DIM};font-family:Rajdhani;font-size:6.3pt;font-weight:400;">'
            f'{stamp}</span>'
        )
        meta.setStyleSheet('background:transparent;border:none;padding:0 2px;')
        self._column.addWidget(meta)
        self._bubble = _ChatBubble(text, you, self, muted=self._muted)
        self._column.addWidget(
            self._bubble, 0,
            Qt.AlignmentFlag.AlignRight if you else Qt.AlignmentFlag.AlignLeft
        )
        avatar = _ChatAvatar('you' if you else 'jarvis', 'Y' if you else 'J', self,
                             muted=self._muted)
        if you:
            row.addStretch(1)
            row.addLayout(self._column, 0)
            row.addSpacing(2)
            row.addWidget(avatar, 0, Qt.AlignmentFlag.AlignTop | Qt.AlignmentFlag.AlignRight)
        else:
            row.addWidget(avatar, 0, Qt.AlignmentFlag.AlignTop)
            row.addLayout(self._column, 0)
            row.addStretch(1)
        self._avatar = avatar

    def play_entrance_animation(self, delay: int = 0) -> None:
        """Messenger-like fade/reveal for a newly inserted message row."""
        def _start():
            try:
                self.setMinimumHeight(0)
                target = max(1, self.sizeHint().height())
                effect = QGraphicsOpacityEffect(self)
                self.setGraphicsEffect(effect)
                effect.setOpacity(0.0)

                self.setMaximumHeight(1)
                fade = QPropertyAnimation(effect, b'opacity', self)
                fade.setDuration(180)
                fade.setStartValue(0.0)
                fade.setEndValue(1.0)
                fade.setEasingCurve(QEasingCurve.Type.OutCubic)

                reveal = QPropertyAnimation(self, b'maximumHeight', self)
                reveal.setDuration(220)
                reveal.setStartValue(1)
                reveal.setEndValue(target)
                reveal.setEasingCurve(QEasingCurve.Type.OutCubic)

                self._entrance_anims = (fade, reveal)
                def _done():
                    try:
                        self.setMaximumHeight(16777215)
                        self.setGraphicsEffect(None)
                        self.updateGeometry()
                    except Exception:
                        pass
                    self._entrance_anims = ()
                reveal.finished.connect(_done)
                fade.start(QAbstractAnimation.DeletionPolicy.DeleteWhenStopped)
                reveal.start(QAbstractAnimation.DeletionPolicy.DeleteWhenStopped)
            except Exception:
                try:
                    self.setMaximumHeight(16777215)
                    self.setGraphicsEffect(None)
                except Exception:
                    pass
        if delay > 0:
            QTimer.singleShot(int(delay), _start)
        else:
            QTimer.singleShot(0, _start)

    def set_max_width(self, width: int) -> None:
        self._bubble.set_bubble_width(max(220, int(width)))
        self.updateGeometry()

    def append_text(self, text: str) -> None:
        self._bubble.append_text(text)
        self.updateGeometry()

    def full_text(self) -> str:
        return self._bubble._raw_text

    @staticmethod
    def _esc(v: str) -> str:
        import html
        return html.escape(str(v or ''))


