# Give image cards their own painted gradient without introducing any border.
def _chat_image_card_paint(self, event):
    p = QPainter(self); p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    r = QRectF(0.5, 0.5, self.width()-1.0, self.height()-1.0)
    grad = QLinearGradient(r.topLeft(), r.bottomRight())
    owner = self.parentWidget()
    you = bool(getattr(owner, '_you', False))
    if you:
        grad.setColorAt(0.0, QColor(28, 125, 188, 248)); grad.setColorAt(1.0, QColor(7, 74, 126, 248))
    else:
        grad.setColorAt(0.0, QColor(12, 52, 69, 248)); grad.setColorAt(1.0, QColor(5, 25, 40, 248))
    path = QPainterPath(); path.addRoundedRect(r, 18, 18)
    p.fillPath(path, grad); p.end()
    QFrame.paintEvent(self, event)

# QFrame does not support per-instance paint method cleanly on all PyQt6 builds,
# so bind this after class creation; the method only paints the rounded fill.
_OriginalChatImageInit = _ChatImageRow.__init__
def _ChatImageRowInit(self, pixmap, caption, you, parent=None):
    _OriginalChatImageInit(self, pixmap, caption, you, parent)
    self._card.paintEvent = _chat_image_card_paint.__get__(self._card, QFrame)
_ChatImageRow.__init__ = _ChatImageRowInit


class _TypingIndicatorRow(QWidget):
    """Messenger-like J.A.R.V.I.S. typing row. Only dots animate inside chat."""
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setStyleSheet('background:transparent;border:none;')
        row = QHBoxLayout(self); row.setContentsMargins(2, 1, 2, 1); row.setSpacing(7)
        avatar = _ChatAvatar('jarvis', 'J', self); row.addWidget(avatar, 0, Qt.AlignmentFlag.AlignTop)
        col = QVBoxLayout(); col.setContentsMargins(0,0,0,0); col.setSpacing(3)
        meta = QLabel('J.A.R.V.I.S.')
        meta.setStyleSheet(f'color:{C.PRI};font:700 7.8pt Orbitron;background:transparent;border:none;padding:0 2px;')
        col.addWidget(meta)
        self._bubble = QFrame(self)
        self._bubble.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self._bubble.setMinimumSize(0, 34)
        self._bubble.setMaximumWidth(120)
        self._bubble.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        self._bubble.setFixedHeight(34)
        # Messenger-style typing bubble: the animated dots start from the
        # left instead of being centered in the capsule.
        bl = QHBoxLayout(self._bubble); bl.setContentsMargins(11, 5, 11, 5); bl.setSpacing(0)
        self._dots = QLabel('·')
        self._dots.setAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
        self._dots.setStyleSheet(f'color:{C.WHITE};font:800 16pt Rajdhani;background:transparent;border:none;padding:0;')
        bl.addWidget(self._dots)
        # Bind the painter to the BUBBLE itself. The previous form
        # (self._paint_bubble.__get__(...)) was a no-op: __get__ on an
        # already-bound method returns it unchanged, so the handler stayed
        # bound to this ROW and every repaint raised
        # "TypeError: paintEvent(...) first argument ... must have type
        # 'QFrame'" — one captured auto-heal fault per frame.
        self._bubble.paintEvent = types.MethodType(
            _TypingIndicatorRow._paint_bubble, self._bubble)
        col.addWidget(self._bubble, 0, Qt.AlignmentFlag.AlignLeft)
        row.addLayout(col, 0); row.addStretch(1)
        self._frames = ('·', '··', '···', '··')
        self._i = 0
        try:
            self._bubble.setFixedWidth(max(32, self._dots.fontMetrics().horizontalAdvance('·') + 24))
        except Exception:
            pass
        self._timer = QTimer(self)
        self._timer.setInterval(260)
        self._timer.timeout.connect(self._tick)
        self._timer.start()

    def _tick(self):
        self._i = (self._i + 1) % len(self._frames)
        text = self._frames[self._i]
        self._dots.setText(text)
        # Keep the typing bubble as tight as the animated dots themselves.
        try:
            natural = max(14, self._dots.fontMetrics().horizontalAdvance(text)) + 24
            self._bubble.setFixedWidth(min(72, natural))
        except Exception:
            pass

    def stop(self):
        self._timer.stop()

    def _paint_bubble(self, event):
        # Decorative paint: it must never propagate into the crash/auto-heal
        # sentry. The painter is always ended, and the base paint is guarded.
        try:
            p = QPainter(self)
            try:
                p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
                r = QRectF(0.5, 0.5, self.width()-1.0, self.height()-1.0)
                grad = QLinearGradient(r.topLeft(), r.bottomRight())
                grad.setColorAt(0.0, QColor(12, 53, 70, 248)); grad.setColorAt(1.0, QColor(5, 26, 41, 248))
                path = QPainterPath(); path.addRoundedRect(r, 16, 16)
                p.fillPath(path, grad)
            finally:
                p.end()
        except Exception:
            pass
        try:
            QFrame.paintEvent(self, event)
        except Exception:
            pass


class _FileAttachmentCard(QFrame):
    """TASK 6: compact rounded chat attachment card — file icon, the ACTUAL
    filename, and the ACTUAL file type/description underneath. It reads the real
    path; nothing about the name or type is hardcoded."""
    _MAX_NAME_W = 210

    def __init__(self, path: Path, size_text: str = "", parent=None):
        super().__init__(parent)
        self.setObjectName('FileAttachmentCard')
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
