        stage_g = QGridLayout(self._vision_camera_stage)
        stage_g.setContentsMargins(2,2,2,2); stage_g.setSpacing(6)
        stage_g.setColumnStretch(1, 1)

        # Unified left-side Vision control surface. All switches are labeled,
        # icon/emoji-free, and live inside a wheel-scrollable container that is
        # COLLAPSED BY DEFAULT: the camera owns the whole stage until the
        # top-left handle opens the drawer.
        vision_scroll = QScrollArea(self._vision_camera_stage)
        vision_scroll.setMinimumWidth(0)
        vision_scroll.setMaximumWidth(0)
        vision_scroll.setWidgetResizable(True)
        vision_scroll.setFrameShape(QFrame.Shape.NoFrame)
        vision_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        vision_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        vision_scroll.setStyleSheet(
            'QScrollArea { background:transparent; border:none; }'
            'QScrollBar:vertical { width:6px; margin:2px 0 2px 0; background:transparent; border:none; }'
            'QScrollBar::handle:vertical { background:rgba(88,214,245,120); border-radius:3px; min-height:30px; }'
            'QScrollBar::handle:vertical:hover { background:rgba(88,214,245,205); }'
            'QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height:0px; border:none; background:transparent; }'
            'QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background:transparent; }'
        )
        vision_scroll.viewport().setStyleSheet('background:transparent; border:none;')
        vision_scroll.hide()

        vision_controls = QFrame()
        vision_controls.setObjectName('VisionControlScroll')
        vision_controls.setMinimumWidth(206)
        vision_controls.setStyleSheet('QFrame#VisionControlScroll { background:transparent; border:none; }')
        controls_l = QVBoxLayout(vision_controls)
        controls_l.setContentsMargins(8,8,8,8)
        controls_l.setSpacing(6)

        controls_head = QHBoxLayout()
        controls_head.setContentsMargins(1, 0, 1, 0)
        controls_head.setSpacing(7)
        controls_head.setAlignment(Qt.AlignmentFlag.AlignVCenter)
        controls_title = QLabel('VISION CONTROLS')
        controls_title.setStyleSheet(f'color:{C.PRI};font:900 8.2pt "Orbitron";letter-spacing:1.05px;background:transparent;')
        controls_head.addWidget(controls_title, 1)
        controls_l.addLayout(controls_head)

        self._vision_face_track = _VisionSwitch('FACE VECTOR', vision_controls, tip='Follow the largest detected face')
        self._vision_face_track.setChecked(True)
        controls_l.addWidget(self._vision_face_track)


        self._vision_object_track = _VisionSwitch('OBJECT TRACK', vision_controls, tip='Track each detected object and keep a persistent target ID')
        self._vision_object_track.setChecked(True)
        controls_l.addWidget(self._vision_object_track)

        self._vision_expression = _VisionSwitch('EXPRESSION SCAN', vision_controls, tip='Enable facial expression analysis')
        controls_l.addWidget(self._vision_expression)

        self._vision_visible_name = _VisionSwitch('IDENTITY TAG', vision_controls, tip='Display the configured name for detected faces')
        self._vision_visible_name.setChecked(True)
        controls_l.addWidget(self._vision_visible_name)

        self._vision_face_zoom = _VisionSwitch('FACE FOCUS', vision_controls, tip='Smoothly zoom toward the tracked face')
        controls_l.addWidget(self._vision_face_zoom)

        self._vision_object_detection = _VisionSwitch('SCENE RADAR', vision_controls, tip='Enable object-recognition reporting')
        self._vision_object_detection.setChecked(True)
        controls_l.addWidget(self._vision_object_detection)

        self._vision_yolo_engine = _VisionSwitch('OBJECT ENGINE', vision_controls, tip='Use the local object detector when available')
        self._vision_yolo_engine.setChecked(False)
        controls_l.addWidget(self._vision_yolo_engine)

        self._vision_live_inference = _VisionSwitch('OBJECT TELEMETRY', vision_controls, tip='Show live object count, tracking and latency')
        self._vision_live_inference.setChecked(True)
        controls_l.addWidget(self._vision_live_inference)

        self._vision_invert = _VisionSwitch('MIRROR FEED', vision_controls, tip='Mirror the camera horizontally')
        controls_l.addWidget(self._vision_invert)

        self._vision_grid_overlay = _VisionSwitch('GRID SCAN', vision_controls, tip='Show a subtle Vision alignment grid over the feed')
        controls_l.addWidget(self._vision_grid_overlay)

        self._vision_fps_hud = _VisionSwitch('FRAME RATE', vision_controls, tip='Show the live camera frame rate')
        controls_l.addWidget(self._vision_fps_hud)

        self._vision_low_light = _VisionSwitch('LOW-LIGHT LIFT', vision_controls, tip='Increase the display lift for a darker camera feed')
        controls_l.addWidget(self._vision_low_light)

        self._vision_center_reticle = _VisionSwitch('AIM RETICLE', vision_controls, tip='Show a central alignment reticle')
        controls_l.addWidget(self._vision_center_reticle)

        self._vision_edge_outline = _VisionSwitch('EDGE TRACE', vision_controls, tip='Keep a clean cyan outline around the camera surface')
        self._vision_edge_outline.setChecked(True)
        controls_l.addWidget(self._vision_edge_outline)

        self._vision_track_ids = _VisionSwitch('TRACK IDS', vision_controls, tip='Show persistent IDs when the detector can provide them')
        self._vision_track_ids.setChecked(True)
        controls_l.addWidget(self._vision_track_ids)

        self._vision_inference_hud = _VisionSwitch('INFERENCE HUD', vision_controls, tip='Show live model, device, latency, task, object count and tracker telemetry')
        self._vision_inference_hud.setChecked(True)
        controls_l.addWidget(self._vision_inference_hud)

        self._vision_motion_pulse = _VisionSwitch('MOTION PULSE', vision_controls, tip='Measure frame-to-frame movement locally without uploading camera frames')
        controls_l.addWidget(self._vision_motion_pulse)

        self._vision_person_filter = _VisionSwitch('PERSON FILTER', vision_controls, tip='Show only detections labelled person')
        controls_l.addWidget(self._vision_person_filter)

        # Dedicated expandable object-inference control surface. It is its
        # own collapsible card (chevron header) rather than more flat switches,
        # grouping every real inference control in one place.
        self._inference_panel = _InferenceControlPanel(vision_controls)
        self._inference_panel.options_changed.connect(self._on_inference_panel_changed)
        controls_l.addWidget(self._inference_panel)

        controls_l.addStretch(1)
        vision_scroll.setWidget(vision_controls)
        stage_g.addWidget(vision_scroll, 0, 0)

        self._vision_control_scroll = vision_scroll
        self._vision_control_panel = vision_controls

        self._camera_view = _InlineVisionView(self._vision_camera_stage)
        self._camera_view.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        stage_g.addWidget(self._camera_view, 0, 1)

        # Floating corner controls. Both are icon-only and stay reachable
