        self._vision_exit_btn.clicked.connect(lambda _=False: self._on_vision_toggled(False))
        stage_g.addWidget(self._vision_exit_btn, 0, 1, corner.AlignRight | corner.AlignTop)

        visual.addWidget(self._vision_camera_stage)

        # -- Image Panel: title-less, transparent, Exit-only image stage --
