        self._image_view_stage = QWidget(visual)
        self._image_view_stage.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self._image_view_stage.setStyleSheet('background:transparent;border:none;')
        img_g = QGridLayout(self._image_view_stage)
        img_g.setContentsMargins(2, 2, 2, 2)
        img_g.setSpacing(0)
        img_g.setColumnStretch(0, 1)
