        self._image_view_exit_btn.clicked.connect(lambda _=False: self.clear_inline_vision())
        img_g.addWidget(self._image_view_exit_btn, 0, 0, corner.AlignRight | corner.AlignTop)

        self._image_view_open = False
        self._image_view_caption_text = ""
        self._image_view_source_url = ""
        visual.addWidget(self._image_view_stage)

        # -- Video View: title-less, transparent, embedded stage --
        self._video_view_stage = QWidget(visual)
