        self._video_view_stage.setStyleSheet('background:transparent;border:none;')
        vid_g = QGridLayout(self._video_view_stage); vid_g.setContentsMargins(2,2,2,2); vid_g.setSpacing(0)
        self._video_view = _InlineVideoView(self._video_view_stage); vid_g.addWidget(self._video_view,0,0)
        self._video_view_exit_btn = _VisionCornerButton('x', self._video_view_stage, tip='Exit Video View and return to the reactor view', tint=C.RED)
        self._video_view_exit_btn.clicked.connect(lambda _=False: self.clear_inline_video())
        vid_g.addWidget(self._video_view_exit_btn,0,0,Qt.AlignmentFlag.AlignRight|Qt.AlignmentFlag.AlignTop)
        self._video_view_open=False; self._video_view_source=''; self._video_view_caption=''
        visual.addWidget(self._video_view_stage)

        # -- History / Tasks: standalone desktop window --------------------
