        right_wrap = QWidget(dashboard)
        right_wrap.setFixedWidth(168)
        right_wrap.setMinimumWidth(0)
        right_wrap.setMaximumWidth(168)
        right_wrap.setObjectName('VisionRightGroup')
        right_wrap.setStyleSheet('QWidget#VisionRightGroup { background:transparent; border:none; }')
        right_col = QVBoxLayout(right_wrap); right_col.setContentsMargins(0,0,0,0); right_col.setSpacing(7)
        right_col.addWidget(hud_card('QUICK INFO', [
            ('uptime', 'Uptime', '--:--', '◷'), ('user', 'User', '—', '●'),
            ('ip', 'IP', '--', '⌁'), ('zone', 'Zone', '—', '⌖')
        ]))
        # -- Live J.A.R.V.I.S. activity monitor ------------------------
        doing_card = QFrame(dashboard)
        doing_card.setObjectName('JarvisDoingCard')
        doing_card.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        doing_card.setStyleSheet(
            f'QFrame#JarvisDoingCard {{ background:rgba(3,18,30,145); border:none; border-radius:10px; }}'
            'QLabel { background:transparent; border:none; }'
        )
        doing_layout = QVBoxLayout(doing_card)
        doing_layout.setContentsMargins(10, 8, 10, 8)
        doing_layout.setSpacing(3)
        doing_title = QLabel('ACTIVITY')
        doing_title.setStyleSheet(f'color:{C.PRI}; font:900 6.9pt "Orbitron"; letter-spacing:1.15px;')
        doing_layout.addWidget(doing_title)
        doing_line = QFrame()
        doing_line.setFixedHeight(1)
        doing_line.setStyleSheet(f'background:{C.BORDER_B}; border:none;')
        doing_layout.addWidget(doing_line)

        # Current-action readout belongs to the ReferenceDashboard itself.
        # This replaces the old descriptive activity banner in the bottom rail.
        doing_now_title = QLabel('WHAT J.A.R.V.I.S. IS DOING')
        doing_now_title.setStyleSheet(
            f'color:{C.TEXT_DIM}; font:800 5.35pt "Orbitron"; '
            f'letter-spacing:0.85px; background:transparent;'
        )
        doing_layout.addWidget(doing_now_title)
        self._doing_now_label = QLabel('● READY')
        self._doing_now_label.setMinimumHeight(23)
        self._doing_now_label.setAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
        self._doing_now_label.setToolTip('Current J.A.R.V.I.S. activity')
        self._doing_now_label.setStyleSheet(
            f'color:{C.TEXT_DIM}; font:700 6.15pt "Share Tech Mono"; '
            f'letter-spacing:0.1px; background:rgba(0,212,255,12); '
            f'border:none; padding:0 4px; border-radius:4px;'
        )
        doing_layout.addWidget(self._doing_now_label)

        self._doing_rows = {}
        self._doing_effects = {}
        self._doing_animations = {}
        self._doing_pulse_animations = {}
        self._doing_generation = {}
        for category in ('SEARCH', 'CODE', 'REVIEW', 'VIEW', 'FIND', 'GENERATE', 'ANALYZE', 'AUTOMATE'):
            row = _ActivityRow(category, doing_card)
            detail = row.detail_label
            effect = QGraphicsOpacityEffect(row)
            effect.setOpacity(0.52)
            row.setGraphicsEffect(effect)
            self._doing_rows[category] = (row, detail)
            self._doing_effects[category] = effect
            self._doing_generation[category] = 0
            doing_layout.addWidget(row)

        # ── Laya runtime status ────────────────────────────────────────────
        # A small, unobtrusive line showing whether the local decision AI is
        # ACTUALLY driving the current activity — not whether it is enabled in
        # Settings. main.py drives it from the real classification lifecycle
        # (NOT USED → ACTIVE while deciding → COMPLETE once it routed the task).
        doing_layout.addSpacing(3)
        self._laya_status_state = 'idle'
        self._laya_status_label = QLabel('')
        self._laya_status_label.setMinimumHeight(19)
        self._laya_status_label.setAlignment(
            Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
        self._laya_status_label.setToolTip(
            'Whether Laya (the local decision AI) is actually used for the '
            'current activity — reflects real execution, not the Settings flag.')
        doing_layout.addWidget(self._laya_status_label)
        self.set_laya_status('NOT USED', 'idle')

        # ── Brain mode (Gemini conversation ⇄ UI TARS PC control) ──────────
        # A persistent readout of what the chat panel's icon switch is set to,
        # so the current mode is visible on the dashboard itself and does not
        # depend on hovering the button. The value comes from the saved
        # features.ui_tars_mode flag, never from a guess.
        try:
            _mode_on = bool(((_read_full_config().get('features') or {})
                             .get('ui_tars_mode', False)))
        except Exception:
            _mode_on = False
        self._mode_status_state = 'gemini'
        self._mode_status_label = QLabel('')
        self._mode_status_label.setMinimumHeight(19)
        self._mode_status_label.setAlignment(
            Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
        doing_layout.addWidget(self._mode_status_label)
        self.set_mode_status(_mode_on)

