        _lbl.setStyleSheet(
            f'color:{C.PRI}; font:800 7pt "Orbitron"; letter-spacing:1.5px; '
            f'background:transparent;'
        )
        chat_hdr.addWidget(_lbl)
        chat_hdr.addStretch(1)
        # Chat History is a mode of the Chat Log itself. Use the exact same
