def _blur_pixmap(src_pix, strength: int = 10):
    """Soft background blur with no dependencies: shrink, then smooth-scale back.

    Two passes of shrink/enlarge approximate a gaussian well enough for a frosted
    glass backdrop, and cost a few milliseconds even on a large panel. Never raises.
    """
    try:
        if src_pix is None or src_pix.isNull():
            return QPixmap()
        dpr = src_pix.devicePixelRatio() or 1.0
        w, h = src_pix.width(), src_pix.height()
        out = src_pix
        for div in (max(2, int(strength)), max(2, int(strength) // 2)):
            small = out.scaled(
                max(1, w // div), max(1, h // div),
                Qt.AspectRatioMode.IgnoreAspectRatio,
                Qt.TransformationMode.SmoothTransformation)
            out = small.scaled(
                w, h, Qt.AspectRatioMode.IgnoreAspectRatio,
                Qt.TransformationMode.SmoothTransformation)
        out.setDevicePixelRatio(dpr)
        return out
    except Exception:
        return QPixmap()


def _paint_glass_glow(p, rect, radius: float, accent, layers: int = 5) -> None:
    """Soft neon halo drawn as stacked translucent strokes (no graphics effect,
    so scrolling the lists inside the panel stays cheap)."""
    try:
        for i in range(layers):
            col = QColor(accent)
            col.setAlpha(max(4, 34 - i * 6))
            p.setPen(QPen(col, 2.0 + i * 2.0))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRoundedRect(rect, radius, radius)
    except Exception:
        pass


class _HistoryGlassPanel(QFrame):
    """One self-contained glass panel: gradient fill, neon glow, own header.

    Chat History uses two of these side by side (conversations on the left,
    transcript on the right) so each list owns its own scroll container.
    """

    _INSET = 7  # room around the panel for the glow

    def __init__(self, title: str, parent=None):
        super().__init__(parent)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setFrameShape(QFrame.Shape.NoFrame)
        pad = self._INSET + 10
        self._root = QVBoxLayout(self)
        self._root.setContentsMargins(pad, pad - 2, pad, pad)
        self._root.setSpacing(8)

        head = QHBoxLayout()
        head.setContentsMargins(2, 0, 2, 0)
        head.setSpacing(8)
        mark = QLabel('\u25c6')
        mark.setStyleSheet(
            f"color:{C.PRI};background:transparent;font:700 7pt 'Orbitron';")
        head.addWidget(mark, 0)
        self._title = QLabel(str(title).upper())
        self._title.setStyleSheet(
            f"color:{C.PRI};background:transparent;border:none;"
            f"font:900 7.6pt 'Orbitron';letter-spacing:1.8px;")
        head.addWidget(self._title, 1)
        self._badge = QLabel('')
        self._badge.setAlignment(
            Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        self._badge.setStyleSheet(
            f"color:{C.TEXT_DIM};background:transparent;border:none;"
            f"font:700 6.6pt 'Exo 2';letter-spacing:0.8px;")
        head.addWidget(self._badge, 0)
        self._root.addLayout(head)

        rule = QFrame()
        rule.setFixedHeight(1)
        rule.setStyleSheet(
            f"background:qlineargradient(x1:0,y1:0,x2:1,y2:0,"
            f"stop:0 {C.PRI},stop:1 rgba(0,0,0,0));border:none;")
        self._root.addWidget(rule)

    def set_title(self, text: str) -> None:
        self._title.setText(str(text or '').upper())

    def set_badge(self, text: str) -> None:
        self._badge.setText(str(text or ''))

    def set_body(self, widget) -> None:
        self._root.addWidget(widget, 1)

    def paintEvent(self, event) -> None:
        p = QPainter(self)
        try:
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            i = float(self._INSET)
            r = QRectF(self.rect()).adjusted(i, i, -i, -i)
            radius = 14.0
            accent = qcol(C.PRI)

            _paint_glass_glow(p, r, radius, accent)

            path = QPainterPath()
            path.addRoundedRect(r, radius, radius)
            fill = QLinearGradient(r.topLeft(), r.bottomRight())
            fill.setColorAt(0.0, QColor(10, 62, 92, 178))
            fill.setColorAt(0.5, QColor(4, 30, 50, 168))
            fill.setColorAt(1.0, QColor(2, 12, 24, 205))
            p.fillPath(path, QBrush(fill))

            # soft light bloom from the top-left corner
            bloom = QRadialGradient(r.left() + r.width() * 0.12, r.top(),
                                    max(r.width(), r.height()) * 0.75)
            top = QColor(accent)
            top.setAlpha(46)
            bloom.setColorAt(0.0, top)
            bloom.setColorAt(1.0, QColor(0, 0, 0, 0))
            p.fillPath(path, QBrush(bloom))

            edge = QLinearGradient(r.topLeft(), r.bottomRight())
            hi = QColor(accent)
            hi.setAlpha(210)
            lo = QColor(accent)
            lo.setAlpha(60)
            edge.setColorAt(0.0, hi)
            edge.setColorAt(0.5, lo)
            edge.setColorAt(1.0, hi)
            p.setPen(QPen(QBrush(edge), 1.2))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
        except Exception:
            pass
        p.end()


class ConversationHistoryPage(QWidget):
    """The real conversation history, presented directly as a scrollable HUD timeline."""

    def __init__(self, host=None, parent=None):
        super().__init__(parent)
        self._host = host
        self._rows: list[dict] = []
        self._map: dict[int, dict] = {}
        self._cards: dict[str, _HistoryConversationCard] = {}
        self._selected = ''
        self._loaded = False
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setStyleSheet('background:transparent;border:none;')

        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(6)

        # History toolbar — NEW CHAT is intentionally first so starting a fresh
        # conversation is always one click away. Every button uses the same
        # angular gradient/cut-corner style as the main navigation tabs.
        # Two rows keep the toolbar readable in the portrait history window:
        # NEW CHAT + BACK + search on top, the management actions beneath it.
        head = QHBoxLayout()
        head.setContentsMargins(2, 0, 2, 0)
        head.setSpacing(5)

        new_chat = self._tab_button(
            'NEW CHAT', 'chat', self._new,
            'Start a completely new conversation'
        )
        new_chat.setMinimumWidth(92)
        head.addWidget(new_chat)

        back = self._tab_button('BACK', 'x', self._close, 'Return to the Chat Log')
        head.addWidget(back)

        self._search = QLineEdit()
        self._search.setPlaceholderText('Search conversations…')
        self._search.setMinimumHeight(34)
        self._search.setMinimumWidth(60)
        self._search.setStyleSheet(_hud_field_css())
        self._search.returnPressed.connect(lambda: self.reload(self._search.text()))
        head.addWidget(self._search, 1)
        lay.addLayout(head)

        actions = QHBoxLayout()
        actions.setContentsMargins(2, 0, 2, 0)
        actions.setSpacing(5)

        for label, icon, slot, tip in (
            ('RESUME', 'chat', self._resume, 'Continue the selected conversation'),
            ('RENAME', None, self._rename, 'Rename the selected conversation'),
            ('DELETE', 'x', self._delete, 'Delete the selected conversation'),
            ('EXPORT', None, self._export, 'Export the selected conversation'),
            ('IMPORT', None, self._import, 'Import a conversation file'),
            ('CLEAR', 'x', self._clear_all, 'Delete every conversation'),
        ):
            button = self._tab_button(label, icon, slot, tip)
            button.setMinimumWidth(0)
            button.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
            actions.addWidget(button, 1)

        lay.addLayout(actions)

        self._status = QLabel('HISTORY · READING CONVERSATIONS…')
        self._status.setMinimumHeight(22)
        self._status.setAlignment(
            Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter
        )
        self._status.setStyleSheet(
            f"color:{C.TEXT_DIM};background:{C.PRI_GHO};border:none;"
            f"font:700 6.5pt 'Exo 2';letter-spacing:0.75px;padding:1px 8px;"
        )
        lay.addWidget(self._status)

        # Left | right, not top / bottom: conversations on the left, the selected
        # transcript on the right, each in its own glass panel with its own scroll.
        columns = QHBoxLayout()
        columns.setContentsMargins(0, 0, 0, 0)
        columns.setSpacing(2)

        self._left_panel = _HistoryGlassPanel('Conversations')
        self._right_panel = _HistoryGlassPanel('Transcript')

        self._timeline = QListWidget()
        self._timeline.setObjectName('JARVISHIStoryTimeline')
        self._timeline.setFrameShape(QFrame.Shape.NoFrame)
        self._timeline.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self._timeline.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self._timeline.setVerticalScrollMode(QAbstractItemView.ScrollMode.ScrollPerPixel)
        self._timeline.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        self._timeline.setSpacing(6)
        self._timeline.setStyleSheet(
            'QListWidget#JARVISHIStoryTimeline { background:transparent;border:none; }'
            'QListWidget#JARVISHIStoryTimeline::item { background:transparent;border:none;margin:0;padding:0; }'
            + _theme_scrollbar_css(5)
        )
        self._timeline.currentRowChanged.connect(self._on_row)
        # Single click selects/previews; double-click opens the conversation in
        # the main Chat Log so the user can continue exactly where they left off.
        self._timeline.itemDoubleClicked.connect(self._on_double_click)
        self._left_panel.set_body(self._timeline)
        self._left_panel.setMinimumWidth(170)
        columns.addWidget(self._left_panel, 5)

        self._preview = QListWidget()
        self._preview.setObjectName('JARVISHistoryPreview')
        self._preview.setFrameShape(QFrame.Shape.NoFrame)
        self._preview.setSelectionMode(QAbstractItemView.SelectionMode.NoSelection)
        self._preview.setVerticalScrollMode(QAbstractItemView.ScrollMode.ScrollPerPixel)
        self._preview.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self._preview.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self._preview.setStyleSheet(
            'QListWidget#JARVISHistoryPreview { background:transparent;border:none; }'
            'QListWidget#JARVISHistoryPreview::item {'
            'background:qlineargradient(x1:0,y1:0,x2:1,y2:1,'
            'stop:0 rgba(0,74,110,130),stop:1 rgba(1,20,34,160));'
            f'color:{C.TEXT};border:1px solid rgba(67,151,185,90);'
            'border-radius:9px;margin:3px 2px;padding:9px 11px;'
            "font:600 7.4pt 'Rajdhani';}"
            'QListWidget#JARVISHistoryPreview::item:selected { background:rgba(0,89,128,160); }'
            + _theme_scrollbar_css(5)
        )
        self._right_panel.set_body(self._preview)
        self._right_panel.setMinimumWidth(190)
        columns.addWidget(self._right_panel, 6)
        lay.addLayout(columns, 1)

    @staticmethod
    def _tab_button(label: str, icon: str | None, slot, tip: str):
        button = _AngularButton(label, None, compact=True, icon=icon)
        button.setFixedHeight(34)
        button.setCheckable(False)
        button.set_tab_visual(True)
        button.setToolTip(tip)
        if slot is not None:
            button.clicked.connect(slot)
        return button

    # ── reads ──────────────────────────────────────────────────────────────
    def reload(self, search: str = '') -> None:
        text = str(search or '').strip()
        try:
            self._search.setText(text)
        except Exception:
            pass
        self._status.setText(
            f'HISTORY · SEARCHING "{text[:40]}"…' if text
            else 'HISTORY · READING CONVERSATIONS…'
        )
        threading.Thread(
            target=self._read,
            args=(text,),
            name='history-chats',
            daemon=True
        ).start()

    def _read(self, search: str) -> None:
        rows: list[dict] = []
        error = ''
        try:
            from memory.conversations import get_store
            rows = list(
                get_store().list_conversations(limit=200, query=search) or []
            )
        except Exception as exc:
            error = f'{type(exc).__name__}: {exc}'
        self._marshal(lambda: self._render(rows, error, search))

    def _read_messages(self, conv_id: str) -> None:
        messages: list[dict] = []
        error = ''
        try:
            from memory.conversations import get_store
            messages = list(get_store().messages(str(conv_id)) or [])
        except Exception as exc:
            error = f'{type(exc).__name__}: {exc}'
        self._marshal(
            lambda: self._render_messages(str(conv_id), messages, error)
        )

    def _marshal(self, fn) -> None:
        try:
            host = self._host
            runner = getattr(host, 'run_on_ui', None) if host is not None else None
            if callable(runner):
                runner(fn)
                return
        except Exception:
            pass
        try:
            if QApplication.instance() is not None:
                QTimer.singleShot(0, fn)
                return
        except Exception:
            pass
        try:
            fn()
        except Exception:
            pass

    # ── render ─────────────────────────────────────────────────────────────
    def _render(self, rows, error, search) -> None:
        self._rows = list(rows)
        self._map = {}
        self._cards = {}
        self._timeline.blockSignals(True)
        self._timeline.clear()

        if not self._rows:
            item = QListWidgetItem(
                'NO SAVED CONVERSATIONS\n\n'
                'Say something to J.A.R.V.I.S. to create your first chat.'
            )
            item.setFlags(Qt.ItemFlag.NoItemFlags)
            item.setSizeHint(QSize(10, 74))
            self._timeline.addItem(item)
        else:
            grouped: dict[str, list[dict]] = {}
            for row in self._rows:
                grouped.setdefault(
                    _history_group(row.get('updated_at')), []
                ).append(row)

            for group, group_rows in grouped.items():
                header = _HistoryGroupHeader(group)
                header.set_count(len(group_rows))
                header_item = QListWidgetItem()
                header_item.setFlags(Qt.ItemFlag.NoItemFlags)
                header_item.setSizeHint(QSize(10, 28))
                self._timeline.addItem(header_item)
                self._timeline.setItemWidget(header_item, header)

                for row in group_rows:
                    conv_id = str(row.get('id') or '')
                    item = QListWidgetItem()
                    item.setData(Qt.ItemDataRole.UserRole, conv_id)
                    item.setFlags(
                        Qt.ItemFlag.ItemIsEnabled
                        | Qt.ItemFlag.ItemIsSelectable
                    )
                    card = _HistoryConversationCard(
                        row,
                        selected=(conv_id == self._selected),
                        on_click=lambda cid=conv_id: self._select_conv(cid),
                    )
                    self._cards[conv_id] = card
                    item.setSizeHint(card.sizeHint())
                    self._timeline.addItem(item)
                    self._timeline.setItemWidget(item, card)

            # Open the newest conversation when there is no current selection.
            ids = [str(row.get('id') or '') for row in self._rows]
            if self._selected not in ids:
                self._selected = ids[0] if ids else ''

        self._timeline.blockSignals(False)
        self._loaded = True
        try:
            self._left_panel.set_badge(f'{len(self._rows)} CHATS')
        except Exception:
            pass

        if error:
            self._status.setText(
                f'HISTORY · ERROR — {error[:110]}'.upper()
            )
        elif search:
            self._status.setText(
                f'HISTORY · "{search[:28]}" · {len(self._rows)} CONVERSATION(S)'
            )
        else:
            self._status.setText(
                f'HISTORY · {len(self._rows)} CONVERSATION(S)'
            )

        self._select_conv(self._selected, update_list=False)

    def _select_conv(self, conv_id: str, update_list: bool = True) -> None:
        conv_id = str(conv_id or '')
        self._selected = conv_id
        for cid, card in list(self._cards.items()):
            try:
                card.set_selected(cid == conv_id)
            except Exception:
                pass

        if update_list:
            for index in range(self._timeline.count()):
                item = self._timeline.item(index)
                if str(item.data(Qt.ItemDataRole.UserRole) or '') == conv_id:
                    self._timeline.blockSignals(True)
                    self._timeline.setCurrentRow(index)
                    self._timeline.blockSignals(False)
                    break

        if not conv_id:
            self._preview.clear()
            return

        self._status.setText('HISTORY · LOADING SELECTED CONVERSATION…')
        threading.Thread(
            target=self._read_messages,
            args=(conv_id,),
            name='history-preview',
            daemon=True,
        ).start()

    def _render_messages(self, conv_id, messages, error) -> None:
        if str(conv_id) != str(self._selected):
            return
        self._preview.clear()
        try:
            self._right_panel.set_badge(f'{len(messages)} MSG')
        except Exception:
            pass
        if not messages:
            item = QListWidgetItem('No messages in this conversation yet.')
            item.setFlags(Qt.ItemFlag.NoItemFlags)
            self._preview.addItem(item)
        else:
            for message in messages:
                role = (
                    'YOU'
                    if str(message.get('role') or '').lower() == 'user'
                    else 'JARVIS'
                )
                text = ' '.join(str(message.get('text') or '').split())
                stamp = _history_time(message.get('ts'))
                item = QListWidgetItem(
                    f'{stamp}   {role}\n{text or "(empty message)"}'
                )
                item.setToolTip(
                    str(message.get('text') or '')[:4000]
                )
                self._preview.addItem(item)

        if error:
            self._status.setText(
                f'HISTORY · ERROR — {error[:100]}'.upper()
            )

    def _on_row(self, index: int) -> None:
        if index < 0:
            return
        item = self._timeline.item(index)
        if item is None:
            return
        conv_id = str(item.data(Qt.ItemDataRole.UserRole) or '')
        if conv_id:
            self._select_conv(conv_id, update_list=False)

    def _on_double_click(self, item: QListWidgetItem) -> None:
        """Open the double-clicked saved conversation in the main Chat Log."""
        try:
            conv_id = str(item.data(Qt.ItemDataRole.UserRole) or '') if item else ''
        except Exception:
            conv_id = ''
        if not conv_id:
            return
        fn = getattr(self._host, 'load_conversation', None)
        if not callable(fn):
            self._status.setText('HISTORY · COULD NOT OPEN CONVERSATION.')
            return
        try:
            loaded = fn(conv_id, muted=False, show_divider=False)
        except Exception as exc:
            self._status.setText(
                f'HISTORY · COULD NOT OPEN IT — {exc}'.upper()
            )
            return
        if loaded is False:
            self._status.setText('HISTORY · CONVERSATION COULD NOT BE LOADED.')
            return
        self._selected = conv_id
        self._status.setText('HISTORY · CONVERSATION OPENED — RETURNING TO CHAT LOG.')
        QTimer.singleShot(120, self._close)

    # ── actions ─────────────────────────────────────────────────────────────
    def _selected_row(self) -> dict | None:
        for row in self._rows:
            if str(row.get('id') or '') == str(self._selected or ''):
                return row
        return None

    def _new(self) -> None:
        fn = getattr(self._host, 'new_conversation', None)
        if not callable(fn):
            self._status.setText('HISTORY · NEW CHAT IS UNAVAILABLE.')
            return
        try:
            fn()
        except Exception as exc:
            self._status.setText(f'HISTORY · COULD NOT START NEW CHAT — {exc}'.upper())
            return

        self._selected = ''
        self._status.setText('HISTORY · NEW CHAT STARTED — RETURNED TO CHAT LOG.')
        # A new conversation is a Chat Log state change, so close the history
        # window after the host has cleared the transcript.
        QTimer.singleShot(120, self._close)

    def _resume(self) -> None:
        conv_id = str(self._selected or '')
        if not conv_id:
            self._status.setText('HISTORY · SELECT A CONVERSATION TO RESUME.')
            return
        fn = getattr(self._host, 'load_conversation', None)
        if callable(fn):
            try:
                fn(conv_id, muted=True, show_divider=True)
            except Exception as exc:
                self._status.setText(
                    f'HISTORY · COULD NOT OPEN IT — {exc}'.upper()
                )
                return
        self._status.setText('HISTORY · RESUMED — RETURNED TO CHAT LOG.')
        QTimer.singleShot(120, self._close)

    def _rename(self) -> None:
        row = self._selected_row()
        if row is None:
            self._status.setText('HISTORY · SELECT A CONVERSATION TO RENAME.')
            return
        try:
            text, ok = QInputDialog.getText(
                self,
                'Rename conversation',
                'Name:',
                text=str(row.get('title') or ''),
            )
        except Exception:
            return
        if not ok or not str(text).strip():
            return
        try:
            from memory.conversations import get_store
            get_store().set_title(str(row.get('id') or ''), str(text))
        except Exception:
            pass
        self.reload()

    def _delete(self) -> None:
        row = self._selected_row()
        if row is None:
            self._status.setText('HISTORY · SELECT A CONVERSATION TO DELETE.')
            return
        title = str(row.get('title') or 'this conversation')[:48]
        if not _confirm(
            self,
            'Delete conversation?',
            f'Delete "{title}" and every message in it? This cannot be undone.',
        ):
            return
        try:
            from memory.conversations import get_store
            get_store().delete_conversation(str(row.get('id') or ''))
        except Exception:
            pass
        self._selected = ''
        self.reload()

    def _clear_all(self) -> None:
        if not _confirm(
            self,
            'Delete every conversation?',
            'This removes all saved chat history. Your memories are kept — '
            'this is only the transcript.',
        ):
            return
        try:
            from memory.conversations import get_store
            get_store().clear_all()
        except Exception:
            pass
        self._selected = ''
        self.reload()

    def _export(self) -> None:
        conv_id = str(self._selected or '')
        if not conv_id:
            self._status.setText('HISTORY · SELECT A CONVERSATION TO EXPORT.')
            return
        try:
            path, _ = QFileDialog.getSaveFileName(
                self,
                'Export conversation',
                'conversation.md',
                'Markdown (*.md);;JSON (*.json)',
            )
        except Exception:
            return
        if not path:
            return
        fmt = (
            'json'
            if str(path).lower().endswith('.json')
            else 'markdown'
        )
        try:
            from memory.conversations import get_store
            text = get_store().export_conversation(conv_id, fmt)
            Path(path).write_text(text, encoding='utf-8')
            self._status.setText(
                f'HISTORY · EXPORTED TO {Path(path).name}'.upper()
            )
        except Exception as exc:
            self._status.setText(
                f'HISTORY · EXPORT FAILED — {exc}'.upper()
            )

    def _import(self) -> None:
        try:
            path, _ = QFileDialog.getOpenFileName(
                self,
                'Import conversation',
                '',
                'JSON (*.json)',
            )
        except Exception:
            return
        if not path:
            return
        message = ''
        try:
            from memory.conversations import get_store
            store = get_store()
            conv_id = store.import_conversation(
                Path(path).read_text(encoding='utf-8')
            )
            if conv_id:
                self._selected = str(conv_id)
                message = 'IMPORTED.'
            else:
                message = str(store.last_error or 'IMPORT FAILED.')
        except Exception as exc:
            message = f'IMPORT FAILED — {exc}'
        self.reload()
        self._status.setText(f'HISTORY · {message}'.upper())

    def _close(self) -> None:
        try:
            host = self._host
            if host is not None:
                host.clear_history_view()
            else:
                self.hide()
        except Exception:
            self.hide()


class HistoryStage(QWidget):
    """Standalone 4:5 Chat History window.

    The history UI used to be an overlay inside the main Chat Log. It is now a
    real top-level Qt window so Chat History can stay open independently while
    the main J.A.R.V.I.S. HUD remains usable.

    The archive is the project's own brain database (`memory/database.py`),
    reached the way the rest of the HUD reaches it (`memory.service`), so this
    stage invents no second store: it lists exactly what J.A.R.V.I.S. already
    recorded, and its search uses the same index `recall_memory` searches. The
    live rows come from `brain.tasks`, the tracker the backend already writes to.

    Both reads happen on a worker thread: SQLite on the GUI thread in the middle
    of a turn is what makes a HUD stutter, and a search over the whole archive
    is not something to run between two frames.
    """

    def __init__(self, host=None, parent=None):
        super().__init__(parent)
        self._host = host

        # Chat History is intentionally a separate desktop window. Keep its
        # proportions at an exact 4:5 portrait ratio instead of inheriting the
        # main HUD's wide layout. The actual size is fitted to the available
        # screen in the host's positioning helper.
        self.setWindowFlags(
            Qt.WindowType.Window
            | Qt.WindowType.WindowTitleHint
            | Qt.WindowType.WindowCloseButtonHint
            | Qt.WindowType.WindowMinimizeButtonHint
        )
        self.setWindowTitle('J.A.R.V.I.S. · CHAT HISTORY')
        self.setObjectName('ChatHistoryWindow')
        self.setMinimumSize(400, 500)
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)

        self._loaded = False
        self._rows: list[dict] = []
        self.setObjectName('ChatHistoryOverlay')
        self._backdrop = QPixmap()  # blurred snapshot of the chat surface
        # The overlay must be OPAQUE: it is painted in paintEvent (a plain QWidget
        # subclass does not paint a stylesheet background), otherwise the chat log,
        # the input box and its buttons show straight through the history panel.
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, False)
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, False)
        self.setAutoFillBackground(False)
        self.setStyleSheet('QWidget#ChatHistoryOverlay{background:transparent;border:none;}')
        # Never wider than the compact chat window it sits in.
        self.setMinimumSize(0, 0)
        self._chats_loaded = False

        root = QVBoxLayout(self)
        root.setContentsMargins(14, 12, 14, 12)  # room for the outer glow
        root.setSpacing(6)

        # ── Mode bar: CHATS (the real conversation history) / ARCHIVE ───────
        # Chats is the authoritative conversation store; Archive is the brain
        # database view. Two different things, so they are two pages, not a
        # merge that would have to pretend they were one.
        bar = QHBoxLayout()
        bar.setSpacing(6)
        self._chats_tab = _AngularButton('CHATS', self, compact=True, icon='chat')
        self._chats_tab.setCheckable(True)
        self._chats_tab.set_tab_visual(True)
        self._chats_tab.setToolTip('Your saved conversations — resume, rename, export')
        self._chats_tab.clicked.connect(lambda: self.show_chats())
        bar.addWidget(self._chats_tab)
        self._archive_tab = _AngularButton('ARCHIVE', self, compact=True)
        self._archive_tab.setCheckable(True)
        self._archive_tab.set_tab_visual(True)
        self._archive_tab.setToolTip('The brain archive: recorded turns, and the tasks running now')
        self._archive_tab.clicked.connect(lambda: self.show_archive())
        bar.addWidget(self._archive_tab)
        bar.addStretch(1)
        self._mode_label = QLabel('CHAT HISTORY')
        self._mode_label.setStyleSheet(_theme_chip_css() + "font:700 7pt 'Exo 2';")
        bar.addWidget(self._mode_label)
        root.addLayout(bar)

        self._pages = QStackedWidget(self)
        root.addWidget(self._pages, 1)
        self.chats = ConversationHistoryPage(host=host, parent=self._pages)
        self._pages.addWidget(self.chats)

        archive = QWidget(self._pages)
        archive.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        archive.setStyleSheet('background:transparent;border:none;')
        self._pages.addWidget(archive)
        self._archive_page = archive
        self._chats_tab.setChecked(True)

        # Everything below the CHATS/ARCHIVE bar scrolls: on a short window the
        # lists and the task log would otherwise be clipped rather than reachable.
        outer = QVBoxLayout(archive)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.setSpacing(0)
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.Shape.NoFrame)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        scroll.setStyleSheet("QScrollArea{background:transparent;border:none;}"
                             "QScrollArea>QWidget>QWidget{background:transparent;}")
        body = QWidget()
        body.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        scroll.setWidget(body)
        outer.addWidget(scroll, 1)
        lay = QVBoxLayout(body)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(6)

        head = QHBoxLayout()
        head.setSpacing(6)
        self._search = QLineEdit()
        self._search.setPlaceholderText('Search what was said — a word, a name, a topic…')
        self._search.setStyleSheet(_hud_field_css())
        self._search.returnPressed.connect(lambda: self.reload(self._search.text()))
        head.addWidget(self._search, 1)
        go = _GlowButton('SEARCH', '⌕', compact=True)
        go.clicked.connect(lambda: self.reload(self._search.text()))
        head.addWidget(go)
        refresh = _GlowButton('REFRESH', '↻', compact=True)
        refresh.clicked.connect(lambda: self.reload(self._search.text()))
        head.addWidget(refresh)
        back = _GlowButton('CLOSE', '✕', compact=True)
        back.clicked.connect(self._close)
        head.addWidget(back)
        lay.addLayout(head)

        self._status = QLabel('HISTORY · reading the archive…')
        self._status.setStyleSheet(_theme_chip_css() + "font:700 7pt 'Exo 2';")
        lay.addWidget(self._status)

        columns = QHBoxLayout()
        columns.setSpacing(6)
        self._conversations = QListWidget()
        self._conversations.setStyleSheet(_hud_field_css())
        self._conversations.setFixedWidth(212)
        self._conversations.setToolTip('Conversations, newest first')
        self._conversations.currentRowChanged.connect(self._on_conversation)
        columns.addWidget(self._conversations)

        self._messages = QListWidget()
        self._messages.setStyleSheet(_hud_field_css())
        self._messages.setWordWrap(True)
        self._messages.setToolTip('Messages — the newest search hits, or the newest turns')
        self._messages.currentRowChanged.connect(self._on_message)
        columns.addWidget(self._messages, 1)
        lay.addLayout(columns, 1)

        self._tasks = QTextEdit()
        self._tasks.setReadOnly(True)
        self._tasks.setStyleSheet(_hud_field_css())
        self._tasks.setFixedHeight(96)
        self._tasks.setPlaceholderText('No task is running.')
        lay.addWidget(self._tasks)

    def capture_backdrop(self, host=None) -> None:
        """Snapshot + blur whatever sits under this overlay (call before the chat
        surface is hidden). Skipped while already open so it never captures itself."""
        try:
            if self.isVisible():
                return
            host = host or self.parentWidget()
            if host is None or self.width() < 8 or self.height() < 8:
                return
            self._backdrop = _blur_pixmap(host.grab(self.geometry()), 10)
            self.update()
        except Exception:
            self._backdrop = QPixmap()

    def paintEvent(self, event) -> None:
        p = QPainter(self)
        try:
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            inset = 7.0
            r = QRectF(self.rect()).adjusted(inset, inset, -inset, -inset)
            radius = 16.0
            accent = qcol(C.PRI)
            path = QPainterPath()
            path.addRoundedRect(r, radius, radius)

            _paint_glass_glow(p, r, radius, accent, layers=6)

            # 1) solid base so nothing underneath ever shows through
            p.fillPath(path, QBrush(QColor(C.BG)))

            # 2) frosted backdrop: the blurred chat surface, clipped to the panel
            pix = getattr(self, '_backdrop', None)
            if pix is not None and not pix.isNull():
                p.save()
                p.setClipPath(path)
                p.setOpacity(0.55)
                p.drawPixmap(QRectF(self.rect()), pix, QRectF(pix.rect()))
                p.restore()

            # 3) deep gradient wash
            wash = QLinearGradient(r.topLeft(), r.bottomRight())
            wash.setColorAt(0.0, QColor(5, 40, 64, 188))
            wash.setColorAt(0.55, QColor(2, 18, 33, 200))
            wash.setColorAt(1.0, QColor(1, 8, 18, 224))
            p.fillPath(path, QBrush(wash))

            # 4) accent bloom from the top-left
            bloom = QRadialGradient(r.left() + r.width() * 0.1, r.top(),
                                    max(r.width(), r.height()) * 0.85)
            top = QColor(accent)
            top.setAlpha(40)
            bloom.setColorAt(0.0, top)
            bloom.setColorAt(1.0, QColor(0, 0, 0, 0))
            p.fillPath(path, QBrush(bloom))

            # 5) glowing edge
            edge = QLinearGradient(r.topLeft(), r.bottomRight())
            hi = QColor(accent)
            hi.setAlpha(220)
            lo = QColor(accent)
            lo.setAlpha(70)
            edge.setColorAt(0.0, hi)
            edge.setColorAt(0.5, lo)
            edge.setColorAt(1.0, hi)
            p.setPen(QPen(QBrush(edge), 1.3))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
        finally:
            p.end()

    # -- modes ---------------------------------------------------------------
    def show_chats(self) -> None:
        """Front the saved conversation history (the real chat history)."""
        try:
            self._pages.setCurrentWidget(self.chats)
            self._chats_tab.setChecked(True)
            self._archive_tab.setChecked(False)
            self._mode_label.setText('CHAT HISTORY')
            self.chats.reload()
            self._chats_loaded = True
        except Exception:
            pass

    def show_archive(self) -> None:
        """Front the brain-archive view (recorded turns and running tasks)."""
        try:
            self._pages.setCurrentWidget(self._archive_page)
            self._archive_tab.setChecked(True)
            self._chats_tab.setChecked(False)
            self._mode_label.setText('BRAIN ARCHIVE')
            if not self._loaded:
                self.reload()
        except Exception:
            pass

    # -- reads ---------------------------------------------------------------
    def reload(self, search: str = '') -> None:
        text = str(search or '').strip()
        self._search.setText(text)
        self._status.setText(f'HISTORY · searching "{text[:40]}"…' if text
                             else 'HISTORY · reading the archive…')
        threading.Thread(target=self._read, args=(text,), name='history-read',
                         daemon=True).start()

    def _read(self, search: str) -> None:
        conversations: list[dict] = []
        messages: list[dict] = []
        error = ''
        try:
            from memory.service import get_memory_service
            service = get_memory_service()
            db = service.db
            conversations = list(service.recent_conversations(limit=40) or [])
            if search:
                messages = list(db.search_messages_fts(search, limit=60) or [])
                if not messages:
                    error = f'nothing in the archive matches "{search}"'
            else:
                messages = list(db.recent_messages(limit=60) or [])
        except Exception as exc:
            error = f'{type(exc).__name__}: {exc}'
        tasks = ''
        try:
            from brain.tasks import get_task_tracker
            tasks = str(get_task_tracker().list_active(limit=5) or '')
        except Exception as exc:
            tasks = f'Task tracker unavailable — {exc}'
        self._marshal(lambda: self._render(conversations, messages, tasks, error,
                                           search))

    def _marshal(self, fn) -> None:
        try:
            host = self._host
            if host is not None:
                host.run_on_ui(fn)
                return
        except Exception:
            pass
        try:
            fn()
        except Exception:
            pass

    # -- render --------------------------------------------------------------
    def _render(self, conversations, messages, tasks, error, search) -> None:
        self._rows = list(conversations)
        self._conversations.blockSignals(True)
        self._conversations.clear()
        for row in self._rows:
            title = str(row.get('title') or 'untitled conversation')[:44]
            count = int(row.get('n') or row.get('message_count') or 0)
            stamp = _history_time(row.get('started_at'))
            item = QListWidgetItem(f"#{int(row.get('id') or 0):03d}  {title}"
                                  + (f"\n{stamp}  ·  {count} message(s)" if count else
                                     (f"\n{stamp}" if stamp else '')))
            self._conversations.addItem(item)
        self._conversations.blockSignals(False)

        self._messages.blockSignals(True)
        self._messages.clear()
        for row in list(messages):
            role = str(row.get('role') or 'turn').upper()[:9]
            text = ' '.join(str(row.get('content') or '').split())
            stamp = _history_time(row.get('created_at'))
            item = QListWidgetItem(f"{stamp}  {role}  ·  {text[:70]}")
            item.setToolTip(text[:4000] or '(empty)')
            self._messages.addItem(item)
        self._messages.blockSignals(False)

        self._tasks.setPlainText(tasks or 'No task is running.')
        if error and not messages:
            self._status.setText(f'HISTORY · {error[:90].upper()}')
        else:
            label = f'HISTORY · "{search[:28]}" · {len(messages)} MESSAGE(S)' if search \
                else f'HISTORY · {len(self._rows)} CONVERSATION(S) · {len(messages)} MESSAGE(S)'
            self._status.setText(label.upper())
        self._loaded = True

    def _on_conversation(self, index: int) -> None:
        if index < 0 or index >= len(self._rows):
            return
        row = self._rows[index]
        self._tasks.setPlainText(
            f"Conversation #{int(row.get('id') or 0)}"
            f"\nStarted  {_history_time(row.get('started_at')) or 'unknown'}"
            f"\nEnded    {_history_time(row.get('ended_at')) or 'still open'}"
            f"\nMessages {int(row.get('n') or row.get('message_count') or 0)}"
            f"\nTitle    {str(row.get('title') or 'untitled')}")

    def _on_message(self, index: int) -> None:
        item = self._messages.item(index)
        if item is not None:
            self._tasks.setPlainText(str(item.toolTip() or ''))

    def _close(self) -> None:
        # Closing the standalone window only hides it. The live Chat Log remains
        # visible because it is no longer covered by an overlay.
        try:
            self.hide()
        except Exception:
            pass

    def closeEvent(self, event) -> None:
        # Keep the widget alive so reopen is instant and its current view state
        # is preserved.
        try:
            event.ignore()
            self.hide()
        except Exception:
            try:
                event.accept()
            except Exception:
                pass


class _ActivityTimeline(QFrame):
    MAX_ENTRIES = 60

    _CATS = (
        (('you:', 'voice:', 'mic:'),            'VOICE', '#e9fcff'),
        (('jarvis:', 'j.a.r.v.i.s', 'ai:'),     'AI',    '#9ae8ff'),
        (('err', 'fail', 'exception', 'trace'), 'ERROR', '#ff7892'),
        (('ok', 'done', 'complete', 'sent'),    'OK',    '#7affc3'),
        (('file:',),                            'FILE',  '#7affc3'),
        (('tool', 'exec', 'run:'),              'TOOL',  '#ffcc66'),
        (('web', 'search', 'fetch'),            'WEB',   '#42c7ef'),
        (('warn',),                             'WARN',  '#ffcc66'),
    )

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setStyleSheet('background:transparent;border:none;')
        self._entries: list[dict] = []
        self._filter = 'ALL'
        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)
        self._scroll = QScrollArea(self)
        self._scroll.setWidgetResizable(True)
        self._scroll.setFrameShape(QFrame.Shape.NoFrame)
        self._scroll.setStyleSheet('QScrollArea{background:transparent;border:none;}' + _theme_scrollbar_css(5))
        self._scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self._scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self._container = QWidget()
        self._cl = QVBoxLayout(self._container)
        self._cl.setContentsMargins(2, 2, 2, 2)
        self._cl.setSpacing(6)
        self._cl.addStretch(1)
        self._scroll.setWidget(self._container)
        lay.addWidget(self._scroll, 1)

    @classmethod
    def _categorize(cls, text: str):
        tl = text.strip().lower()
        for prefixes, tag, color in cls._CATS:
            if tl.startswith(prefixes) or f' {prefixes[0]}' in tl[:14]:
                return tag, color
        if tl.startswith('sys:'):
            return 'SYS', '#659fb1'
        return 'SYS', '#659fb1'

    def set_filter(self, tag: str) -> None:
        self._filter = str(tag or 'ALL').upper()
        self._render()

    def count(self) -> int:
        return len(self._entries)

    def lines(self, n: int = 80) -> list[str]:
        try:
            return [f"[{e['time']}] [{e['tag']}] {e['text']}" for e in self._entries[:max(1, int(n))]]
        except Exception:
            return []

    def add_entry(self, text: str) -> None:
        text = str(text or '').strip()
        if not text:
            return
        try:
            stamp = time.strftime('%H:%M:%S')
        except Exception:
            stamp = '--:--:--'
        tag, color = self._categorize(text)
        entry = {'time': stamp, 'tag': tag, 'color': color, 'text': text[:280]}
        self._entries.insert(0, entry)
        del self._entries[self.MAX_ENTRIES:]
        # Incremental paint. The old path called _render() for every arriving
        # line, which destroyed and rebuilt every card widget (60 entries × 4
        # widgets) per line — log bursts (MCP hot-registration, transcripts)
        # froze the HUD. Insert just the new card; trim only when the cap
        # pushed an old entry out. A full _render() remains for filter changes.
        if self._filter and self._filter != 'ALL' and self._filter != tag:
            return
        card = self._make_card(entry)
        self._cl.insertWidget(0, card)
        visible = sum(
            1 for e in self._entries
            if not self._filter or self._filter == 'ALL' or e['tag'] == self._filter)
        while self._cl.count() - 1 > visible:
            item = self._cl.takeAt(self._cl.count() - 2)   # oldest card, before stretch
            if item and item.widget():
                item.widget().deleteLater()
        self._fade_in(card)
        try:
            self._scroll.verticalScrollBar().setValue(0)
        except Exception:
            pass

    def _render(self, new_first: bool = False) -> None:
        while self._cl.count() > 1:
            item = self._cl.takeAt(0)
            if item and item.widget():
                item.widget().deleteLater()
        shown = 0
        for i, e in enumerate(self._entries):
            if self._filter != 'ALL' and e['tag'] != self._filter:
                continue
            card = self._make_card(e)
            self._cl.insertWidget(shown, card)
            shown += 1
            if new_first and i == 0:
                self._fade_in(card)
        try:
            self._scroll.verticalScrollBar().setValue(0)
        except Exception:
            pass

    def _make_card(self, e: dict) -> QFrame:
        card = QFrame()
        card.setStyleSheet(
            "QFrame { background:rgba(1,15,25,120); border:none; border-radius:8px; }"
        )
        hl = QHBoxLayout(card)
        hl.setContentsMargins(9, 6, 9, 6)
        hl.setSpacing(8)
        dot = QLabel('●')
        dot.setStyleSheet(f"color:{e['color']};font-size:9px;background:transparent;{_theme_icon_font_css()}")
        dot.setFixedWidth(12)
        hl.addWidget(dot, 0, Qt.AlignmentFlag.AlignTop)
        vb = QVBoxLayout()
        vb.setSpacing(2)
        vb.setContentsMargins(0, 0, 0, 0)
        head = QHBoxLayout()
        head.setSpacing(8)
        tag = QLabel(e['tag'])
        tag.setStyleSheet(f"color:{e['color']};font:700 7pt 'Exo 2';background:transparent;")
        head.addWidget(tag)
        ts = QLabel(e['time'])
        ts.setStyleSheet("color:#3a6a7a;font:700 7pt 'Exo 2';background:transparent;")
        head.addWidget(ts)
        head.addStretch(1)
        vb.addLayout(head)
        body = QLabel(e['text'])
        body.setWordWrap(True)
        body.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
        body.setStyleSheet("color:#b9efff;font:8pt 'Share Tech Mono';background:transparent;")
        vb.addWidget(body)
        hl.addLayout(vb, 1)
        return card

    def _fade_in(self, card: QFrame) -> None:
        try:
            eff = QGraphicsOpacityEffect(card)
            card.setGraphicsEffect(eff)
            eff.setOpacity(0.0)
            anim = QPropertyAnimation(eff, b'opacity', card)
            anim.setDuration(200)
            anim.setStartValue(0.0)
            anim.setEndValue(1.0)
            anim.setEasingCurve(QEasingCurve.Type.OutCubic)
            anim.finished.connect(lambda: card.setGraphicsEffect(None))
            anim.start(QAbstractAnimation.DeletionPolicy.DeleteWhenStopped)
        except Exception:
            pass


class ToolsPane(QFrame):
    CATEGORIES = ('All', 'Browser', 'Files', 'Screen',
                  'Media', 'System', 'Automation', 'Coding', 'Memory', 'Plugins')

    def __init__(self, host=None, parent=None):
        super().__init__(parent)
        self.setStyleSheet('background:transparent;border:none;')
        self._host = host
        self._entries: list[dict] = []
        self._filter = 'All'
        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(7)
        self._controls = _CollapsibleControls('FILTER TOOLS', self)
        top = QHBoxLayout(); top.setContentsMargins(0,0,0,0); top.setSpacing(6)
        self._search = QLineEdit()
        self._search.setPlaceholderText('Search tools…')
        self._search.setStyleSheet(_hud_field_css())
        self._search.setMinimumHeight(30)
        self._search.textChanged.connect(self._render)
        top.addWidget(self._search, 1)
        self._cat = QComboBox()
        self._cat.addItems(list(self.CATEGORIES))
        self._cat.setStyleSheet(_hud_field_css())
        self._cat.setMinimumHeight(30)
        self._cat.currentTextChanged.connect(self._on_cat)
        top.addWidget(self._cat)
        self._controls.addLayout(top)
        lay.addWidget(self._controls, 0)
        self._count = QLabel('')
        self._count.setStyleSheet("color:#5796ad;font:700 7pt 'Exo 2';background:transparent;")
        lay.addWidget(self._count)
        self._scroll = QScrollArea(self)
        self._scroll.setWidgetResizable(True)
        self._scroll.setFrameShape(QFrame.Shape.NoFrame)
        self._scroll.setStyleSheet('QScrollArea{background:transparent;border:none;}' + _theme_scrollbar_css(5))
        self._scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self._container = QWidget()
        self._cl = QVBoxLayout(self._container)
        self._cl.setContentsMargins(2, 2, 2, 2)
        self._cl.setSpacing(7)
        self._cl.addStretch(1)
        self._scroll.setWidget(self._container)
        lay.addWidget(self._scroll, 1)

    def _on_cat(self, text: str) -> None:
        self._filter = text
        self._render()

    def reload(self) -> None:
        try:
            host = self._host() if callable(self._host) else self._host
            if host is not None and hasattr(host, 'get_tool_entries'):
                self._entries = list(host.get_tool_entries() or [])
        except Exception:
            pass
        self._render()

    def _render(self) -> None:
        q = self._search.text().strip().lower() if hasattr(self, '_search') else ''
        while self._cl.count() > 1:
            item = self._cl.takeAt(0)
            if item and item.widget():
                item.widget().deleteLater()
        shown = 0
        for e in self._entries:
            if self._filter != 'All' and e.get('category') != self._filter:
                continue
            hay = f"{e.get('name','')} {e.get('desc','')}".lower()
            if q and q not in hay:
                continue
            self._cl.insertWidget(shown, self._make_card(e))
            shown += 1
        try:
            self._count.setText(f'{shown} of {len(self._entries)} tools ready')
        except Exception:
            pass

    def _make_card(self, e: dict) -> QFrame:
        card = QFrame()
        card.setStyleSheet(
            "QFrame { background:rgba(1,15,25,120); border:none; border-radius:8px; }"
        )
        hl = QHBoxLayout(card)
        hl.setContentsMargins(10, 8, 10, 8)
        hl.setSpacing(9)
        icon = QLabel(e.get('icon', '▣'))
        icon.setStyleSheet("color:#42c7ef;font-size:15px;background:transparent;" + _theme_icon_font_css())
        icon.setFixedWidth(22)
        hl.addWidget(icon, 0, Qt.AlignmentFlag.AlignTop)
        vb = QVBoxLayout()
        vb.setSpacing(3)
        vb.setContentsMargins(0, 0, 0, 0)
        title_row = QHBoxLayout()
        title_row.setSpacing(8)
        name = QLabel(str(e.get('name', 'tool')).upper())
        name.setStyleSheet("color:#dff8ff;font:700 8pt 'Orbitron';letter-spacing:1px;background:transparent;border:none;")
        title_row.addWidget(name, 1)
        avail = bool(e.get('available', True))
        dot = QLabel('● READY' if avail else '○ OFF')
        dot.setStyleSheet(f"color:{'#7affc3' if avail else '#5796ad'};font:700 7pt 'Exo 2';background:transparent;")
        title_row.addWidget(dot)
        vb.addLayout(title_row)
        cat = QLabel(str(e.get('category', '')))
        cat.setStyleSheet("color:#5796ad;font:600 7pt 'Exo 2';background:transparent;")
        vb.addWidget(cat)
        desc = QLabel(str(e.get('desc', '')))
        desc.setWordWrap(True)
        desc.setStyleSheet("color:#9ae8ff;font:8pt 'Rajdhani';background:transparent;")
        vb.addWidget(desc)
        hl.addLayout(vb, 1)
        run = QPushButton('RUN')
        run.setFixedSize(56, 32)
        run.setCursor(Qt.CursorShape.PointingHandCursor)
        run.setStyleSheet(
            "QPushButton { color:#edfcff; background:rgba(0,111,151,170);"
            " border:1px solid #75e2fa; border-radius:7px; font:700 7pt 'Exo 2'; }"
            "QPushButton:hover { background:rgba(0,154,199,210); }"
            "QPushButton:disabled { color:#3a6a7a; border-color:rgba(67,151,185,40);"
            " background:rgba(1,17,27,80); }"
        )
        run.setEnabled(avail)
        run.setToolTip(str(e.get('desc', 'Run this tool')))
        run.clicked.connect(lambda _=False, entry=dict(e): self._run_entry(entry))
        hl.addWidget(run, 0, Qt.AlignmentFlag.AlignVCenter)
        return card

    def _run_entry(self, entry: dict) -> None:
        try:
            _sfx('click')
        except Exception:
            pass
        try:
            host = self._host() if callable(self._host) else self._host
            if host is None:
                return
            action = entry.get('action')
            if action == 'open_web_task' and hasattr(host, '_open_web_task_panel'):
                host._open_web_task_panel()
                return
            if action == 'open_window' and hasattr(host, 'control_jarvis_window'):
                host.control_jarvis_window(entry.get('window', 'webview'), 'open')
                return
            run_text = (entry.get('run') or '').strip()
            if run_text and hasattr(host, '_send_backend_command'):
                try:
                    host._activity_add(f"YOU: {run_text}")
                except Exception:
                    pass
                host._send_backend_command(run_text)
        except Exception:
            pass


