    def _open_3d_panel(self):
        self._open_3d_display()

    def _open_3d_display(self):
        path,_=QFileDialog.getOpenFileName(self,'Open 3D object',str(Path.home()),'3D Models (*.obj *.stl *.ply *.off *.glb *.gltf *.dae *.3ds *.fbx);;All Files (*.*)')
        if not path: return
        try:
            if getattr(self,'_three_d_display',None) is None:
                self._three_d_display=_3DDisplayWindow(self)
                self._three_d_display.setProperty('_jarvis_floating_panel', True)
                self._three_d_display.setProperty('_jarvis_panel_kind', '3d_hologram')
                self._three_d_display.setProperty('_jarvis_panel_key', '3d_hologram')
            self._three_d_display.load_model(path)
            sg=QApplication.primaryScreen().availableGeometry() if QApplication.primaryScreen() else None
            if sg:
                w,h=self._three_d_display.width(),self._three_d_display.height()
                self._three_d_display.move(sg.left()+(sg.width()-w)//2,sg.top()+(sg.height()-h)//2)
            self._three_d_display.show(); self._three_d_display.raise_(); self._three_d_display.activateWindow()
        except Exception as exc:
            self.write_log(f'ERR: 3D display — {exc}')

    def control_jarvis_window(self, window: str, action: str = "open", query: str = ""):
        w = str(window or "webview").strip().lower().replace(" ", "_").replace("-", "_")
        a = str(action or "open").strip().lower()
        aliases = {
            "web": "webview", "browser": "webview", "search": "webview",
            "images": "image", "image_preview": "image", "imageviewer": "image",
            "world": "world_monitor", "worldmonitor": "world_monitor",
            "video_preview": "video", "player": "video",
            "task": "web_task", "webtask": "web_task",
            "tools": "tools", "toolbox": "tools", "tool": "tools",
            "system": "world_monitor", "telemetry": "world_monitor",
            "sysmon": "world_monitor", "performance": "world_monitor",
            "system_panel": "world_monitor", "system_monitor": "world_monitor",
            "status": "world_monitor", "monitor": "world_monitor",
            "memory_core": "memory", "memorycore": "memory",
            "activity_log": "activity", "log": "activity",
            "content_surface": "content", "research": "content",
            "model": "3d", "3d_display": "3d", "hologram": "3d",
            "camera": "live_camera", "webcam": "live_camera",
            "my_camera": "live_camera", "camera_view": "live_camera",
            "live_camera": "live_camera", "vision": "live_camera",
            "vision_panel": "live_camera", "vision_stage": "live_camera",
            "settings": "jarvis_settings", "jarvis_settings": "jarvis_settings",
            "ui_settings": "jarvis_settings", "jarvis_ui": "jarvis_settings",
            "control_center": "jarvis_settings", "configuration": "jarvis_settings",
            "preferences": "jarvis_settings", "options": "jarvis_settings",
        }
        w = aliases.get(w, w)

        # JARVIS's OWN Settings window — deliberately separate from the OS/Windows
        # settings app. Opening it here is how "open JARVIS settings / UI settings /
        # control center" must behave; it must never launch the Windows Settings.
        if w == "jarvis_settings":
            if a == "close":
                swin = getattr(self, "_full_settings_window", None)
                try:
                    if swin is not None and swin.isVisible():
                        swin.close()
                        return "Closed the JARVIS Settings window."
                except Exception:
                    pass
                return "The JARVIS Settings window is not open."
            self._open_full_settings()
            swin = getattr(self, "_full_settings_window", None)
            try:
                if swin is not None and swin.isVisible():
                    return "Opened the JARVIS Settings window."
            except Exception:
                pass
            return "I could not open the JARVIS Settings window."

        # The live Vision surface is the embedded Chat Panel stage, NOT a
        # floating panel, so it has no entry in the ``panels`` map below. It
        # must therefore be resolved BEFORE that map's membership check — which
        # is exactly what used to swallow "open vision": the alias resolved to
        # "live_camera", the guard rejected it and returned "Unknown JARVIS
        # window. Available: Settings, Vision, …" — naming Vision as available
        # while refusing to open it, which the assistant then reported as done.
        if w == "live_camera":
            if a == "close":
                self.toggle_camera_overlay(False)
                return ("I could not close the Vision panel."
                        if bool(getattr(self, "_chat_vision_inline", False))
                        else "Closed the Vision panel.")
            # Never claim success from the call alone: the inline stage reports
            # its real result, and the Chat Panel that hosts it must be visible.
            opened = bool(self.open_inline_vision_camera())
            if opened:
                try:
                    host = getattr(self, "_command_window", None)
                    opened = host is not None and host.isVisible()
                except Exception:
                    opened = False
            return ("Opened the Vision panel inside the chat window."
                    if opened else
                    "I could not open the Vision panel right now.")

        panels = {
            "video": self._video_panel, "image": self._image_panel,
            "activity": self._activity_panel, "content": self._content_panel,
            "3d": self._model_panel, "webview": self._webview_panel,
            "web_task": self._web_task_panel, "world_monitor": self._world_monitor_panel,
            "memory": self._memory_panel, "tools": self._tools_panel,
        }
        if w not in panels:
            return ("Unknown JARVIS window. Available: Settings, Vision, Tools, WebView, "
                    "Image, System Monitor (World Monitor), Video, Web Task, Memory, "
                    "Activity, Content, and 3D.")
        panel = panels[w]

        # IMAGE is a mode of the ReferenceDashboard, not a floating window.
        if w == "image":
            win = getattr(self, '_command_window', None)
            if a == "close":
                if win is not None:
                    try:
                        win.clear_inline_vision()
                    except Exception:
                        pass
                return "Closed the Image View."
            if a in ("open", "refresh"):
                self._open_image_view()
                return "Opened the Image View inside the JARVIS Chat Panel."

        if a == "close":
            self._set_panel_visible(panel, False)
            return f"Closed the {w.replace('_', ' ')} window."

        if w == "webview":
            if a in ("search", "find"):
                q = query.strip()
                if not q:
                    return "Please provide something to search for."
                self._open_webview_panel()
                self._webview_pane._url.setText(q)
                self._webview_pane.navigate()
                return f"Searching for {q} inside the JARVIS WebView."
            if a in ("refresh", "reload"):
                self._open_webview_panel(); self._webview_pane.reload()
                return "Refreshed the JARVIS WebView."
            self._open_webview_panel(query if query else None)
            return "Opened the JARVIS WebView."

        if w == "world_monitor":
            self._open_world_monitor()
            if a == "refresh":
                try: self._world_monitor_pane.refresh_feeds()
                except Exception: pass
                return "Refreshed the JARVIS World Monitor."
            return "Opened the JARVIS World Monitor."

        if w == "image":
            self._open_image_panel()
            if a == "search" and query:
                try:
                    from urllib.parse import quote_plus
                    self._open_webview_panel('https://www.google.com/search?tbm=isch&q=' + quote_plus(query))
                    return f"Opened image search for {query} inside the JARVIS WebView."
                except Exception as exc:
                    return f"Could not open image search: {exc}"
            return "Opened the JARVIS Image Preview."

        if w == "video":
            self._open_video_panel()
            return "Opened the JARVIS Video Preview."
        if w == "web_task":
            self._open_web_task_panel()
            return "Opened the JARVIS Web Task window."
        if w == "tools":
            self._open_tools_panel()
            return "Opened the JARVIS Tools Deck."
        if w == "memory":
            self._open_memory_panel()
            return "Opened the JARVIS Mind panel."
        if w == "activity":
            self._open_activity_panel()
            return "Opened the JARVIS Activity Log."
        if w == "content":
            self._set_panel_visible(self._content_panel, True)
            return "Opened the JARVIS Content Surface."
        if w == "3d":
            self._set_panel_visible(self._model_panel, True)
            return "Opened the JARVIS 3D Display. Use OPEN MODEL inside it to load a file."
        return "Done."

    def _open_video_panel(self):
        try:
            source=str(getattr(self,'_video_view_source','') or '')
            if source: return bool(self.show_video_view(source,getattr(self,'_video_view_caption','') or 'VIDEO'))
            win=self._ensure_command_window_for_inline_view()
            if win is not None: win._show_chat_tab(); win.show(); win.raise_(); win.activateWindow()
            self.write_log('SYS: Video View is ready — no video loaded yet.')
        except Exception as exc: self.write_log(f'ERR: Video View — {exc}')

    def _open_image_panel(self):
        """Legacy entry point: route image display into the embedded Chat/ReferenceDashboard stage."""
        try:
            panel = getattr(self, '_image_view_panel', None)
            if panel is not None and panel.has_image():
                self._open_image_view()
                return
            # No cached image yet: let the existing file chooser load one;
            # show_image_path() will immediately route it into the inline stage.
            self._open_image_file()
        except Exception as exc:
            self.write_log(f'ERR: Image View — {exc}')

    def _open_image_view(self):
        """Show the last Image View result directly inside the Chat Panel."""
        try:
            if not self._image_view_panel.has_image():
                return
            win = self._ensure_command_window_for_inline_view()
            if win is not None:
                win._show_chat_tab()
                win.show_inline_vision(
                    self._image_view_panel._pixmap,
                    self.image_view_caption or "VISION RESULT",
                )
                win.show()
                win.raise_()
                win.activateWindow()
        except Exception as exc:
            self.write_log(f"ERR: Inline Image View — {exc}")

    def _ensure_command_window_for_inline_view(self):
        try:
            win = getattr(self, "_command_window", None)
            if win is not None and win.isVisible():
                return win
            self._toggle_command_window()
            return getattr(self, "_command_window", None)
        except Exception:
            return getattr(self, "_command_window", None)

    def open_inline_vision_camera(self) -> bool:
        """Open Vision only inside the Refined Chat Panel.

        The vision tools ("what am I holding", "scan this") call this from the
        backend/executor thread, but the real work drives live Qt widgets, and
        widget calls made off the GUI thread are silently ignored by Qt — which
        is why the inline stage never appeared for a voice scan. So this wrapper
        marshals the body onto the GUI thread (call_on_ui) and returns the REAL
        result. When already on the GUI thread (the Chat Panel's own VISION
        button, or control_jarvis_window) call_on_ui runs the body inline, so
        every existing caller keeps working unchanged.
        """
        try:
            return bool(self.call_on_ui(self._open_inline_vision_camera_on_ui))
        except Exception as exc:
            try:
                self.write_log(f'ERR: Inline Vision camera — {exc}')
            except Exception:
                pass
            return False

    def _open_inline_vision_camera_on_ui(self) -> bool:
        """GUI-thread body of open_inline_vision_camera — never call directly."""
        try:
            win = self._ensure_command_window_for_inline_view()
            if win is None:
                return False
            win._show_chat_tab()
            win.show(); win.raise_(); win.activateWindow()
            btn = getattr(win, '_vision_status_toggle', None)
            if btn is not None and not btn.isChecked():
                # This is the same embedded Vision transition used by the
                # visible VISION control and sets the inline flag before frames.
                win._on_vision_toggled(True)
            else:
                self._chat_vision_inline = True
                for name in ('_cam_preview', '_cam_live_lbl'):
                    w = getattr(self, name, None)
                    if w is not None:
                        w.hide()
                stage = getattr(win, '_vision_camera_stage', None)
                visual = getattr(win, '_vision_visual', None)
                if stage is not None:
                    stage.show()
                if visual is not None and stage is not None:
                    visual.setCurrentWidget(stage)
            return True
        except Exception as exc:
            try:
                self.write_log(f'ERR: Inline Vision camera — {exc}')
            except Exception:
                pass
            return False

    # ── Image View: AI-generated and researched images ─────────────────────
    def show_image_view(self, source=None, caption: str = '', source_url: str = '') -> bool:
        """Render generated/researched images inside the Chat Panel Vision card.

        The legacy Image View surface is retained as a hidden compatibility/cache
        surface, but it is no longer opened as a separate top-level window.
        """
        try:
            if source is None:
                if not self._image_view_panel.has_image():
                    return False
                pix = self._image_view_panel._pixmap
                cap = caption or self.image_view_caption or "VISION RESULT"
            else:
                if isinstance(source, QPixmap):
                    ok = self._image_view_panel.set_pixmap(source, caption)
                elif isinstance(source, (bytes, bytearray)):
                    ok = self._image_view_panel.set_image_bytes(source, caption)
                else:
                    ok = self._image_view_panel.set_image_path(source, caption)
                if not ok:
                    self.write_log('ERR: Image View — that image could not be decoded')
                    return False
                pix = self._image_view_panel._pixmap
                cap = str(caption or "")

            self._image_view_caption = str(cap or "")
            effective_url = str(source_url or getattr(self, '_image_source_url', '') or '')
            win = self._ensure_command_window_for_inline_view()
            if win is None or pix is None or pix.isNull():
                self.write_log('ERR: Image View — Chat Panel is unavailable')
                return False

            win._show_chat_tab()
            shown = win.show_inline_vision(
                pix, self._image_view_caption or "VISION RESULT", effective_url
            )
            if shown:
                win.show()
                win.raise_()
                win.activateWindow()
            return shown
        except Exception as exc:
            self.write_log(f'ERR: Inline Image View — {exc}')
            return False

    def show_video_view(self, source, caption: str = 'Video') -> bool:
        try:
            src=str(source or '').strip()
            if not src: return False
            self._video_view_source=src; self._video_view_caption=str(caption or 'Video')
            win=self._ensure_command_window_for_inline_view()
            if win is None: return False
            win._show_chat_tab(); shown=win.show_inline_video(src,self._video_view_caption)
            if shown: win.show(); win.raise_(); win.activateWindow()
            return bool(shown)
        except Exception as exc: self.write_log(f'ERR: Inline Video View — {exc}'); return False

    def show_web_video(self, url_or_query: str, caption: str = 'Web video') -> bool:
        try:
            from urllib.parse import quote_plus
            raw=str(url_or_query or '').strip()
            url=raw if raw.lower().startswith(('http://','https://')) else 'https://www.youtube.com/results?search_query='+quote_plus(raw or 'video')
            return self.show_video_view(url,caption)
        except Exception: return False

