    def show_repair_card(self, kind: str, payload: dict | None = None) -> None:
        """Feed one auto-heal event to the repair card and surface it."""
        try:
            self._repair_pane.set_event(str(kind or ""), dict(payload or {}))
        except Exception:
            pass
        try:
            panel = getattr(self, "_repair_panel", None)
            if panel is None:
                return
            if panel.isVisible():
                # Refresh in place. Re-running _set_panel_visible() restarted
                # the fade from opacity 0, re-fit the geometry and called
                # activateWindow() on every auto-heal event — the panel
                # blinked and stole keyboard focus mid-typing/speaking.
                panel.raise_()
            else:
                self._set_panel_visible(panel, True)
        except Exception:
            pass

