    def open_history(self, search: str = "") -> bool:
        """Open the chat archive: past conversations, and the tasks running now.

        The rows come from the project's own brain database, so this is a view
        of what J.A.R.V.I.S. already recorded — never a second transcript kept
        only for the panel.
        """
        try:
            win = self._ensure_command_window_for_inline_view()
            if win is None:
                return False
            win._show_chat_tab()
            shown = bool(win.show_history())
            if search:
                try:
                    win._history_stage.chats.reload(str(search))
                except Exception:
                    pass
            if shown:
                win.show(); win.raise_(); win.activateWindow()
            return shown
        except Exception as exc:
            self.write_log(f'ERR: History View — {exc}')
            return False

    def _open_history(self) -> None:
        self.open_history()

    def restore_chat_history(self) -> bool:
        """Restore the last conversation into the chat panel on startup.

        Called once the window exists, so a session that was closed (or killed)
        mid-thought comes back with its transcript already in the chat log
        instead of starting blank. Never fatal, and never claims success it did
        not achieve.
        """
        try:
            target = ''
            try:
                from memory.conversations import get_store
                row = get_store().resume_target()
                if row and (row.get('messages') or []):
                    target = str(row.get('id') or '')
            except Exception:
                target = ''
            if not target:
                return False
            # Never open the chat panel just to restore history. If the window
            # does not exist yet the previous chat is queued and loads (faded)
            # the first time the panel is opened by the user.
            win = getattr(self, '_command_window', None)
            try:
                if win is not None:
                    win.windowTitle()
            except RuntimeError:
                win = None
            if win is None:
                self._pending_restore_conv = target
                self.write_log('SYS: previous conversation ready — loads when the chat panel opens.')
                return True
            restored = bool(win.restore_last_conversation(target))
            if restored:
                self.write_log('SYS: restored the last conversation.')
            return restored
        except Exception as exc:
            try:
                self.write_log(f'ERR: Chat history restore — {exc}')
            except Exception:
                pass
            return False

    def show_globe(self, places, source: str = "", focus: str = "") -> None:
        """Plot geospatial evidence on the globe and surface the card.

        Called both from the tool dispatch (a background thread) and from the
        UI thread; QtWebEngine will only accept the load from the GUI thread,
        so the work is marshalled there first.
        """
        def _plot():
            try:
                self._globe_pane.show_places(places, source=source)
                if focus and not self._globe_pane.focus_place(focus):
                    self.write_log(f"HoloGlobe: '{focus}' is not plotted.")
            except Exception as exc:
                self.write_log(f'HoloGlobe: could not plot — {exc}')
            self._set_panel_visible(self._globe_panel, True)
        if self._on_gui_thread():
            _plot()
        else:
            self.run_on_ui(_plot)

