def _skin_window(win):
    """Make Settings/utility windows visually match the main JARVIS surface."""
    if win is None:
        return
    try:
        win.setStyleSheet(f"""
            QWidget {{ background: transparent; color: {C.WHITE}; font-family: Rajdhani, Exo 2; }}
            QFrame {{ background: transparent; border: none; border-radius: 0; }}
            QLabel {{ background: transparent; border: none; }}
            QLineEdit, QTextEdit, QComboBox, QListWidget, QSpinBox, QDoubleSpinBox {{
                background: rgba(1,15,25,235); color: {C.WHITE};
                border: 1px solid rgba(88,214,245,62); border-radius: 8px; padding: 7px 10px;
            }}
            QLineEdit:hover, QTextEdit:hover, QComboBox:hover, QListWidget:hover, QSpinBox:hover, QDoubleSpinBox:hover {{
                border-color: rgba(88,214,245,120);
            }}
            QLineEdit:focus, QTextEdit:focus, QComboBox:focus, QListWidget:focus, QSpinBox:focus, QDoubleSpinBox:focus {{
                border-color: {C.PRI}; background: rgba(2,24,38,245);
            }}
            QPushButton {{
                background: rgba(1,15,25,210); color: {C.TEXT};
                border: 1px solid rgba(88,214,245,62); border-radius: 7px;
                padding: 7px 12px; font: 700 8pt "Exo 2"; letter-spacing: 1px;
            }}
            QPushButton:hover {{ color: {C.WHITE}; background: rgba(0,72,98,125); border-color: {C.PRI}; }}
            QPushButton:pressed {{ background: rgba(0,120,157,185); }}
            QTabWidget {{ background: transparent; }}
            QTabWidget::pane {{ border: none; background: transparent; }}
            QTabBar {{ background: transparent; }}
            QTabBar::tab {{
                background: rgba(1,15,25,210); color: {C.TEXT_DIM};
                border: 1px solid rgba(88,214,245,45); border-radius: 7px;
                padding: 8px 12px; margin: 2px 4px 4px 0; font: 700 8pt "Exo 2";
            }}
            QTabBar::tab:hover {{ color: {C.WHITE}; background: rgba(0,72,98,105); border-color: rgba(88,214,245,120); }}
            QTabBar::tab:selected {{ color: {C.WHITE}; background: rgba(0,92,124,135); border-color: {C.PRI}; }}
            QCheckBox {{ background: transparent; color: {C.TEXT_MED}; spacing: 8px; }}
            QGroupBox {{ background: transparent; border: none; margin-top: 10px; padding-top: 8px; }}
            QGroupBox::title {{ background: transparent; color: {C.PRI}; padding: 0 4px; font: 800 8pt "Orbitron"; }}
            QScrollBar:vertical {{ background: transparent; width: 6px; }}
            QScrollBar::handle:vertical {{ background: rgba(30,116,142,105); border-radius: 3px; min-height: 26px; }}
            QScrollBar::handle:vertical:hover {{ background: {C.PRI}; }}
            QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {{ height: 0; }}
        """)
        win.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
    except Exception:
        pass


def _open_full_settings_redesign(self):
    # Settings is now fully styled before show(); do not mutate the native
    # window surface again after it becomes visible.
    return _old_open_full_settings(self)

def _open_layout_editor_redesign(self):
    # The Studio styles itself (`composed_app_css` plus an opaque QMainWindow
    # background), so it is deliberately NOT re-skinned here. `_skin_window`
    # replaces the editor's stylesheet with a transparent one and sets
    # WA_TranslucentBackground on the live window, leaving it with no opaque
    # surface to paint — the blank/white Layout Studio window.
    return _old_open_layout_editor(self)

MainWindow._open_full_settings = _open_full_settings_redesign
MainWindow._open_layout_editor = _open_layout_editor_redesign


class _InertCall:
    """Callable / connectable / emittable no-op for a member of a dead window."""

    def __call__(self, *a, **k):
        return None

    def __getattr__(self, _name):
        return self

    def connect(self, *a, **k):
        return None

    def disconnect(self, *a, **k):
        return None

    def emit(self, *a, **k):
        return None


_INERT_CALL = _InertCall()


class _InertMainWindow:
    """Stands in for the MainWindow once it has been destroyed.

    The backend's asyncio tasks outlive the window by a beat and keep pushing
    state into it — ``set_state("LISTENING")`` after the last turn, log lines,
    activity rows. Touching a signal on the deleted C++ object raised
    ``RuntimeError: wrapped C/C++ object of type MainWindow has been deleted``,
    which is exactly the shutdown traceback that used to land in
    ``jarvis_startup_error.log`` on an otherwise clean exit. A finished session
    is not an error: reads return a harmless default and writes do nothing.
    """

    # Values that keep the backend quiet rather than accidentally "live".
    _muted = True
    _ready = False
    _features: dict = {}

    def __getattr__(self, name):
        if name.startswith('__') and name.endswith('__'):
            raise AttributeError(name)
        return _INERT_CALL


class JarvisUI:
    def __init__(self, face_path: str, size=None):
        try:
            from PyQt6.QtCore import Qt, QCoreApplication
            if not QApplication.instance():
                QCoreApplication.setAttribute(Qt.ApplicationAttribute.AA_ShareOpenGLContexts, True)
        except Exception:
            pass
        self._app=QApplication.instance() or QApplication(sys.argv)
        self._app.setStyle('Fusion')
        try:
            from ui_theme import tooltip_css as _tt_css
            self._app.setStyleSheet(
                _tt_css()
                + "QComboBox QAbstractItemView, QListView, QListWidget {"
                  "background:rgba(4,16,24,242); color:#dff4fb;"
                  "selection-background-color:rgba(0,180,230,70);"
                  "selection-color:#ffffff; border:1px solid rgba(10,134,184,120); }"
                + "QMenu { background:rgba(4,16,24,244); color:#dff4fb;"
                  "border:1px solid rgba(10,134,184,120); padding:4px; }"
                + f"QTextEdit#QuickChat {{ font-family: '{FONT_CHAT}'; }}"
                  f"QTabBar::tab {{ font-family: '{FONT_CHAT}'; }}")
        except Exception:
            pass
        cfg=_read_full_config(); fam=cfg.get('ui_font')
        if fam: self._app.setFont(QFont(fam,10))
        self._ui_gone = False
        self._win=MainWindow(face_path); self._win.show(); self.root=_RootShim(self._app)
        # Swap in an inert stand-in the moment the window dies, so whatever the
        # backend emits during shutdown is dropped instead of raising.
        try:
            self._win.destroyed.connect(self._on_window_destroyed)
        except Exception:
            pass

    def _on_window_destroyed(self, *_a):
        self._ui_gone = True
        self._win = _InertMainWindow()

    @property
    def muted(self): return self._win._muted
    @muted.setter
    def muted(self,v):
        if bool(v)!=self._win._muted: self._win._toggle_mute()
    @property
    def voice_input_enabled(self):
        # Explicitly False once the window is gone: the mic callback reads this
        # every block and must not treat a dead UI as "listening".
        win = getattr(self, '_win', None)
        return bool(getattr(win, 'voice_input_enabled', False)) if self._ui_alive() else False

    def feature_enabled(self, name: str) -> bool:
        return bool(self._win._features.get(name, True))
    @property
    def current_file(self): return self._win.current_file
    def __getattr__(self, name: str):
        if name.startswith('__') and name.endswith('__'):
            raise AttributeError(name)
        try:
            win = object.__getattribute__(self, '_win')
        except AttributeError:
            raise AttributeError(name)
        return getattr(win, name)

    def _ui_alive(self) -> bool:
        """Whether the MainWindow is still a live C++ object.

        ``_on_window_destroyed`` swaps ``_win`` for an inert stand-in, so this
        is a plain flag read rather than a probe of a possibly-deleted widget.
        Callers that do a meaningful chunk of work use it to bail out early;
        the inert window is the safety net underneath.
        """
        return not getattr(self, '_ui_gone', False)

    @property
    def on_text_command(self): return self._win.on_text_command
    @on_text_command.setter
    def on_text_command(self,cb): self._win.on_text_command=cb

    def begin_assistant_stream(self, who='J.A.R.V.I.S.'):
        return self._win.begin_assistant_stream(who)

    def stream_assistant_text(self, chunk):
        return self._win.stream_assistant_text(chunk)

    def finish_assistant_stream(self):
        return self._win.finish_assistant_stream()
    @property
    def on_remote_clicked(self): return self._win.on_remote_clicked
    @on_remote_clicked.setter
    def on_remote_clicked(self,cb): self._win.on_remote_clicked=cb
    @property
    def on_interrupt(self): return self._win.on_interrupt
    @on_interrupt.setter
    def on_interrupt(self,cb): self._win.on_interrupt=cb
    @property
    def on_voice_change(self): return self._win.on_voice_change
    @on_voice_change.setter
    def on_voice_change(self,cb): self._win.on_voice_change=cb
    @property
    def on_audio_device_change(self): return self._win.on_audio_device_change
    @on_audio_device_change.setter
    def on_audio_device_change(self,cb): self._win.on_audio_device_change=cb
    @property
    def on_ui_tars_mode_change(self): return self._win.on_ui_tars_mode_change
    @on_ui_tars_mode_change.setter
    def on_ui_tars_mode_change(self,cb): self._win.on_ui_tars_mode_change=cb
    def show_confirm(self,title,detail): self._win._confirm_sig.emit(str(title)[:120],str(detail)[:300])
    def hide_confirm(self): self._win._confirm_hide_sig.emit()
    def show_coding_approval(self,req_id,title,detail):
        self._win._coding_approval_sig.emit(str(req_id),str(title)[:160],str(detail)[:800])
    @property
    def get_plugins(self): return self._win.get_plugins
    @get_plugins.setter
    def get_plugins(self,cb): self._win.get_plugins=cb
    @property
    def request_say(self): return self._win.request_say
    @request_say.setter
    def request_say(self,cb): self._win.request_say=cb
    def run_on_ui(self, fn): return self._win.run_on_ui(fn)
    def call_on_ui(self, fn, timeout=15.0): return self._win.call_on_ui(fn, timeout=timeout)
    def _post(self, fn, *args, **kw):
        """Fire-and-forget a UI update coming from a background thread.

        The backend outlives the window at shutdown — its daemon threads are
        still finishing a turn when the HUD has already been destroyed — and
        emitting a signal on a deleted C++ object raises RuntimeError. That
        used to escape into JarvisLive.run() and be reported as a backend
        startup failure. An update that arrives after the window is gone has
        nowhere to go, so it is dropped instead of killing the process."""
        try:
            return fn(*args, **kw)
        except RuntimeError:
            return None

    def set_audio_level(self,level): self._post(self._win.set_audio_level, level)
    def set_speech_level(self,level): self._win.set_speech_level(level)
    def notify_phone_connected(self): self._win.notify_phone_connected()
    def show_repair_card(self, kind, payload=None):
        """Auto-heal telemetry -> repair card (marshalled onto the GUI thread)."""
        self._win.run_on_ui(lambda: self._win.show_repair_card(kind, payload))
    def show_globe(self, places, source='', focus=''):
        """Geospatial evidence -> HoloGlobe (marshalled onto the GUI thread)."""
        self._win.run_on_ui(lambda: self._win.show_globe(places, source=source, focus=focus))
    def clear_globe(self):
        """Remove every globe marker (marshalled onto the GUI thread)."""
        self._win.run_on_ui(lambda: self._win.clear_globe())
    def set_state(self,state): self._post(self._win._state_sig.emit, state)
    def write_log(self,text): self._post(self._win._log_sig.emit, text)
    def set_chat_activity(self, activity: str): self._post(self._win._chat_activity_sig.emit, str(activity or ''))
    def clear_chat_activity(self): self._post(self._win._chat_activity_sig.emit, '')
    def set_live_transcript(self, text: str, final: bool = False): self._post(self._win._live_transcript_sig.emit, str(text or ''), bool(final))
    def set_doing(self, category: str, detail: str): self._post(self._win.set_doing, category, detail)
    def set_laya_status(self, state: str, role: str = ''): self._post(self._win.set_laya_status, state, role)
    def set_mode_status(self, mode): self._post(self._win.set_mode_status, bool(mode))
    def clear_doing(self, category: str): self._post(self._win.clear_doing, category)
    def wait_for_api_key(self):
        # Must end when a full-close has begun — an unbreakable wait here was
        # one of the ways the backend thread survived its own shutdown and
        # left an invisible "already running" instance holding the mutex.
        # (If the window is destroyed the close path always sets shutdown,
        # so keying on the flag alone can never spin forever.)
        while not self._win._ready and not self._shutdown_started():
            time.sleep(0.1)

    @staticmethod
    def _shutdown_started() -> bool:
        try:
            from core import stability as _st
            return _st.shutdown_requested()
        except Exception:
            return False
    def show_content(self,title,text): self._post(self._win._content_sig.emit, title[:80], text[:12000])
    def show_image_url(self,url,caption='Research image'): self._win.show_image_url(url,caption)
    def show_image_path(self,path,caption='Generated image'): self._win.show_image_path(path,caption)
    def show_image_view(self,source=None,caption='',source_url=''): return self._win.show_image_view(source,caption,source_url)
    def show_video_view(self,source=None,caption='Video'): return self._win.show_video_view(source,caption)
    def show_web_video(self,url_or_query,caption='Web video'): return self._win.show_web_video(url_or_query,caption)
    @property
    def image_view_caption(self): return self._win.image_view_caption
    def prompt_reconfig(self): self._win._ready=False; self._win._reconfig_sig.emit()
    def show_camera_frame(self,img_bytes): self._win._camera_sig.emit(img_bytes)
    def start_camera_stream(self): self._win.start_camera_stream()
    def stop_camera_stream(self): self._win.stop_camera_stream()
    def warm_camera(self): self._win.warm_camera()
    def vision_scan_then_close(self, seconds: float = 2.4):
        self._win.vision_scan_then_close(seconds)
    def begin_vision_scan(self): self._win.begin_vision_scan()
    def end_vision_scan(self): self._win.end_vision_scan()
    def vision_scan_progress(self, stage: str, percent: int):
        # Called from the vision worker thread; the view marshals to the UI.  
        self._win.vision_scan_progress(stage, percent)

    @property
    def assistant_name(self): return self._win._assistant_name
    def start_speaking(self): self.set_state('SPEAKING')
    def stop_speaking(self):
        if not self.muted: self.set_state('LISTENING')